def _message_templates_for_language(options, language: str) -> dict[str, str]:
    """Resolve only overrides belonging to the concrete interface language."""

    grouped = getattr(options, "message_templates_by_language", {})
    if isinstance(grouped, dict):
        selected = grouped.get(language)
        if isinstance(selected, dict):
            return dict(selected)
    legacy = getattr(options, "message_templates", None)
    if language == i18n.POLISH and isinstance(legacy, dict):
        return dict(legacy)
    return {}
# Nazwa blokady pozostaje technicznie stabilna podczas przejścia z nazwy
# „AMC Python” na „AMC Test”. Dzięki temu także bezpośrednio uruchomiony
# frontend nie otworzy drugiej instancji obok starszej kompilacji.
INSTANCE_CHECKER_NAME = "AMC Python"


def _startup_smoke_mode() -> bool:
    """Czy trwa odizolowana, bezokienna bramka prawdziwego startu paczki."""

    return os.environ.get("AMC_STARTUP_SMOKE") == "1"


def _instance_checker_name() -> str:
    """Zwróć blokadę jednego okna osobną dla AMC i AMC Test.

    Uruchamiacz C# od początku rozdziela profile własnymi mutexami.  Drugi,
    wewnętrzny bezpiecznik wx również musi używać tożsamości profilu; inaczej
    publiczny AMC uznaje działający AMC Test za swoją poprzednią instancję i
    nie uruchamia hosta ani własnego magazynu danych.
    """

    return (
        f"{INSTANCE_CHECKER_NAME}-{current_profile().product_id}-"
        f"{wx.GetUserId()}"
    )
