    def _schedule_automatic_application_update_check(self) -> None:
        """Sprawdz raz po spokojnym starcie, bez przerywania pierwszego fokusu."""

        if (
            self._automatic_application_update_check_started
            or not self.options.application_check_automatically
        ):
            return
        self._automatic_application_update_check_started = True

        def start() -> None:
            if not self._window_alive():
                return
            if any(
                window is not self
                and window.IsShown()
                and callable(getattr(window, "IsModal", None))
                and bool(window.IsModal())
                for window in wx.GetTopLevelWindows()
            ):
                # Nie nakladaj drugiego modala na wybor sesji, Ustawienia ani
                # inne rozpoczęte działanie. Sprawdzenie nadal odbędzie się w
                # tym uruchomieniu, gdy użytkownik wróci do głównego okna.
                self._automatic_application_update_check_call = wx.CallLater(
                    5000, start
                )
                return
            self._check_application_update(automatic=True)

        self._automatic_application_update_check_call = wx.CallLater(
            5000, start
        )

    def _check_application_update(self, *, automatic: bool = False) -> None:
        if not automatic:
            scheduled = self._automatic_application_update_check_call
            if scheduled is not None and scheduled.IsRunning():
                scheduled.Stop()
            self._automatic_application_update_check_started = True
        if self._application_update_pending:
            if not automatic:
                self.announcer.say("Sprawdzanie lub pobieranie aktualizacji już trwa")
            return

        self._application_update_pending = True
        if not automatic:
            self.announcer.say("Sprawdzanie aktualizacji AMC")

        def done(check: ApplicationUpdateCheck) -> None:
            self._application_update_pending = False
            if automatic and not check.available:
                return
            dialog = ApplicationUpdateDialog(self, check)
            try:
                decision = dialog.ShowModal()
            finally:
                dialog.Destroy()
                self._restore_focus_after_dialog()
            if decision == wx.ID_OK and check.available:
                self._download_application_update(check)

        def failed(error: Exception) -> None:
            self._application_update_pending = False
            _append_frontend_log(
                self.store,
                "Sprawdzanie aktualizacji AMC nie powiodło się: "
                f"{type(error).__name__}: {error}",
            )
            if not automatic:
                self.announcer.say(user_facing_update_error(error))

        self.runner.submit(
            "application-update-check",
            check_for_application_update,
            done,
            failed,
        )

    def _download_application_update(self, check: ApplicationUpdateCheck) -> None:
        if self._application_update_pending:
            self.announcer.say("Sprawdzanie lub pobieranie aktualizacji już trwa")
            return

        self._application_update_pending = True
        self.announcer.say("Pobieranie i sprawdzanie aktualizacji AMC")

        def work() -> object:
            return prepare_application_update(check)

        def done(prepared: PreparedApplicationUpdate) -> None:
            self._application_update_pending = False
            try:
                launch_prepared_application_update(prepared)
            except Exception as error:  # noqa: BLE001 - szczegoly tylko do logu
                _append_frontend_log(
                    self.store,
                    "Uruchomienie aktualizatora AMC nie powiodło się: "
                    f"{type(error).__name__}: {error}",
                )
                self.announcer.say(user_facing_update_error(error))
                return
            self.announcer.say(
                "Aktualizacja jest gotowa. AMC zamknie się bezpiecznie, "
                "zainstaluje nową wersję i uruchomi ponownie"
            )

        def failed(error: Exception) -> None:
            self._application_update_pending = False
            _append_frontend_log(
                self.store,
                "Pobieranie aktualizacji AMC nie powiodło się: "
                f"{type(error).__name__}: {error}",
            )
            self.announcer.say(user_facing_update_error(error))

        self.runner.submit("application-update-download", work, done, failed)

    def _update_media_components(
        self,
        *,
        automatic: bool = False,
        on_complete: Callable[[dict[str, object]], None] | None = None,
    ) -> bool:
        if self._component_update_pending:
            if not automatic:
                self.announcer.say("Aktualizacja składników już trwa")
            if on_complete is not None:
                on_complete({
                    "success": False,
                    "message": "Aktualizacja składników już trwa.",
                })
            return False
        client = self.client
        if client is None or not client.alive:
            if not automatic:
                self.announcer.say(
                    "Silnik nie działa, nie mogę zaktualizować składników"
                )
            if on_complete is not None:
                on_complete({
                    "success": False,
                    "message": (
                        "Silnik AMC nie działa, dlatego nie można sprawdzić "
                        "składników."
                    ),
                })
            return False

        self._component_update_pending = True
        if not automatic:
            self.announcer.say("Sprawdzanie składników FFmpeg i yt-dlp")

        def work() -> object:
            kwargs: dict[str, object] = {"automatic": automatic}
            options = getattr(self, "options", None)
            check_automatically = getattr(
                options, "component_check_automatically", None
            )
            download_automatically = getattr(
                options, "component_download_automatically", None
            )
            if check_automatically is not None:
                kwargs["check_automatically"] = check_automatically
            if download_automatically is not None:
                kwargs["download_automatically"] = download_automatically
            return client.update_media_components(**kwargs)

        def done(payload: object) -> None:
            self._component_update_pending = False
            data = payload if isinstance(payload, dict) else {}
            performed = bool(data.get("performed"))
            success = bool(data.get("success"))
            changed = bool(data.get("changed"))
            complete = bool(data.get("complete"))
            message = str(data.get("message") or "").strip()
            if on_complete is not None:
                on_complete(data)
            if automatic and not performed:
                return
            if automatic and success and complete and not changed:
                return
            if automatic and success and changed:
                lead = "Zaktualizowano składniki multimedialne"
            elif success and complete:
                lead = "Składniki multimedialne są gotowe"
            elif success:
                lead = "Składniki multimedialne nie są jeszcze kompletne"
            else:
                lead = "Nie udało się bezpiecznie zaktualizować składników"
            self.announcer.say(f"{lead}. {message}" if message else lead)

        def failed(error: Exception) -> None:
            self._component_update_pending = False
            _append_frontend_log(
                self.store,
                "Aktualizacja składników nie powiodła się: "
                f"{type(error).__name__}: {error}",
            )
            if not automatic:
                self.announcer.say(
                    "Nie udało się bezpiecznie zaktualizować składników. "
                    "Szczegóły zapisano w dzienniku AMC"
                )
            if on_complete is not None:
                on_complete({
                    "success": False,
                    "message": f"Nie udało się sprawdzić składników: {error}",
                })

        self.runner.submit("component-update", work, done, failed)
        return True

    @staticmethod
    def _common_data_summary(payload: object) -> str:
        data = payload if isinstance(payload, dict) else {}
        state = str(data.get("state") or "unknown")
        if state == "missing" or not data.get("available"):
            return "Nie ma jeszcze danych z AMC Test"
        state_label = {
            "exported": "migawka przygotowana",
            "available": "migawka dostępna",
            "ready": "dane gotowe do odświeżenia",
            "imported": "dane odświeżone",
            "current": "dane są aktualne",
            "conflict": "AMC Public ma własne zmiany",
        }.get(state, "stan danych odczytany")
        ticks = int(data.get("createdUtcTicks") or 0)
        created = ""
        if ticks >= 621355968000000000:
            try:
                seconds = (ticks - 621355968000000000) / 10_000_000
                created = datetime.fromtimestamp(seconds).astimezone().strftime(
                    "%d.%m.%Y, %H:%M"
                )
            except (OSError, OverflowError, ValueError):
                created = ""
        counts = (
            f"pliki {int(data.get('localFiles') or 0)}, "
            f"stacje {int(data.get('radioStations') or 0)}, "
            f"źródła podcastów i YouTube {int(data.get('podcastSources') or 0)}, "
            f"odcinki {int(data.get('podcastEpisodes') or 0)}, "
            f"zakładki {int(data.get('bookmarks') or 0)}, "
            f"harmonogramy {int(data.get('recordingSchedules') or 0)}"
        )
        when = f" z {created}" if created else ""
        return f"{state_label}. Migawka{when}. {counts}"

    def _show_common_data_status(self) -> None:
        client = self._profile_edit_client()
        if client is None:
            return
        self.runner.submit(
            "common-data-status",
            client.common_data_snapshot_status,
            lambda payload: self.announcer.say(self._common_data_summary(payload)),
            lambda error: self.announcer.say(
                f"Nie można odczytać stanu danych: {error}"
            ),
        )

    def _refresh_common_data_from_test(self) -> None:
        if current_profile().profile_id != "public":
            self.announcer.say("Dane z AMC Test odświeża AMC Public")
            return
        client = self._profile_edit_client()
        if client is None:
            return

        def checked(payload: object) -> None:
            data = payload if isinstance(payload, dict) else {}
            state = str(data.get("state") or "")
            if state == "missing":
                self.announcer.say("Nie ma jeszcze danych z AMC Test")
                return
            if state == "current":
                self.announcer.say(self._common_data_summary(data))
                return
            if state == "conflict":
                answer = wx.MessageBox(
                    "AMC Public ma własne zmiany od poprzedniego odświeżenia. "
                    "Czy zastąpić zgodne dane danymi z AMC Test? Ustawienia, "
                    "konta i bieżący widok pozostaną bez zmian.",
                    "Odśwież dane z AMC Test",
                    wx.YES_NO | wx.NO_DEFAULT | wx.ICON_QUESTION,
                    self,
                )
                self._restore_focus_after_dialog()
                if answer != wx.YES:
                    self.announcer.say("Zachowano dane AMC Public")
                    return
                self._import_common_data(accept_test_data=True)
                return
            self._import_common_data(accept_test_data=False)

        self.runner.submit(
            "common-data-status",
            client.common_data_snapshot_status,
            checked,
            lambda error: self.announcer.say(
                f"Nie można odświeżyć danych: {error}"
            ),
        )

    def _import_common_data(self, *, accept_test_data: bool) -> None:
        client = self._profile_edit_client()
        if client is None:
            return
        preferred_id = self.navigator.session.model.selected_id

        def done(payload: object) -> None:
            data = payload if isinstance(payload, dict) else {}
            search_history_saved = True
            search_history = data.get("searchHistory")
            if isinstance(search_history, dict):
                self.state.search_history = {
                    str(scope): [str(query) for query in queries if str(query).strip()]
                    for scope, queries in search_history.items()
                    if isinstance(scope, str) and isinstance(queries, list)
                }
                if self._save_state() is False:
                    search_history_saved = False
            # Ponowne otwarcie TEGO SAMEGO widoku zachowuje Id fokusu. Jezeli
            # element zniknal, model wybiera najblizszy prawidlowy wiersz.
            self._refresh_profile_view(preferred_id=preferred_id)
            message = "Odświeżono dane z AMC Test. " + self._common_data_summary(payload)
            if not search_history_saved:
                message += ". Nie zapisano historii wyszukiwania interfejsu"
            self.announcer.say(message)

        self.runner.submit(
            "common-data-import",
            lambda: client.import_common_data_snapshot(
                accept_test_data=accept_test_data
            ),
            done,
            lambda error: self.announcer.say(f"Nie odświeżono danych: {error}"),
        )

    @staticmethod
    def _backup_summary(payload: object) -> str:
        data = payload if isinstance(payload, dict) else {}
        return (
            f"pliki {int(data.get('localFiles') or 0)}, "
            f"stacje {int(data.get('radioStations') or 0)}, "
            f"źródła podcastów i YouTube {int(data.get('podcastSources') or 0)}, "
            f"odcinki {int(data.get('podcastEpisodes') or 0)}, "
            f"zakładki {int(data.get('bookmarks') or 0)}, "
            f"playlisty {int(data.get('playlists') or 0)}, "
            f"harmonogramy {int(data.get('recordingSchedules') or 0)}"
        )

    def _choose_backup_scope(self):
        labels = [scope.label for scope in BACKUP_SCOPES]
        with wx.SingleChoiceDialog(
            self,
            "Wybierz zakres danych. Strzałki zmieniają wybór, Enter "
            "zatwierdza, a Escape anuluje.",
            "Eksportuj dane AMC",
            labels,
        ) as dialog:
            dialog.SetName("Wybierz zakres eksportu danych AMC")
            dialog.SetSelection(0)
            pending = list(dialog.GetChildren())
            while pending:
                child = pending.pop()
                if isinstance(child, (wx.Choice, wx.ListBox)):
                    child.SetName("Zakres eksportu danych AMC")
                pending.extend(child.GetChildren())
            if dialog.ShowModal() != wx.ID_OK:
                self._restore_focus_after_dialog()
                return None
            selected = dialog.GetSelection()
        self._restore_focus_after_dialog()
        if selected < 0 or selected >= len(BACKUP_SCOPES):
            return None
        return BACKUP_SCOPES[selected]

    def _export_backup(self) -> None:
        client = self._profile_edit_client()
        if client is None:
            return
        scope = self._choose_backup_scope()
        if scope is None:
            self.announcer.say("Anulowano eksport danych AMC")
            return
        if not self._save_state():
            return
        with wx.FileDialog(
            self,
            f"Eksportuj: {scope.label}",
            wildcard=scope.wildcard,
            defaultFile=scope.default_file_name(),
            style=wx.FD_SAVE | wx.FD_OVERWRITE_PROMPT,
        ) as dialog:
            if dialog.ShowModal() != wx.ID_OK:
                self._restore_focus_after_dialog()
                return
            target = Path(dialog.GetPath())
        self._restore_focus_after_dialog()
        staged = full_backup_staging_path(target)

        def work() -> object:
            result = client.export_backup(staged, list(scope.sections))
            complete_full_backup_export(
                staged,
                target,
                profile_id=current_profile().profile_id,
                ui_state_path=self.store.path,
                sections=scope.sections,
            )
            return result

        def cleanup_staged() -> None:
            try:
                staged.unlink(missing_ok=True)
            except OSError:
                pass

        def done(payload: object) -> None:
            self.Enable(True)
            self._restore_focus_after_dialog()
            cleanup_staged()
            self.announcer.say(
                f"Wyeksportowano {describe_backup_sections(scope.sections)}: "
                f"{target.name}. "
                + self._backup_summary(payload)
                + ". Hasła i tokeny nie zostały zapisane"
            )

        def failed(error: Exception) -> None:
            self.Enable(True)
            self._restore_focus_after_dialog()
            cleanup_staged()
            self.announcer.say(f"Nie wyeksportowano danych AMC: {error}")

        self.Enable(False)
        self.announcer.say("Eksportuję dane AMC")
        self.runner.submit("profile-backup-export", work, done, failed)

    def _import_backup(self) -> None:
        client = self._profile_edit_client()
        if client is None:
            return
        if not self._save_state():
            return
        with wx.FileDialog(
            self,
            "Importuj dane AMC",
            wildcard=IMPORT_WILDCARD,
            style=wx.FD_OPEN | wx.FD_FILE_MUST_EXIST,
        ) as dialog:
            if dialog.ShowModal() != wx.ID_OK:
                self._restore_focus_after_dialog()
                return
            path = Path(dialog.GetPath())
        self._restore_focus_after_dialog()

        def inspect_work():
            plan = inspect_full_backup_import(
                path,
                expected_profile_id=current_profile().profile_id,
                state_store=self.store,
            )
            inspected = client.inspect_backup(path)
            data = inspected if isinstance(inspected, dict) else {}
            host_sections = normalize_backup_sections(data.get("sections"))
            if host_sections != plan.included_sections:
                raise FullBackupError(
                    "Rdzeń i interfejs AMC rozpoznały różny zakres kopii."
                )
            return plan

        def inspected(plan) -> None:
            self.Enable(True)
            description = describe_backup_sections(plan.included_sections)
            answer = wx.MessageBox(
                f"Kopia zawiera: {description}. Import zastąpi wyłącznie te "
                "dane w bieżącym profilu. Pozostałe dane zostaną zachowane. "
                "Hasła i tokeny nie są importowane. Przed zmianą AMC utworzy "
                "kopię ratunkową. Po udanym imporcie program zostanie "
                "zamknięty; uruchom go ponownie. Czy kontynuować?",
                "Importuj dane AMC",
                wx.YES_NO | wx.NO_DEFAULT | wx.ICON_QUESTION,
                self,
            )
            self._restore_focus_after_dialog()
            if answer != wx.YES:
                self.announcer.say("Anulowano import danych AMC")
                return
            self._start_backup_import(client, path, plan)

        def inspection_failed(error: Exception) -> None:
            self.Enable(True)
            self._restore_focus_after_dialog()
            self.announcer.say(f"Nie można zaimportować danych AMC: {error}")

        self.Enable(False)
        self.announcer.say("Sprawdzam kopię danych AMC")
        self.runner.submit(
            "profile-backup-inspect",
            inspect_work,
            inspected,
            inspection_failed,
        )

    def _start_backup_import(self, client, path: Path, plan) -> None:
        rescue = full_backup_rollback_path(self.store.directory)
        rescue_stage = full_backup_staging_path(rescue)

        def cleanup(path_to_remove: Path) -> None:
            try:
                path_to_remove.unlink(missing_ok=True)
            except OSError:
                pass

        def work():
            imported_state = build_imported_ui_state(plan, self.store)
            rescue_ready = False
            try:
                client.export_backup(rescue_stage, list(ALL_SECTIONS))
                complete_full_backup_export(
                    rescue_stage,
                    rescue,
                    profile_id=current_profile().profile_id,
                    ui_state_path=self.store.path,
                    sections=ALL_SECTIONS,
                )
                rescue_ready = True
                try:
                    payload = client.import_backup(
                        path, list(plan.included_sections)
                    )
                except Exception as import_error:
                    try:
                        client.import_backup(rescue, list(ALL_SECTIONS))
                    except Exception as rollback_error:
                        raise FullBackupError(
                            "Import nie powiódł się i nie udało się "
                            "automatycznie przywrócić danych. Kopię ratunkową "
                            "zachowano w folderze danych profilu."
                        ) from rollback_error
                    cleanup(rescue)
                    rescue_ready = False
                    raise FullBackupError(
                        "Import nie powiódł się. Poprzednie dane zostały "
                        "przywrócone."
                    ) from import_error
                try:
                    self.store.save(imported_state)
                except Exception as state_error:
                    try:
                        client.import_backup(rescue, list(ALL_SECTIONS))
                    except Exception as rollback_error:
                        raise FullBackupError(
                            "Nie zapisano ustawień interfejsu i nie udało się "
                            "automatycznie przywrócić danych. Kopię ratunkową "
                            "zachowano w folderze danych profilu."
                        ) from rollback_error
                    cleanup(rescue)
                    rescue_ready = False
                    raise FullBackupError(
                        "Nie zapisano ustawień interfejsu. Poprzednie dane "
                        "zostały przywrócone."
                    ) from state_error
                cleanup(rescue)
                rescue_ready = False
                return payload, imported_state
            finally:
                cleanup(rescue_stage)
                if not rescue_ready:
                    cleanup(rescue)

        def done(result) -> None:
            self.Enable(True)
            payload, imported_state = result
            self.state = imported_state
            self.options = imported_state.options
            suffix = (
                " Przywrócono także ustawienia interfejsu."
                if plan.has_ui_state
                else " To starsza kopia; zachowano obecne ustawienia interfejsu."
            )
            wx.MessageBox(
                f"Zaimportowano {describe_backup_sections(plan.included_sections)}. "
                + self._backup_summary(payload)
                + "."
                + suffix
                + " Program zostanie teraz zamknięty; uruchom go ponownie.",
                "Import zakończony",
                wx.OK | wx.ICON_INFORMATION,
                self,
            )
            self.Close()

        def failed(error: Exception) -> None:
            self.Enable(True)
            self._restore_focus_after_dialog()
            self.announcer.say(f"Nie zaimportowano danych AMC: {error}")

        self.Enable(False)
        self.announcer.say("Importuję dane AMC")
        self.runner.submit(
            "profile-backup-import",
            work,
            done,
            failed,
        )

    # ---------------------------------------------------- wykonanie zamiarow

    def _run(self, intents: list[object]) -> None:
        """Wykonaj zamiary zwrocone przez Navigator. To JEDYNE miejsce, w
        ktorym logika nawigacji spotyka wx."""
        announcements_after_empty_update: list[str] = []
        for intent in intents:
            if isinstance(intent, Announce):
                # Pusta natywna lista nie ma wiersza do przeczytania. Najpierw
                # kończymy jej aktualizację, dopiero potem mówimy wynik. Dzięki
                # temu systemowy stan usuwanego dziecka nie dopisuje na końcu
                # słowa „nieznane”.
                if (
                    intent.text.strip().casefold() == "zero elementów"
                    and self.navigator.session.view is View.LIST
                    and self.navigator.session.model.selected_row is None
                ):
                    announcements_after_empty_update.append(intent.text)
                else:
                    self.announcer.say(intent.text)
            elif isinstance(intent, OpenFolder):
                # Gdy Biblioteka jest dostepna, wchodzenie w foldery czyta
                # SQLite, a nie dysk -- sciezki profilu moga tu nie istniec.
                if self.library.is_available:
                    self._open_library(intent.path or None, preferred_id=intent.preferred_id)
                else:
                    self._open_folder(intent.path, preferred_id=intent.preferred_id)
            elif isinstance(intent, OpenLibraryView):
                self._open_library_view(intent)
            elif isinstance(intent, OpenQueueView):
                self._open_queue_view()
            elif isinstance(intent, OpenRadioarchiwistaStations):
                self._open_radioarchiwista_stations(
                    intent.preferred_id, refresh=intent.refresh
                )
            elif isinstance(intent, OpenRadioarchiwistaLevel):
                self._open_radioarchiwista_level(intent)
            elif isinstance(intent, OpenRadioarchiwistaLatest):
                self._open_radioarchiwista_latest(refresh=intent.refresh)
            elif isinstance(intent, OpenPodcastView):
                self._open_podcast_view(intent)
            elif isinstance(intent, OpenYouTubeBroadcasts):
                self._open_youtube_broadcasts(intent)
            elif isinstance(intent, OpenPodcastAggregateView):
                self._open_podcast_aggregate(intent)
            elif isinstance(intent, OpenPodcastPlaylistView):
                self._open_podcast_playlist_view(intent)
            elif isinstance(intent, OpenSpotifyView):
                self._open_spotify_view(intent)
            elif isinstance(intent, OpenSpotifyCollectionView):
                self._open_spotify_collection_view(intent)
            elif isinstance(intent, OpenSpotifyContainer):
                self._open_spotify_container(intent)
            elif isinstance(intent, OpenTidalView):
                self._open_tidal_view(intent)
            elif isinstance(intent, OpenTidalContainer):
                self._open_tidal_container(intent)
            elif isinstance(intent, OpenSonosView):
                self._open_sonos_view(intent)
            elif isinstance(intent, OpenSonosAccount):
                self._show_sonos_account()
            elif isinstance(intent, ShowTidalRelations):
                self._show_tidal_relations(intent)
            elif isinstance(intent, ShowSpotifyRelations):
                self._show_spotify_relations(intent)
            elif isinstance(intent, PlayTrack):
                self._play_track(intent)
            elif isinstance(intent, PlayFromQueue):
                self._play_from_queue(intent)
            elif isinstance(intent, PlayQueueAt):
                self._play_queue_at(intent)
            elif isinstance(intent, PlayStation):
                self._play_station(intent)
            elif isinstance(intent, PlayMedia):
                if self.navigator.active is SessionId.RADIOARCHIWISTA:
                    self._play_media(intent, session_id=SessionId.RADIOARCHIWISTA)
                else:
                    self._play_media(intent)
            elif isinstance(intent, PlayTidalTrack):
                self._play_tidal_track(intent)
            elif isinstance(intent, PlayTidalContainer):
                self._play_tidal_container(intent)
            elif isinstance(intent, PlaySpotifyItem):
                self._play_spotify(intent)
            elif isinstance(intent, ActivateWiiMDevice):
                self._activate_wiim_device(intent)
            elif isinstance(intent, ActivateFrontierSmartDevice):
                self._activate_frontier_smart_device(intent)
            elif isinstance(intent, PlayWiiMNetworkStream):
                self._activate_wiim_network_stream(intent)
            elif isinstance(intent, OpenWiiMDevicePresets):
                self._show_wiim_presets()
            elif isinstance(intent, OpenWiiMNetworkStreams):
                self._show_wiim_network_streams()
            elif isinstance(intent, ActivateSonosGroup):
                self._activate_sonos_group(intent)
            elif isinstance(intent, PlaySonosMaterial):
                self._play_sonos_material(intent)
        self._sync_views()
        for text in announcements_after_empty_update:
            self._announce_after_native_list_update(text)

    @staticmethod
    def _view_history_fingerprint(
        snapshot: TransientNavigationSnapshot,
    ) -> tuple[object, ...]:
        tidal = snapshot.tidal_context
        spotify = snapshot.spotify_context
        return (
            snapshot.session_id,
            snapshot.view,
            snapshot.folder_path,
            snapshot.library_view,
            snapshot.library_playlist_id,
            snapshot.library_item_id,
            snapshot.tidal_heading,
            getattr(tidal, "service_id", None),
            getattr(tidal, "kind", None),
            getattr(tidal, "artist_section", None),
            snapshot.spotify_heading,
            getattr(spotify, "service_id", None),
            getattr(spotify, "kind", None),
            getattr(spotify, "section", None),
            snapshot.wiim_device_return_id,
            snapshot.wiim_streams_return_to_sources,
        )

    def _track_view_history(self) -> None:
        if not hasattr(self, "_view_history_current"):
            return
        current = self.navigator.capture_transient_navigation()
        if self._restoring_view_history:
            self._view_history_current = current
            self._restoring_view_history = False
            return
        previous = self._view_history_current
        if self._view_history_fingerprint(current) != self._view_history_fingerprint(previous):
            self._view_history_back.append(previous)
            del self._view_history_back[:-100]
            self._view_history_forward.clear()
        self._view_history_current = current

    def _navigate_view_history(self, *, back: bool) -> None:
        source = self._view_history_back if back else self._view_history_forward
        destination = self._view_history_forward if back else self._view_history_back
        if not source:
            self.announcer.say(
                "Brak wcześniejszego widoku" if back else "Brak następnego widoku"
            )
            return
        current = self.navigator.capture_transient_navigation()
        target = source.pop()
        destination.append(current)
        del destination[:-100]
        self._restoring_view_history = True
        self.navigator.restore_transient_navigation(target)
        self._sync_views()

    def _sync_views(self) -> None:
        """Odwzoruj stan nawigatora. Fokus ruszamy TYLKO przy zmianie widoku."""
        self._track_view_history()
        self._apply_native_playback_activity_status(self.navigator.active)
        session = self.navigator.session
        # Menu musi zgadzac sie z kontekstem, ktory wlasnie sie zmienil.
        if (
            hasattr(self, "_menu_items")
            and getattr(self, "_menu_session", self.navigator.active)
            is not self.navigator.active
        ):
            self._build_menu()
        else:
            self._refresh_menu_state()
        self.session_label.SetLabel(i18n.ui_text({
            SessionId.FILES: "Pliki lokalne",
            SessionId.RADIO: "Radio",
            SessionId.PODCASTS: "Podcasty i YouTube",
            SessionId.TIDAL: "TIDAL",
            SessionId.SPOTIFY: "Spotify",
            SessionId.WIIM: "WiiM",
            SessionId.SONOS: "Sonos",
            SessionId.FRONTIER_SMART: "Frontier Smart",
            SessionId.RADIOARCHIWISTA: "Radio Archiwista",
        }[self.navigator.active]))

        active_list = self._active_list()
        # Jawna, użytkowa nazwa BIEŻĄCEGO widoku. Model nadal przechowuje enum,
        # lecz NVDA nigdy go nie zobaczy; pozycję i licznik czyta natywna lista.
        view_label = {
            LibraryView.ALL_FILES: "Wszystkie pliki",
            LibraryView.FAVORITES: "Ulubione",
            LibraryView.PLAYLISTS: "Playlisty",
            LibraryView.PLAYLIST_CONTENTS: "Playlista",
            LibraryView.HISTORY: "Historia odtwarzania",
            LibraryView.SAVED_QUEUE: "Zapisana kolejka",
            LibraryView.LIVE_QUEUE: "Kolejka odtwarzania",
            LibraryView.ITEM_BOOKMARKS: "Zakładki",
            LibraryView.ACTIVE_RADIO_RECORDINGS: "Nagrywane",
            LibraryView.RECORDED_RADIO_FILES: "Historia nagrywania",
            LibraryView.RADIO_RECORDING_SCHEDULES: "Harmonogramy nagrywania",
            LibraryView.SONOS_LIBRARY: "Biblioteka Sonos",
            LibraryView.SONOS_FAVORITES: "Ulubione Sonos",
            LibraryView.SONOS_PLAYLISTS: "Playlisty Sonos",
            LibraryView.SONOS_OWN_STREAMS: "Moje stacje Sonos",
            LibraryView.SPOTIFY_LIBRARY: "Biblioteka Spotify",
            LibraryView.SPOTIFY_CONTAINER: session.spotify_heading,
            LibraryView.SPOTIFY_HISTORY: "Spotify — Historia odtwarzania",
            LibraryView.YOUTUBE_BROADCASTS: "Transmisje YouTube na żywo i zaplanowane",
            LibraryView.YOUTUBE_BROADCASTS_AGGREGATE: (
                "Transmisje wybranych kanałów YouTube"
            ),
            LibraryView.SERVICE_HISTORY: (
                f"{SESSION_LABELS[self.navigator.active]} — Historia odtwarzania"
            ),
        }.get(
            session.library_view,
            getattr(active_list, "_base_accessible_label", None),
        )
        if view_label is not None:
            set_accessible_label = getattr(active_list, "set_accessible_label", None)
            if callable(set_accessible_label):
                set_accessible_label(view_label)
        all_lists = tuple(
            candidate for candidate in (
                getattr(self, "files_list", None),
                getattr(self, "radio_list", None),
                getattr(self, "podcasts_list", None),
                getattr(self, "tidal_list", None),
                getattr(self, "spotify_list", None),
                getattr(self, "wiim_list", None),
                getattr(self, "sonos_list", None),
                getattr(self, "frontier_smart_list", None),
                getattr(self, "radioarchiwista_list", None),
            )
            if candidate is not None
        )
        other_lists = tuple(control for control in all_lists if control is not active_list)
        # FILTR TEGO WIDOKU przywracamy PRZED ``sync_rows``, bo on wlasnie
        # liczy stan zadany listy. Port ``RestoreFilterForCurrentView``
        # (MainWindow.xaml.cs:10196-10204): wejscie w widok oddaje jego wlasny
        # tekst filtra, a nie tekst widoku, z ktorego przyszlismy.
        self._restore_filter_for_current_view()
        # JEDNA droga odswiezenia dla WSZYSTKICH widokow, bez wymiany kontrolki.
        # ``sync_rows`` sam decyduje, czy jest co robic: gdy dane, kolejnosc,
        # teksty i kursor sa te same, nie wykonuje ZADNEJ operacji na liscie.
        # Dlatego wolanie go na koncu kazdego ``_run`` (takze po samym
        # komunikacie czy Ctrl+C) nie odswieza juz listy bez potrzeby.
        #
        # Rekreacja kontrolki (nowy HWND dla czystego cache czytnika) byla tu
        # przez chwile i ZOSTALA WYCOFANA PO POMIARZE. Usuwala wprawdzie stara
        # nazwe z nowym licznikiem, ale na glownym widoku (2476 wierszy)
        # czytnik przestawal mowic wybrany wiersz w ogole -- slychac bylo tylko
        # naglowek widoku. Kwity: ``przed-po-przed.json`` (stary kod, wiersz
        # czytany) vs ``przed-po-po.json`` (z rekreacja, cisza) oraz para
        # ``odbior-listy-Z-REKREACJA.json`` / ``odbior-listy-BEZ-REKREACJI.json``.
        # Siedem prob ratowania rekreacji (kolejnosc fokus/wypelnienie, obrot
        # petli, podwojny ``SetFocus``, wymuszony ``SetItemState``, kolejnosc
        # ``Destroy``, zdjecie nakladki) nie przywrocilo tego odczytu.
        # Problem "stara nazwa z nowym licznikiem" rozwiazuje teraz sama zmiana
        # na zwykla liste: tekst siedzi w kontrolce, a nie w cache wirtualnym,
        # wiec stara nazwa nie ma skad wrocic.
        # Po powrocie z Total Commandera/Explorera shell mogl juz wykonac
        # przeniesienie przygotowane przez Ctrl+X. Baza pelnego AMC jest dla
        # tego interfejsu tylko do odczytu, wiec filtr procesu zapobiega
        # ponownemu pokazaniu wiersza do czasu nastepnego uruchomienia/skanu.
        self._hide_completed_external_moves_from_files_model()
        active_list.sync_rows()

        want_player = session.view is View.PLAYER
        changed = self.player_panel.IsShown() != want_player or any(
            control.IsShown() for control in other_lists
        )

        self.list_panel.Show(not want_player)
        self.player_panel.Show(want_player)
        active_list.Show(not want_player)
        for control in other_lists:
            control.Hide()
        self.panel.Layout()

        # Dzwiek TIDALa nie przechodzi przez AMC. Pozostawienie aktywnych
        # suwakow glosnosci i tempa zmienialoby ukryty lokalny silnik, choc
        # uzytkownik jest w odtwarzaczu TIDAL. Przycisk gra/pauza pozostaje
        # aktywny, bo jest jawnie kierowany do sesji systemowej TIDALa.
        tidal_external = self.navigator.active is SessionId.TIDAL
        spotify_read_only = self.navigator.active is SessionId.SPOTIFY
        wiim_remote = self.navigator.active is SessionId.WIIM
        sonos_remote = self.navigator.active is SessionId.SONOS
        frontier_smart_remote = (
            self.navigator.active is SessionId.FRONTIER_SMART
        )
        wiim_ready = (
            not wiim_remote
            or bool(self._wiim_snapshot)
            and self._wiim_snapshot.get("deviceId")
            == self._wiim_active_device_id
        )
        sonos_ready = (
            not sonos_remote
            or bool(self._sonos_snapshot)
            and self._sonos_snapshot.get("groupId")
            == self._sonos_active_group_id
        )
        sonos_volume = (
            sonos_ready
            and self._sonos_snapshot.get("fixedVolume") is not True
            and self._sonos_snapshot.get("volume") is not None
        )
        frontier_smart_ready = (
            not frontier_smart_remote
            or bool(self._frontier_smart_snapshot)
            and self._frontier_smart_snapshot.get("deviceId")
            == self._frontier_smart_active_device_id
        )
        frontier_smart_volume = (
            frontier_smart_ready
            and self._frontier_smart_snapshot.get("volume") is not None
        )
        self.volume_slider.Enable(
            not (tidal_external or spotify_read_only) and wiim_ready
            and (not sonos_remote or sonos_volume)
            and (not frontier_smart_remote or frontier_smart_volume)
        )
        self.rate_choice.Enable(not (
            tidal_external
            or spotify_read_only
            or wiim_remote
            or sonos_remote
            or frontier_smart_remote
        ))

        if want_player:
            if wiim_remote and self._wiim_snapshot:
                self._apply_wiim_snapshot(self._wiim_snapshot, announce=False)
            elif sonos_remote and self._sonos_snapshot:
                self._apply_sonos_snapshot(self._sonos_snapshot, announce=False)
            elif frontier_smart_remote and self._frontier_smart_snapshot:
                self._apply_frontier_smart_snapshot(
                    self._frontier_smart_snapshot,
                    announce=False,
                )
            else:
                self.now_playing.SetLabel(
                    session.now_playing_title or "Nic nie jest odtwarzane"
                )
            if self.navigator.active is SessionId.RADIO:
                # F6 najpierw oglasza wejscie do odtwarzacza. Natychmiast potem
                # przywracamy z ostatniej migawki wlasciwa tresc NVDA+End.
                self._update_native_playback_status(self._last_status)
            if changed:
                self.play_button.SetFocus()
        elif changed:
            active_list.SetFocus()

    def _active_list(self) -> MediaListCtrl:
        # Galazie zamiast slownika: testy logiki buduja lekkie okno tylko z
        # kontrolkami sesji, ktora sprawdzaja. Slownik obliczalby wszystkie
        # wartosci z gory i pytal o ``podcasts_list`` nawet przy sesji Plikow.
        if self.navigator.active is SessionId.FILES:
            return self.files_list
        if self.navigator.active is SessionId.RADIO:
            return self.radio_list
        if self.navigator.active is SessionId.PODCASTS:
            return self.podcasts_list
        if self.navigator.active is SessionId.SPOTIFY:
            return self.spotify_list
        if self.navigator.active is SessionId.WIIM:
            return self.wiim_list
        if self.navigator.active is SessionId.SONOS:
            return self.sonos_list
        if self.navigator.active is SessionId.FRONTIER_SMART:
            return self.frontier_smart_list
        if self.navigator.active is SessionId.RADIOARCHIWISTA:
            return self.radioarchiwista_list
        return self.tidal_list

    def _on_item_focused(self, event: wx.ListEvent) -> None:
        """Fokus jest kotwica akcji takze wtedy, gdy wiersz nie jest wybrany.

        To natywny etap windowsowego wyboru nieprzylegajacego:
        Ctrl+strzalka przesuwa fokus bez kasowania dotychczasowych zaznaczen,
        a Ctrl+Spacja przelacza dopiero ten wiersz. Model przechowuje jedno ID
        wlasnie jako kotwice nawigacji; pelny zbior zaznaczen nadal pozostaje
        w SysListView32 i nie jest tu kopiowany ani emulowany.
        """
        control = event.GetEventObject()
        if not isinstance(control, MediaListCtrl) or control.updating:
            event.Skip()
            return
        item_id = control.shown_item_id(event.GetIndex())
        if item_id is not None:
            self.navigator.session.model.select_id(item_id)
            self._refresh_menu_state()
            self._play_radio_activity_cue(self.navigator.session.model.selected_row)
        event.Skip()

    def _play_radio_activity_cue(self, row: Row | None) -> None:
        """Opcjonalny, krotki sygnal stanu. Nie dotyka hosta ani audio AMC."""
        if (
            row is None
            or row.kind != "station"
            or getattr(self.navigator, "active", None) is not SessionId.RADIO
        ):
            return
        playback = bool(
            row.playback_activity and self.options.radio_playback_state_sound
        )
        recording = bool(
            row.recording_activity and self.options.radio_recording_state_sound
        )
        if not playback and not recording:
            return
        try:
            import wx.adv as wxadv

            key = (playback, recording)
            sound = self._radio_activity_cues.get(key)
            if sound is None:
                sound = wxadv.Sound()
                if not sound.CreateFromData(
                    activity_cue_wav(playback=playback, recording=recording)
                ):
                    return
                self._radio_activity_cues[key] = sound
            sound.Play(wxadv.SOUND_ASYNC)
        except (ImportError, AttributeError, RuntimeError):
            # Sygnal jest dodatkiem. Jego brak nie moze zepsuc strzalek ani
            # wypowiadania nazwy stacji przez natywna liste.
            return

    def _on_item_selected(self, event: wx.ListEvent) -> None:
        """Zaznaczenie z klawiatury/myszy wraca do modelu, zeby ID pozostal
        stabilny po odswiezeniu listy.

        BRAMKA ``updating``: nasza wlasna aktualizacja listy (wstawienie wiersza,
        ``SetItemState``) wysyla DOKLADNIE TO SAMO zdarzenie co ruch
        uzytkownika. Bez bramki przejsciowy indeks z trwajacej podmiany
        nadpisalby swiadomy wybor uzytkownika -- np. po wstawieniu pierwszego
        wiersza model wskazywalby 0 zamiast zapamietanego utworu.
        """
        control = event.GetEventObject()
        if isinstance(control, MediaListCtrl) and control.updating:
            event.Skip()
            return
        # INDEKS Z KONTROLKI, NIE Z MODELU. Przy aktywnym filtrze lista
        # pokazuje tylko wiersze dopasowane, wiec ``GetIndex()`` numeruje
        # WIDOCZNE wiersze. Przelozenie go na ``item_id`` tego, co kontrolka
        # faktycznie ma w ``_shown``, jest jedyna poprawna droga -- bez tego
        # strzalka w dol na przefiltrowanej liscie wybieralaby w modelu
        # zupelnie inny utwor (ten pod tym samym numerem w PELNYM zbiorze), a
        # Enter odtwarzalby nie to, co czytnik przeczytal.
        if isinstance(control, MediaListCtrl):
            item_id = control.shown_item_id(event.GetIndex())
            if item_id is not None:
                self.navigator.session.model.select_id(item_id)
                self._refresh_menu_state()
                event.Skip()
                return
        self.navigator.session.model.select_index(event.GetIndex())
        # Bramki ``needs_selection`` zmieniaja sie WRAZ Z ZAZNACZENIEM, a nie
        # tylko przy zmianie widoku. Zmierzone na zywym GUI (statusclip-2):
        # bez tego wywolania pozycja "Skopiuj adres" zostawala WYLACZONA po
        # strzalce na liscie, a wylaczony akcelerator POLYKAL Ctrl+Shift+C --
        # klawisz docieral do okna i nie robil nic.
        self._refresh_menu_state()
        event.Skip()

    def _on_item_deselected(self, event: wx.ListEvent) -> None:
        """Nie pozwol, by model wskazywal wiersz usuniety z zaznaczenia.

        Przy Ctrl+klik lub skracaniu zakresu Shift natywna lista moze zostawic
        fokus na wierszu juz niezaznaczonym. To POPRAWNY stan dla Ctrl+Spacji:
        kotwica modelu zostaje wtedy na fokusie, a ``_cursor_target`` nie
        zamienia go z powrotem w zaznaczenie. Gdy fokus jest gdzie indziej,
        kotwice przenosimy na rzeczywiscie zaznaczony wiersz.
        """
        control = event.GetEventObject()
        if not isinstance(control, MediaListCtrl) or control.updating:
            event.Skip()
            return
        item_id = control.shown_item_id(event.GetIndex())
        model = self.navigator.session.model
        if item_id is not None and model.selected_id == item_id:
            focused = control.GetFocusedItem()
            if focused != event.GetIndex():
                replacement = (
                    focused
                    if control._is_index_selected(focused)
                    else control.GetFirstSelected()
                )
                replacement_id = control.shown_item_id(replacement)
                model.select_id(replacement_id)
            self._refresh_menu_state()
        event.Skip()

    def _activate(self) -> None:
        self._run(self.navigator.activate_selected(
            open_player_on_activation=self._session_open_player_on_enter(
                self.navigator.active
            )
        ))

    def _current_preset_target(self) -> profile_presets.PresetTarget | None:
        """Element listy albo faktycznie odtwarzany element widoku gracza."""
        session = self.navigator.active
        state = self.navigator.session
        row = state.model.selected_row
        if state.view is View.PLAYER and state.now_playing_id:
            row = next(
                (
                    candidate for candidate in (
                        *state.playback_source_rows,
                        *state.model.rows,
                    )
                    if candidate.item_id == state.now_playing_id
                ),
                None,
            )
            # Plik otwarty bezposrednio przez Ctrl+O moze nie miec jeszcze
            # wiersza w Bibliotece, ale host zwraca jego prawdziwa sciezke.
            if row is None and session is SessionId.FILES:
                source = self._last_status.get("source")
                if isinstance(source, str) and source.strip():
                    row = Row(
                        item_id=state.now_playing_id,
                        title=state.now_playing_title or Path(source).name,
                        kind="track",
                        path=source.strip(),
                    )
        return profile_presets.target_from_row(session, row)

    def _active_sonos_target_row(self) -> Row | None:
        """Bieżąca grupa z ostatniej topologii; identyfikatory nie są tekstem UI."""
        if not self._sonos_active_household_id or not self._sonos_active_group_id:
            return None
        return next((
            row
            for row in self.navigator.sessions[SessionId.SONOS].sonos_target_rows
            if row.parent_id == self._sonos_active_household_id
            and row.service_id == self._sonos_active_group_id
            and row.service_kind == "sonosGroup"
        ), None)

    def _preset_inputs(self, session: SessionId) -> tuple[dict, list[dict]]:
        """Niezmienne migawki dla watku odczytujacego duzy profil AMC."""
        overrides = {
            key: [dict(item) for item in value]
            for key, value in self.state.preset_overrides.items()
        }
        stations = self.stations.as_payload() if session is SessionId.RADIO else []
        return overrides, stations

    def _show_presets(self) -> None:
        """Ctrl+Alt+P: jawna lista 12 miejsc, bez zapisu i bez technicznych ID."""
        session = self.navigator.active
        if session is SessionId.WIIM:
            self._show_wiim_presets()
            return
        if session is SessionId.FRONTIER_SMART:
            self._show_frontier_smart_presets()
            return
        target = self._current_preset_target()
        overrides, _stations = self._preset_inputs(session)

        def work() -> tuple[profile_presets.PresetEntry, ...]:
            return profile_presets.effective_entries(
                self.layout.state_json, session, overrides
            )

        def done(entries: tuple[profile_presets.PresetEntry, ...]) -> None:
            if self.navigator.active is not session:
                return
            session_name = session_options.session_display_name(session)
            with PresetListDialog(
                self,
                choices=profile_presets.choices(entries),
                session_name=session_name,
                current_target=target,
            ) as dialog:
                if dialog.ShowModal() != wx.ID_OK:
                    self._active_list().SetFocus() if self.navigator.view is View.LIST else self.play_button.SetFocus()
                    return
                choice = dialog.selected_choice
            if choice is not None:
                self._activate_preset(choice.slot)

        def failed(error: Exception) -> None:
            if isinstance(error, profile_presets.PresetProfileError):
                self.announcer.say(str(error))
            else:
                self.announcer.say("Nie udało się odczytać presetów")

        self.runner.submit("preset", work, done, failed)

    def _frontier_smart_device_context(self) -> tuple[str, str] | None:
        state = self.navigator.sessions[SessionId.FRONTIER_SMART]
        row = state.model.selected_row
        if (
            row is not None
            and row.kind == "frontierSmartDevice"
            and row.service_kind == "frontierSmartDevice"
            and row.service_id
        ):
            return row.service_id, row.title
        device_id = self._frontier_smart_active_device_id
        if not device_id:
            return None
        match = next((
            candidate
            for candidate in state.model.rows
            if candidate.service_id == device_id
        ), None)
        return device_id, match.title if match is not None else "Frontier Smart"

    def _apply_frontier_smart_operation_snapshot(self, payload: object) -> None:
        try:
            state = frontier_smart_snapshot(payload)
        except FrontierSmartPayloadError as error:
            self.announcer.say(str(error))
            return
        if state.get("deviceId") != self._frontier_smart_active_device_id:
            return
        self._frontier_smart_snapshot = state
        if self.navigator.active is SessionId.FRONTIER_SMART:
            self._apply_frontier_smart_snapshot(state, announce=True)

    def _show_frontier_smart_modes(self) -> None:
        client = self.client
        context = self._frontier_smart_device_context()
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        if context is None:
            self.announcer.say("Wybierz urządzenie Frontier Smart")
            return
        device_id, _title = context
        self._frontier_smart_active_device_id = device_id
        self.announcer.say("Pobieram tryby Frontier Smart")

        def done(payload: object) -> None:
            try:
                device_title, all_choices, _selected_index = (
                    frontier_smart_mode_choices(payload)
                )
            except FrontierSmartPayloadError as error:
                self.announcer.say(str(error))
                return
            choices = tuple(choice for choice in all_choices if choice.enabled)
            if not choices:
                self.announcer.say(
                    f"{device_title} nie podał trybów dostępnych do wyboru"
                )
                return
            selected_index = next((
                index for index, choice in enumerate(choices) if choice.selected
            ), 0)
            with wx.SingleChoiceDialog(
                self,
                "Wybierz tryb urządzenia.",
                f"Tryb — {device_title}",
                [choice.label for choice in choices],
            ) as dialog:
                dialog.SetName("Tryby urządzenia Frontier Smart")
                dialog.SetSelection(selected_index)
                if dialog.ShowModal() != wx.ID_OK:
                    self._restore_focus_after_dialog()
                    return
                choice = choices[dialog.GetSelection()]
            self._restore_focus_after_dialog()
            self.runner.submit(
                "frontier-smart-mode-set",
                lambda: client.frontier_smart_set_mode(device_id, choice.key),
                self._apply_frontier_smart_operation_snapshot,
                lambda error: self.announcer.say(
                    f"Nie udało się zmienić trybu Frontier Smart: {error}"
                ),
            )

        self.runner.submit(
            "frontier-smart-modes",
            lambda: client.frontier_smart_modes(device_id),
            done,
            lambda error: self.announcer.say(
                f"Nie udało się odczytać trybów Frontier Smart: {error}"
            ),
        )

    def _show_frontier_smart_presets(self) -> None:
        client = self.client
        context = self._frontier_smart_device_context()
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        if context is None:
            self.announcer.say("Wybierz urządzenie Frontier Smart")
            return
        device_id, _title = context
        self._frontier_smart_active_device_id = device_id

        def done(payload: object) -> None:
            try:
                device_title, choices = frontier_smart_preset_choices(payload)
            except FrontierSmartPayloadError as error:
                self.announcer.say(str(error))
                return
            if not choices:
                self.announcer.say(f"{device_title} nie podał żadnych presetów")
                return
            with wx.SingleChoiceDialog(
                self,
                "Wybierz preset zapisany w urządzeniu.",
                f"Presety — {device_title}",
                [choice.label for choice in choices],
            ) as dialog:
                dialog.SetName("Presety urządzenia Frontier Smart")
                dialog.SetSelection(0)
                if dialog.ShowModal() != wx.ID_OK:
                    self._restore_focus_after_dialog()
                    return
                choice = choices[dialog.GetSelection()]
            self._restore_focus_after_dialog()
            self._activate_frontier_smart_preset(
                device_id,
                choice.key,
                choice.title,
            )

        self.runner.submit(
            "frontier-smart-presets",
            lambda: client.frontier_smart_presets(device_id),
            done,
            lambda error: self.announcer.say(
                f"Nie udało się odczytać presetów Frontier Smart: {error}"
            ),
        )

    def _activate_frontier_smart_preset(
        self,
        device_id: str,
        preset_key: int,
        title: str,
    ) -> None:
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        self._frontier_smart_active_device_id = device_id
        self.runner.submit(
            "frontier-smart-preset-activate",
            lambda: client.frontier_smart_activate_preset(device_id, preset_key),
            self._apply_frontier_smart_operation_snapshot,
            lambda error: self.announcer.say(
                f"Nie udało się uruchomić presetu {title}: {error}"
            ),
        )

    def _activate_frontier_smart_shortcut_preset(self, slot: int) -> None:
        client = self.client
        context = self._frontier_smart_device_context()
        if client is None or context is None:
            self.announcer.say("Najpierw wybierz urządzenie Frontier Smart")
            return
        device_id, _title = context

        def done(payload: object) -> None:
            try:
                _device_title, choices = frontier_smart_preset_choices(payload)
            except FrontierSmartPayloadError as error:
                self.announcer.say(str(error))
                return
            choice = next(
                (candidate for candidate in choices if candidate.key == slot - 1),
                None,
            )
            if choice is None:
                self.announcer.say(f"Preset {slot} jest pusty lub niedostępny")
                return
            self._activate_frontier_smart_preset(
                device_id,
                choice.key,
                choice.title,
            )

        self.runner.submit(
            "frontier-smart-preset-shortcut",
            lambda: client.frontier_smart_presets(device_id),
            done,
            lambda error: self.announcer.say(
                f"Nie udało się odczytać presetów Frontier Smart: {error}"
            ),
        )

    def _wiim_device_context(self) -> tuple[str, str, str] | None:
        """Zwróć wybrane urządzenie bez umieszczania jego Id w interfejsie."""
        state = self.navigator.sessions[SessionId.WIIM]
        row = state.model.selected_row
        if (
            row is not None
            and row.kind == "device"
            and row.service_kind == "device"
            and row.service_id
        ):
            return row.item_id, row.service_id, row.title
        device_id = (
            state.library_item_id
            if state.library_view in (
                LibraryView.WIIM_SOURCE_LIBRARY,
                LibraryView.WIIM_NETWORK_STREAMS,
            )
            else None
        ) or self._wiim_active_device_id
        if not device_id:
            return None
        rows = (
            state.wiim_device_rows
            if state.wiim_device_rows
            else tuple(state.model.rows)
        )
        row = next(
            (
                candidate for candidate in rows
                if candidate.kind == "device"
                and candidate.service_kind == "device"
                and candidate.service_id == device_id
            ),
            None,
        )
        if row is None:
            return None
        return row.item_id, device_id, row.title

    def _show_wiim_network_streams(
        self,
        *,
        preferred_stream_id: str | None = None,
        announcement: str | None = None,
    ) -> None:
        """Zapisane strumienie dla wybranego urządzenia WiiM."""
        client = self.client
        context = self._wiim_device_context()
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        if context is None:
            self.announcer.say("Wybierz urządzenie WiiM")
            return
        item_id, device_id, _device_title = context
        self._wiim_active_device_id = device_id
        return_to_sources = (
            self.navigator.sessions[SessionId.WIIM].library_view
            is LibraryView.WIIM_SOURCE_LIBRARY
        )

        def done(payload: object) -> None:
            if self.navigator.active is not SessionId.WIIM:
                return
            if isinstance(payload, dict):
                sort_mode = str(payload.get("sortMode") or "")
                if sort_mode in {
                    SORT_ADDED_NEWEST,
                    SORT_ALPHABETICAL,
                    SORT_CUSTOM,
                }:
                    self._wiim_network_stream_sort_mode = sort_mode
            try:
                rows = list(wiim_network_stream_rows(
                    payload,
                    device_id=device_id,
                ))
            except WiiMPayloadError as error:
                self.announcer.say(str(error))
                return
            self._run(self.navigator.apply_wiim_network_streams(
                rows,
                device_id=device_id,
                return_id=item_id,
                preferred_id=(
                    f"wiim-stream:{preferred_stream_id}"
                    if preferred_stream_id else None
                ),
                return_to_sources=return_to_sources,
            ))
            if announcement:
                self.announcer.say(announcement)

        self.runner.submit(
            "wiim-network-streams",
            client.wiim_network_streams,
            done,
            lambda error: self.announcer.say(
                f"Nie udało się odczytać strumieni WiiM: {error}"
            ),
        )

    def _selected_wiim_stream_rows(self) -> list[Row]:
        """Zwróć tylko zapisane strumienie, nigdy urządzenie ani techniczny wpis."""
        return [
            row for row in self._selected_action_rows()
            if row.kind == "wiimNetworkStream"
            and row.service_kind == "wiimNetworkStream"
            and bool(row.service_id)
        ]

    def _add_wiim_network_stream(self) -> None:
        client = self._profile_edit_client()
        if client is None:
            return
        context = self._wiim_device_context()
        if context is None:
            self.announcer.say("Wybierz urządzenie WiiM")
            return
        with StationDialog(
            self,
            "Dodaj strumień WiiM",
            network_stream=True,
        ) as dialog:
            if dialog.ShowModal() != wx.ID_OK:
                self._restore_focus_after_dialog()
                return
            name, url = dialog.values

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            preferred = str(result.get("preferredStreamId") or "") or None
            message = str(result.get("message") or f"Dodano strumień WiiM: {name}")
            self._show_wiim_network_streams(
                preferred_stream_id=preferred,
                announcement=message,
            )

        self.runner.submit(
            "wiim-stream-edit",
            lambda: client.wiim_add_network_stream(name, url),
            done,
            lambda error: self.announcer.say(f"Nie dodano strumienia WiiM: {error}"),
        )

    def _edit_wiim_network_stream(self) -> None:
        rows = self._selected_wiim_stream_rows()
        if len(rows) != 1:
            self.announcer.say("Do edycji wybierz jeden strumień WiiM")
            return
        client = self._profile_edit_client()
        if client is None:
            return
        selected = rows[0]
        stream_id = selected.service_id or ""

        def loaded(payload: object) -> None:
            try:
                loaded_id, current_name, current_url = wiim_network_stream_edit_info(payload)
            except WiiMPayloadError as error:
                self.announcer.say(str(error))
                return
            with StationDialog(
                self,
                "Edytuj strumień WiiM",
                current_name,
                current_url,
                network_stream=True,
            ) as dialog:
                if dialog.ShowModal() != wx.ID_OK:
                    self._restore_focus_after_dialog()
                    return
                name, url = dialog.values

            def saved(result_payload: object) -> None:
                result = result_payload if isinstance(result_payload, dict) else {}
                preferred = str(result.get("preferredStreamId") or loaded_id)
                message = str(
                    result.get("message") or f"Zapisano strumień WiiM: {name}"
                )
                self._show_wiim_network_streams(
                    preferred_stream_id=preferred,
                    announcement=message,
                )

            self.runner.submit(
                "wiim-stream-edit",
                lambda: client.wiim_edit_network_stream(loaded_id, name, url),
                saved,
                lambda error: self.announcer.say(
                    f"Nie zapisano strumienia WiiM: {error}"
                ),
            )

        self.runner.submit(
            "wiim-stream-edit-info",
            lambda: client.wiim_network_stream_edit_info(stream_id),
            loaded,
            lambda error: self.announcer.say(
                f"Nie odczytano strumienia WiiM: {error}"
            ),
        )

    def _remove_wiim_network_streams(self) -> None:
        rows = self._selected_wiim_stream_rows()
        if not rows:
            self.announcer.say("Wybierz strumień WiiM do usunięcia")
            return
        client = self._profile_edit_client()
        if client is None:
            return
        prompt = (
            f"Usunąć strumień {rows[0].title} z AMC? "
            "Lista w aplikacji WiiM Home pozostanie bez zmian."
            if len(rows) == 1 else
            f"Usunąć wybrane strumienie z AMC: {len(rows)}? "
            "Lista w aplikacji WiiM Home pozostanie bez zmian."
        )
        if wx.MessageBox(
            prompt,
            "Potwierdzenie",
            wx.YES_NO | wx.NO_DEFAULT | wx.ICON_QUESTION,
            self,
        ) != wx.YES:
            self._restore_focus_after_dialog()
            return
        stream_ids = [row.service_id for row in rows if row.service_id]

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            removed = set(stream_ids)
            self._wiim_pending_move_ids = [
                stream_id for stream_id in self._wiim_pending_move_ids
                if stream_id not in removed
            ]
            message = str(
                result.get("message")
                or f"Usunięto strumienie WiiM: {len(stream_ids)}"
            )
            self._show_wiim_network_streams(announcement=message)

        self.runner.submit(
            "wiim-stream-edit",
            lambda: client.wiim_remove_network_streams(stream_ids),
            done,
            lambda error: self.announcer.say(
                f"Nie usunięto strumieni WiiM: {error}"
            ),
        )

    def _import_wiim_network_streams(self) -> None:
        client = self._profile_edit_client()
        if client is None:
            return
        if self._wiim_device_context() is None:
            self.announcer.say("Wybierz urządzenie WiiM")
            return
        with wx.FileDialog(
            self,
            "Otwórz playlistę lub plik ze strumieniami WiiM",
            wildcard=(
                "Playlisty (*.m3u;*.m3u8;*.pls)|*.m3u;*.m3u8;*.pls|"
                "Wszystkie pliki (*.*)|*.*"
            ),
            style=wx.FD_OPEN | wx.FD_FILE_MUST_EXIST,
        ) as dialog:
            if dialog.ShowModal() != wx.ID_OK:
                self._restore_focus_after_dialog()
                return
            path = dialog.GetPath()

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            preferred = str(result.get("preferredStreamId") or "") or None
            message = str(
                result.get("message") or "Zakończono import strumieni WiiM"
            )
            self._show_wiim_network_streams(
                preferred_stream_id=preferred,
                announcement=message,
            )

        self.runner.submit(
            "wiim-stream-import",
            lambda: client.wiim_import_network_streams(path),
            done,
            lambda error: self.announcer.say(
                f"Nie można zaimportować playlisty: {error}"
            ),
        )

    def _export_wiim_network_streams(self) -> None:
        client = self._profile_edit_client()
        if client is None:
            return
        with wx.FileDialog(
            self,
            "Eksportuj strumienie do WiiM Home",
            defaultFile="Strumienie WiiM AMC.m3u",
            wildcard="Playlisty M3U (*.m3u)|*.m3u|Wszystkie pliki (*.*)|*.*",
            style=wx.FD_SAVE | wx.FD_OVERWRITE_PROMPT,
        ) as dialog:
            if dialog.ShowModal() != wx.ID_OK:
                self._restore_focus_after_dialog()
                return
            path = str(Path(dialog.GetPath()).with_suffix(".m3u"))

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            count = int(result.get("exportedCount") or 0)
            self.announcer.say(f"Wyeksportowano strumienie WiiM: {count}")
            self._restore_focus_after_dialog()

        self.runner.submit(
            "wiim-stream-export",
            lambda: client.wiim_export_network_streams(path),
            done,
            lambda error: self.announcer.say(
                f"Nie można zapisać playlisty: {error}"
            ),
        )

    def _set_wiim_network_stream_sort(self, action: Action) -> None:
        modes = {
            Action.SORT_WIIM_NETWORK_STREAMS_ADDED: SORT_ADDED_NEWEST,
            Action.SORT_WIIM_NETWORK_STREAMS_ALPHABETICAL: SORT_ALPHABETICAL,
            Action.SORT_WIIM_NETWORK_STREAMS_CUSTOM: SORT_CUSTOM,
        }
        mode = modes[action]
        client = self._profile_edit_client()
        if client is None:
            return
        selected = next(iter(self._selected_wiim_stream_rows()), None)
        preferred = selected.service_id if selected is not None else None

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            self._wiim_network_stream_sort_mode = mode
            if mode != SORT_CUSTOM:
                self._wiim_pending_move_ids = []
            message = str(result.get("message") or "Zmieniono kolejność strumieni WiiM")
            self._show_wiim_network_streams(
                preferred_stream_id=preferred,
                announcement=message,
            )

        self.runner.submit(
            "wiim-stream-sort",
            lambda: client.wiim_sort_network_streams(mode),
            done,
            lambda error: self.announcer.say(
                f"Nie zapisano kolejności strumieni WiiM: {error}"
            ),
        )

    def _move_wiim_network_streams(self, direction: int) -> None:
        if self._wiim_network_stream_sort_mode != SORT_CUSTOM:
            self.announcer.say(
                "Przenoszenie działa w kolejności własnej. Naciśnij Alt 3"
            )
            return
        filter_box = getattr(self, "filter_box", None)
        if filter_box is not None and filter_box.GetValue().strip():
            self.announcer.say(
                "Wyczyść filtr klawiszem Escape przed zmianą kolejności"
            )
            return
        rows = self._selected_wiim_stream_rows()
        if not rows:
            self.announcer.say("Najpierw wybierz strumień")
            return
        client = self._profile_edit_client()
        if client is None:
            return
        stream_ids = [row.service_id for row in rows if row.service_id]
        selected = set(stream_ids)
        visible = [
            row for row in self.navigator.session.model.rows
            if row.kind == "wiimNetworkStream" and row.service_id
        ]
        positions = [
            index for index, row in enumerate(visible)
            if row.service_id in selected
        ]
        adjacent_title = "sąsiedni element"
        if positions and positions[-1] - positions[0] + 1 == len(positions):
            adjacent_index = positions[0] - 1 if direction < 0 else positions[-1] + 1
            if 0 <= adjacent_index < len(visible):
                adjacent_title = visible[adjacent_index].title

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            preferred = str(result.get("preferredStreamId") or "") or None
            moved = (
                "Przeniesiono strumień"
                if len(stream_ids) == 1
                else f"Przeniesiono strumienie: {len(stream_ids)}"
            )
            message = (
                f"{moved} w górę, nad {adjacent_title}"
                if direction < 0
                else f"{moved} w dół, pod {adjacent_title}"
            )
            self._show_wiim_network_streams(
                preferred_stream_id=preferred,
                announcement=message,
            )

        self.runner.submit(
            "wiim-stream-order",
            lambda: client.wiim_move_network_streams(stream_ids, direction),
            done,
            lambda error: self.announcer.say(str(error)),
        )

    def _cut_wiim_network_streams(self) -> None:
        if self._wiim_network_stream_sort_mode != SORT_CUSTOM:
            self.announcer.say(
                "Przenoszenie działa w kolejności własnej. Naciśnij Alt 3"
            )
            return
        filter_box = getattr(self, "filter_box", None)
        if filter_box is not None and filter_box.GetValue().strip():
            self.announcer.say(
                "Wyczyść filtr klawiszem Escape przed przenoszeniem elementów"
            )
            return
        rows = self._selected_wiim_stream_rows()
        if not rows:
            self.announcer.say("Najpierw wybierz strumień")
            return
        self._wiim_pending_move_ids = [
            row.service_id for row in rows if row.service_id
        ]
        self.announcer.say(
            "Zaznaczono strumień do przeniesienia. "
            "Wybierz miejsce i naciśnij Control V"
            if len(self._wiim_pending_move_ids) == 1 else
            f"Zaznaczono strumienie do przeniesienia: "
            f"{len(self._wiim_pending_move_ids)}. "
            "Wybierz miejsce i naciśnij Control V"
        )

    def _paste_wiim_network_streams(self) -> None:
        if self._wiim_network_stream_sort_mode != SORT_CUSTOM:
            self.announcer.say(
                "Przenoszenie działa w kolejności własnej. Naciśnij Alt 3"
            )
            return
        filter_box = getattr(self, "filter_box", None)
        if filter_box is not None and filter_box.GetValue().strip():
            self.announcer.say(
                "Wyczyść filtr klawiszem Escape przed przenoszeniem elementów"
            )
            return
        if not self._wiim_pending_move_ids:
            self.announcer.say(
                "Najpierw naciśnij Control X na strumieniu do przeniesienia"
            )
            return
        target = next(iter(self._selected_wiim_stream_rows()), None)
        if target is None or not target.service_id:
            self.announcer.say("Nie wybrano miejsca docelowego")
            return
        client = self._profile_edit_client()
        if client is None:
            return
        pending = list(self._wiim_pending_move_ids)
        target_id = target.service_id
        target_title = target.title

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            preferred = str(result.get("preferredStreamId") or "") or None
            self._wiim_pending_move_ids = []
            message = (
                f"Przeniesiono strumień przed {target_title}"
                if len(pending) == 1 else
                f"Przeniesiono strumienie: {len(pending)}, przed {target_title}"
            )
            self._show_wiim_network_streams(
                preferred_stream_id=preferred,
                announcement=message,
            )

        self.runner.submit(
            "wiim-stream-order",
            lambda: client.wiim_place_network_streams(pending, target_id),
            done,
            lambda error: self.announcer.say(str(error)),
        )

    def _activate_wiim_network_stream(
        self, intent: PlayWiiMNetworkStream
    ) -> None:
        """Uruchom strumień po Id; adres nigdy nie przechodzi do wx/NVDA."""
        client = self.client
        if client is None:
            self._run(self.navigator.back_to_list())
            self.announcer.say("Silnik nie jest gotowy")
            return
        self._wiim_active_device_id = intent.device_id
        self._wiim_snapshot = {}
        self.now_playing.SetLabel(intent.title)
        self._set_transport_label(playing=False, preparing=True)

        def done(payload: object) -> None:
            try:
                state = wiim_snapshot(payload)
            except WiiMPayloadError as error:
                failed(error)
                return
            if state.get("deviceId") != self._wiim_active_device_id:
                return
            session = self.navigator.sessions[SessionId.WIIM]
            session.player_entry_anchor_id = intent.item_id
            session.list_anchor_id = intent.item_id
            session.now_playing_id = intent.item_id
            session.now_playing_title = intent.title
            session.current_material_id = intent.item_id
            session.view = View.PLAYER
            self._wiim_snapshot = state
            record_history = getattr(self, "_record_streamer_history_row", None)
            if callable(record_history):
                record_history(SessionId.WIIM, Row(
                    item_id=intent.item_id,
                    title=intent.title,
                    kind="wiimNetworkStream",
                    parent_id=intent.device_id,
                    service_id=intent.stream_id,
                    service_kind="wiimNetworkStream",
                ), replay_supported=True)
            if self.navigator.active is SessionId.WIIM:
                self._sync_views()
                self._apply_wiim_snapshot(state, announce=True)

        def failed(error: Exception) -> None:
            session = self.navigator.sessions[SessionId.WIIM]
            session.view = View.LIST
            if self.navigator.active is SessionId.WIIM:
                self._sync_views()
                self.announcer.say(str(error))

        self.runner.submit(
            "wiim-network-stream-play",
            lambda: client.wiim_play_network_stream(
                intent.device_id,
                intent.stream_id,
            ),
            done,
            failed,
        )

    def _show_wiim_option(self, action: Action) -> None:
        """Otwórz jedną opcję odtwarzacza WiiM z etykietami hosta C#."""
        option_by_action = {
            Action.WIIM_SELECT_INPUT: "input",
            Action.WIIM_SELECT_OUTPUT: "output",
            Action.WIIM_SELECT_EQUALIZER: "equalizer",
            Action.WIIM_SELECT_REPEAT: "repeat",
            Action.WIIM_SET_SLEEP_TIMER: "sleep",
        }
        option = option_by_action.get(action)
        client = self.client
        context = self._wiim_device_context()
        if option is None:
            self.announcer.say("Nieznane ustawienie WiiM")
            return
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        if self.navigator.view is not View.PLAYER or context is None:
            self.announcer.say(
                "To ustawienie WiiM jest dostępne po otwarciu sterowania urządzeniem"
            )
            return
        _item_id, device_id, device_title = context

        def done(payload: object) -> None:
            if (
                self.navigator.active is not SessionId.WIIM
                or self.navigator.view is not View.PLAYER
                or self._wiim_active_device_id != device_id
            ):
                return
            try:
                (
                    _returned_device_title,
                    title,
                    description,
                    choices,
                    selected_index,
                ) = wiim_option_choices(payload)
            except WiiMPayloadError as error:
                self.announcer.say(str(error))
                return
            with WiiMOptionDialog(
                self,
                title=title,
                description=description,
                choices=choices,
                selected_index=selected_index,
            ) as dialog:
                if dialog.ShowModal() != wx.ID_OK:
                    self._restore_focus_after_dialog()
                    return
                choice = dialog.selected_choice
            if choice is None:
                self._restore_focus_after_dialog()
                return

            def applied(result: object) -> None:
                try:
                    state = wiim_snapshot(result)
                except WiiMPayloadError as error:
                    self.announcer.say(str(error))
                    return
                if (
                    self.navigator.active is not SessionId.WIIM
                    or self.navigator.view is not View.PLAYER
                    or self._wiim_active_device_id != device_id
                ):
                    return
                self._wiim_snapshot = state
                self._apply_wiim_snapshot(state, announce=True)
                self.play_button.SetFocus()

            self.runner.submit(
                f"wiim-option-set-{option}",
                lambda: client.wiim_set_option(device_id, option, choice.value),
                applied,
                lambda error: self.announcer.say(
                    f"Nie udało się zastosować ustawienia urządzenia "
                    f"{device_title}: {error}"
                ),
            )

        self.runner.submit(
            f"wiim-option-read-{option}",
            lambda: client.wiim_options(device_id, option),
            done,
            lambda error: self.announcer.say(
                f"Urządzenie {device_title} nie udostępniło tej opcji: {error}"
            ),
        )

    def _toggle_wiim_shuffle(self) -> None:
        client = self.client
        context = self._wiim_device_context()
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        if self.navigator.view is not View.PLAYER or context is None:
            self.announcer.say(
                "Losowanie WiiM jest dostępne po otwarciu sterowania urządzeniem"
            )
            return
        _item_id, device_id, device_title = context

        def done(payload: object) -> None:
            try:
                state = wiim_snapshot(payload)
            except WiiMPayloadError as error:
                self.announcer.say(str(error))
                return
            if (
                self.navigator.active is not SessionId.WIIM
                or self.navigator.view is not View.PLAYER
                or self._wiim_active_device_id != device_id
            ):
                return
            self._wiim_snapshot = state
            self._apply_wiim_snapshot(state, announce=True)
            self.play_button.SetFocus()

        self.runner.submit(
            "wiim-shuffle-toggle",
            lambda: client.wiim_toggle_shuffle(device_id),
            done,
            lambda error: self.announcer.say(
                f"Nie udało się zmienić losowania urządzenia "
                f"{device_title}: {error}"
            ),
        )

    def _show_wiim_presets(self, *, select_for_shortcut: bool = False) -> None:
        """Lista 12 miejsc urządzenia albo wybór celu skrótu AMC."""
        client = self.client
        context = self._wiim_device_context()
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        if context is None:
            self.announcer.say("Wybierz urządzenie WiiM")
            return
        item_id, device_id, device_title = context
        overrides, _stations = self._preset_inputs(SessionId.WIIM)

        def work():
            payload = client.wiim_presets(device_id)
            returned_title, choices = wiim_preset_choices(payload)
            entries = profile_presets.effective_wiim_entries(
                self.layout.state_json,
                device_id,
                choices,
                overrides,
            )
            return returned_title, choices, entries

        def done(result) -> None:
            if self.navigator.active is not SessionId.WIIM:
                return
            returned_title, choices, entries = result
            shortcut_slots = {
                number: entry.slot
                for entry in entries
                if (number := profile_presets.wiim_native_preset_number(entry))
                is not None
            }
            with WiiMPresetListDialog(
                self,
                choices=choices,
                device_title=returned_title or device_title,
                shortcut_slots_by_preset=shortcut_slots,
                select_for_shortcut=select_for_shortcut,
            ) as dialog:
                if dialog.ShowModal() != wx.ID_OK:
                    if self.navigator.view is View.LIST:
                        self._active_list().SetFocus()
                    else:
                        self.play_button.SetFocus()
                    return
                choice = dialog.selected_choice
            if choice is not None:
                if dialog.shortcut_assignment_requested:
                    self._assign_wiim_preset_shortcut(
                        device_id,
                        returned_title or device_title,
                        choice,
                        entries,
                    )
                else:
                    self._activate_wiim_preset(
                        item_id,
                        device_id,
                        returned_title or device_title,
                        choice,
                    )

        self.runner.submit(
            "wiim-presets",
            work,
            done,
            lambda error: self.announcer.say(
                f"Nie udało się odczytać presetów urządzenia {device_title}: {error}"
            ),
        )

    def _assign_wiim_preset_shortcut(
        self,
        device_id: str,
        device_title: str,
        native_choice: WiiMPresetChoice,
        entries: tuple[profile_presets.PresetEntry, ...],
    ) -> None:
        """Przypisz gotowy preset urządzenia bez zmiany samego urządzenia."""
        try:
            target = profile_presets.wiim_native_target(native_choice)
        except ValueError as error:
            self.announcer.say(str(error))
            return
        choices = profile_presets.choices(entries)
        free = profile_presets.first_free_slot(entries)
        existing = profile_presets.existing_target_slot(entries, target)
        initial = existing or free or 1
        with PresetAssignmentDialog(
            self,
            target=target,
            choices=choices,
            first_free_slot=free,
            initial_slot=initial,
            session_name=f"WiiM, {device_title}",
        ) as dialog:
            if dialog.ShowModal() != wx.ID_OK:
                self._restore_focus_after_dialog()
                return
            slot = dialog.selected_slot
            action = dialog.selected_action

        updated = (
            profile_presets.remove_entry(entries, slot)
            if action == "remove"
            else profile_presets.replace_entry(entries, target, slot)
        )
        key = profile_presets.wiim_device_preset_key(device_id)
        previous = {
            name: [dict(item) for item in value]
            for name, value in self.state.preset_overrides.items()
        }
        next_overrides = {
            name: [dict(item) for item in value]
            for name, value in previous.items()
        }
        next_overrides[key] = profile_presets.entries_payload(updated)
        self.state.preset_overrides = next_overrides
        try:
            self.store.save(self.state)
        except Exception:
            self.state.preset_overrides = previous
            self.announcer.say(
                "Nie udało się zapisać przypisania. Niczego nie zmieniono"
            )
            return
        spoken = profile_presets.shortcut_label(slot, spoken=True)
        if action == "remove":
            self.announcer.say(
                f"Usunięto przypisanie Ctrl+Shift+{spoken}. "
                "Preset urządzenia pozostał bez zmian"
            )
        else:
            self.announcer.say(
                f"Ctrl+Shift+{spoken} uruchamia preset {native_choice.number}, "
                f"{native_choice.title}. Ustawienia urządzenia nie zostały zmienione"
            )

    def _activate_wiim_shortcut_preset(self, slot: int) -> None:
        """Rozwiąż miejsce Ctrl+Shift dla bieżącego urządzenia WiiM."""
        client = self.client
        context = self._wiim_device_context()
        spoken = profile_presets.shortcut_label(slot, spoken=True)
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        if context is None:
            self.announcer.say("Wybierz urządzenie WiiM")
            return
        item_id, device_id, device_title = context
        overrides, _stations = self._preset_inputs(SessionId.WIIM)

        def work():
            payload = client.wiim_presets(device_id)
            returned_title, choices = wiim_preset_choices(payload)
            entries = profile_presets.effective_wiim_entries(
                self.layout.state_json,
                device_id,
                choices,
                overrides,
            )
            return returned_title, choices, entries

        def done(result) -> None:
            if self.navigator.active is not SessionId.WIIM:
                return
            returned_title, choices, entries = result
            entry = next((entry for entry in entries if entry.slot == slot), None)
            number = profile_presets.wiim_native_preset_number(entry)
            if number is None:
                self.announcer.say(
                    f"Preset {spoken} pusty. Ctrl+Alt+Shift+P przypisuje "
                    "gotowy preset WiiM"
                )
                return
            choice = next(
                (choice for choice in choices if choice.number == number),
                None,
            )
            if choice is None or not choice.occupied:
                self.announcer.say(
                    f"Skrót Ctrl+Shift+{spoken} wskazuje preset {number}, "
                    "który nie jest już dostępny w urządzeniu"
                )
                return
            if choice.activation_error:
                self.announcer.say(choice.activation_error)
                return
            self._last_preset_slot_by_session[SessionId.WIIM] = slot
            self._activate_wiim_preset(
                item_id,
                device_id,
                returned_title or device_title,
                choice,
            )

        self.runner.submit(
            "wiim-shortcut-preset",
            work,
            done,
            lambda error: self.announcer.say(
                f"Nie udało się uruchomić presetu urządzenia {device_title}: {error}"
            ),
        )

    def _activate_wiim_preset(
        self,
        item_id: str,
        device_id: str,
        device_title: str,
        choice: WiiMPresetChoice,
    ) -> None:
        """Uruchom zajęty preset i dopiero po sukcesie pokaż odtwarzacz."""
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return

        def done(payload: object) -> None:
            try:
                state = wiim_snapshot(payload)
            except WiiMPayloadError as error:
                self.announcer.say(str(error))
                return
            if state.get("deviceId") != device_id:
                return
            session = self.navigator.sessions[SessionId.WIIM]
            session.player_entry_anchor_id = item_id
            session.list_anchor_id = item_id
            session.now_playing_id = item_id
            session.now_playing_title = device_title
            session.current_material_id = item_id
            session.view = View.PLAYER
            self._wiim_active_device_id = device_id
            self._wiim_snapshot = state
            record_history = getattr(self, "_record_streamer_history_row", None)
            if callable(record_history):
                record_history(SessionId.WIIM, Row(
                    item_id=f"{item_id}:preset:{choice.number}",
                    title=choice.title,
                    kind="station",
                ), replay_supported=False)
            if self.navigator.active is SessionId.WIIM:
                self._sync_views()
                self._apply_wiim_snapshot(state, announce=True)

        self.runner.submit(
            "wiim-preset-activate",
            lambda: client.wiim_activate_preset(device_id, choice.number),
            done,
            lambda error: self.announcer.say(
                f"Nie udało się uruchomić presetu urządzenia {device_title}: {error}"
            ),
        )

    def _assign_preset(self) -> None:
        """Ctrl+Alt+Shift+P: trwale zapisz tylko prywatne nadpisanie wxPython."""
        session = self.navigator.active
        if session is SessionId.WIIM:
            self._show_wiim_presets(select_for_shortcut=True)
            return
        target = self._current_preset_target()
        if target is None:
            self.announcer.say(
                f"Wybierz element sesji {session_options.session_display_name(session)}, "
                "który chcesz przypisać do presetu"
            )
            return
        overrides, _stations = self._preset_inputs(session)

        def work() -> tuple[profile_presets.PresetEntry, ...]:
            return profile_presets.effective_entries(
                self.layout.state_json, session, overrides
            )

        def done(entries: tuple[profile_presets.PresetEntry, ...]) -> None:
            if self.navigator.active is not session:
                return
            free = profile_presets.first_free_slot(entries)
            existing_slot = profile_presets.existing_target_slot(entries, target)
            initial = existing_slot or free or 1
            existing = next(
                (entry for entry in entries if entry.slot == existing_slot),
                None,
            )
            fixed_row = (
                self._active_sonos_target_row()
                if session is SessionId.SONOS else None
            )
            fixed_available = bool(
                fixed_row is not None
                and fixed_row.service_members
                and (
                    target.sonos_household_id is None
                    or target.sonos_household_id == fixed_row.parent_id
                )
            )
            with PresetAssignmentDialog(
                self,
                target=target,
                choices=profile_presets.choices(entries),
                first_free_slot=free,
                initial_slot=initial,
                session_name=session_options.session_display_name(session),
                fixed_target_title=(fixed_row.title if fixed_row else ""),
                fixed_target_available=fixed_available,
                fixed_target_initially_selected=bool(
                    existing is not None
                    and existing.sonos_fixed_player_ids
                ),
            ) as dialog:
                if dialog.ShowModal() != wx.ID_OK:
                    self._active_list().SetFocus() if self.navigator.view is View.LIST else self.play_button.SetFocus()
                    return
                slot = dialog.selected_slot
                action = dialog.selected_action
                fixed_selected = dialog.fixed_target_selected

            assigned_target = target
            if action != "remove" and fixed_selected and fixed_row is not None:
                assigned_target = profile_presets.PresetTarget(
                    target.target_id,
                    target.target_kind,
                    target.title,
                    target.location,
                    sonos_household_id=(
                        target.sonos_household_id or fixed_row.parent_id
                    ),
                    sonos_fixed_player_ids=fixed_row.service_members,
                )

            updated = (
                profile_presets.remove_entry(entries, slot)
                if action == "remove"
                else profile_presets.replace_entry(entries, assigned_target, slot)
            )
            previous = {
                key: [dict(item) for item in value]
                for key, value in self.state.preset_overrides.items()
            }
            next_overrides = {
                key: [dict(item) for item in value]
                for key, value in previous.items()
            }
            next_overrides[session.value] = profile_presets.entries_payload(updated)
            self.state.preset_overrides = next_overrides
            try:
                self.store.save(self.state)
            except Exception:
                self.state.preset_overrides = previous
                self.announcer.say("Nie udało się zapisać presetów. Niczego nie zmieniono")
                return

            spoken = profile_presets.shortcut_label(slot, spoken=True)
            if action == "remove":
                self.announcer.say(f"Usunięto preset {spoken}")
            else:
                self.announcer.say(f"Zapisano preset {spoken}: {target.title}")

        def failed(error: Exception) -> None:
            if isinstance(error, profile_presets.PresetProfileError):
                self.announcer.say(str(error))
            else:
                self.announcer.say("Nie udało się przygotować przypisania presetu")

        self.runner.submit("preset", work, done, failed)

    def _trigger_preset_10_from_native_boundary(
        self,
        *,
        now: float | None = None,
    ) -> None:
        """Wykonaj preset 10 raz, niezaleznie od natywnej trasy Windows."""

        if bool(getattr(self, "_keyboard_help_active", False)):
            return
        find_focus = getattr(getattr(wx, "Window", None), "FindFocus", None)
        focused = find_focus() if callable(find_focus) else None
        if focused is getattr(self, "filter_box", None):
            return
        current = time.monotonic() if now is None else float(now)
        if current < float(getattr(self, "_native_preset_10_guard_until", 0.0)):
            return
        # RegisterHotKey i WH_KEYBOARD moga zglosic ten sam fizyczny gest.
        # Krotka bramka usuwa wylacznie duplikat; kolejne swiadome nacisniecie
        # po zwolnieniu klawiszy nadal dziala normalnie.
        self._native_preset_10_guard_until = current + 0.25
        self._activate_preset(10)

    def _activate_preset(self, slot: int) -> None:
        """Uruchom preset profilu AMC albo jego prywatne nadpisanie wxPython."""
        session = self.navigator.active
        if session is SessionId.WIIM:
            self._activate_wiim_shortcut_preset(slot)
            return
        if session is SessionId.FRONTIER_SMART:
            self._activate_frontier_smart_shortcut_preset(slot)
            return
        spoken = profile_presets.shortcut_label(slot, spoken=True)
        overrides, stations = self._preset_inputs(session)

        def work():
            return profile_presets.resolve_preset(
                self.layout.state_json,
                session,
                slot,
                overrides=overrides,
                current_stations=stations,
            )

        def done(resolved: profile_presets.ResolvedPreset) -> None:
            # Preset nalezy do sesji z chwili nacisniecia. Odpowiedz po zmianie
            # sesji nie moze uruchomic materialu w obcym kontekscie.
            if self.navigator.active is not session:
                return
            entry = resolved.entry
            if entry is None:
                self.announcer.say(
                    f"Preset {spoken} pusty. Ctrl+Alt+Shift+P przypisuje bieżący element."
                )
                return

            if session is SessionId.RADIO:
                target = resolved.radio_target
                if target is None:
                    self.announcer.say(
                        f"Preset {spoken} jest niedostępny. Stacji nie ma już w profilu."
                    )
                    return
                sequence = tuple(
                    Row(
                        item_id=item.item_id,
                        title=item.title,
                        kind="station",
                        url=item.url,
                        show_kind=False,
                    )
                    for item in resolved.radio_sequence
                )
                target_row = next(
                    item for item in sequence if item.item_id == target.item_id
                )
                self._last_preset_slot_by_session[session] = slot
                self._run(self.navigator.activate_radio_preset(
                    target_row,
                    sequence,
                    open_player=self._session_open_player_on_preset(session),
                ))
                return

            if session is SessionId.SONOS and entry.target_kind.casefold() in {
                "sonos-favorite",
                "sonos-playlist",
                "sonos-own-stream",
            }:
                self._last_preset_slot_by_session[session] = slot
                self._activate_sonos_preset(entry, spoken)
                return

            spotify_target = (
                profile_presets.spotify_entry_target(entry)
                if session is SessionId.SPOTIFY else None
            )
            if spotify_target is not None:
                self._last_preset_slot_by_session[session] = slot
                kind, external_id = spotify_target
                self._activate_spotify_preset(
                    entry,
                    kind=kind,
                    external_id=external_id,
                    spoken_slot=spoken,
                )
                return

            kind = entry.target_kind.casefold()
            if kind == "folder" and entry.location:
                self._last_preset_slot_by_session[session] = slot
                self._open_library(entry.location)
                return
            if kind == "amcplaylist":
                playlist_id = entry.location
                if not playlist_id and ":" in entry.target_id:
                    playlist_id = entry.target_id.split(":", 1)[1]
                if playlist_id:
                    self._last_preset_slot_by_session[session] = slot
                    self._open_library_view(OpenLibraryView(
                        view=LibraryView.PLAYLIST_CONTENTS,
                        playlist_id=playlist_id,
                        target_session_id=SessionId.FILES,
                    ))
                    return
            if kind in ("track", "file") and entry.location:
                self._last_preset_slot_by_session[session] = slot
                target_row = Row(
                    item_id=entry.target_id,
                    title=entry.title or Path(entry.location).name,
                    kind="track",
                    path=entry.location,
                )
                self._run(self.navigator.activate_local_preset(
                    target_row,
                    open_player=self._session_open_player_on_preset(session),
                ))
                return
            self.announcer.say(
                f"Preset {spoken} istnieje, ale ten rodzaj materiału nie jest jeszcze przeniesiony."
            )

        def failed(error: Exception) -> None:
            if isinstance(error, profile_presets.PresetProfileError):
                self.announcer.say(str(error))
            else:
                self.announcer.say("Nie udało się odczytać presetu")

        self.runner.submit("preset", work, done, failed)

    def _activate_spotify_preset(
        self,
        entry: profile_presets.PresetEntry,
        *,
        kind: str,
        external_id: str,
        spoken_slot: str,
    ) -> None:
        """Run one old-or-new Spotify preset through the native Python UI."""

        row = Row(
            item_id=entry.target_id,
            title=entry.title or "Element Spotify",
            kind=kind,
            service_id=external_id,
            service_kind=kind,
        )
        self._spotify_preset_playback_version = (
            getattr(self, "_spotify_preset_playback_version", 0) + 1
        )
        version = self._spotify_preset_playback_version
        if kind == "album":
            self._play_spotify_album_preset(
                row,
                spoken_slot=spoken_slot,
                request_version=version,
            )
            return
        if kind in {"track", "episode"}:
            intent = self.navigator.prepare_spotify_preset_playback(
                row,
                announcement=row.title,
            )
            self._run([intent])
            return
        # Tak jak w starym AMC: preset kontenera innego niż album otwiera
        # właściwy katalog. Wykonawca dostaje skrócony widok Albumy/Utwory.
        self._run(self.navigator.open_spotify_search_result(row))

    def _play_spotify_album_preset(
        self,
        album: Row,
        *,
        spoken_slot: str,
        request_version: int,
        attempt: int = 0,
    ) -> None:
        """Fetch and play an album without changing list, focus or selection."""

        client = self.client
        if client is None:
            self.announcer.say("Silnik nie działa, nie mogę odtworzyć Spotify")
            return

        def work():
            return spotify_container_result_from_payload(
                client.spotify_container_items(
                    external_id=album.service_id or "",
                    title=album.title,
                    kind="album",
                    artist=album.artist_name,
                )
            )

        def is_current() -> bool:
            return bool(
                request_version
                == getattr(self, "_spotify_preset_playback_version", 0)
                and self.navigator.active is SessionId.SPOTIFY
            )

        def done(result) -> None:
            if not is_current():
                return
            if not result.available:
                self.announcer.say(
                    result.warning
                    or f"Preset {spoken_slot}: Spotify nie udostępnił zawartości albumu {album.title}"
                )
                return
            playable = tuple(
                row for row in result.rows
                if row.kind in {"track", "episode"}
                and not row.activation_message
            )
            if not playable:
                self.announcer.say(
                    f"Preset {spoken_slot}: album {album.title} nie zawiera utworów do odtworzenia"
                )
                return
            intent = self.navigator.prepare_spotify_preset_playback(
                playable[0],
                source_rows=playable,
                announcement=album.title,
            )
            self._run([intent])

        def failed(error: Exception) -> None:
            if not is_current():
                return
            if (
                isinstance(error, HostError)
                and error.code == "operation_busy"
                and attempt < 20
            ):
                wx.CallLater(
                    250,
                    lambda: self._play_spotify_album_preset(
                        album,
                        spoken_slot=spoken_slot,
                        request_version=request_version,
                        attempt=attempt + 1,
                    ) if is_current() else None,
                )
                return
            self.announcer.say(
                f"Preset {spoken_slot}: nie udało się odtworzyć albumu {album.title}"
            )

        self.runner.submit("spotify-preset", work, done, failed)

    def _navigate_nvda_preset(self, direction: int) -> None:
        """Dodatek NVDA: przejdź po zajętych presetach bieżącej sesji.

        Odczyt profilu może być duży, dlatego nie blokuje wątku okna ani
        odpowiedzi do dodatku. Wynik rozpoczęty w jednej sesji nie uruchomi
        niczego po przełączeniu do innej.
        """

        session = self.navigator.active
        if session is SessionId.WIIM:
            self._navigate_nvda_wiim_preset(direction)
            return
        if session is SessionId.FRONTIER_SMART:
            self._navigate_nvda_frontier_smart_preset(direction)
            return
        target = self._current_preset_target()
        overrides, _stations = self._preset_inputs(session)
        current_slot = self._last_preset_slot_by_session.get(session)

        def work() -> profile_presets.PresetEntry | None:
            entries = profile_presets.effective_entries(
                self.layout.state_json, session, overrides
            )
            return profile_presets.adjacent_entry(
                entries,
                direction=direction,
                current_target=target,
                current_slot=current_slot,
            )

        def done(entry: profile_presets.PresetEntry | None) -> None:
            if self.navigator.active is not session:
                return
            if entry is None:
                self.announcer.say(
                    f"Brak zapisanych presetów: "
                    f"{session_options.session_display_name(session)}"
                )
                return
            self._activate_preset(entry.slot)

        self.runner.submit(
            "preset-navigate",
            work,
            done,
            lambda error: self.announcer.say(
                str(error)
                if isinstance(error, profile_presets.PresetProfileError)
                else "Nie udało się odczytać presetów"
            ),
        )

    def _navigate_nvda_frontier_smart_preset(self, direction: int) -> None:
        client = self.client
        context = self._frontier_smart_device_context()
        if client is None or context is None:
            self.announcer.say("Najpierw wybierz urządzenie Frontier Smart")
            return
        device_id, _title = context
        current_key = getattr(self, "_last_frontier_smart_preset_key", None)

        def done(payload: object) -> None:
            if self.navigator.active is not SessionId.FRONTIER_SMART:
                return
            try:
                _device_title, choices = frontier_smart_preset_choices(payload)
            except FrontierSmartPayloadError as error:
                self.announcer.say(str(error))
                return
            if not choices:
                self.announcer.say("Brak zapisanych presetów Frontier Smart")
                return
            index = next((
                position
                for position, choice in enumerate(choices)
                if choice.key == current_key
            ), -1 if direction > 0 else 0)
            choice = choices[(index + direction) % len(choices)]
            self._last_frontier_smart_preset_key = choice.key
            self._activate_frontier_smart_preset(
                device_id,
                choice.key,
                choice.title,
            )

        self.runner.submit(
            "frontier-smart-preset-navigate",
            lambda: client.frontier_smart_presets(device_id),
            done,
            lambda error: self.announcer.say(
                f"Nie udało się odczytać presetów Frontier Smart: {error}"
            ),
        )

    def _navigate_nvda_wiim_preset(self, direction: int) -> None:
        """WiiM: użyj żywej listy urządzenia, bez otwierania jej w oknie."""

        client = self.client
        context = self._wiim_device_context()
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        if context is None:
            self.announcer.say("Wybierz urządzenie WiiM")
            return
        item_id, device_id, device_title = context
        overrides, _stations = self._preset_inputs(SessionId.WIIM)
        current_slot = self._last_preset_slot_by_session.get(SessionId.WIIM)

        def work():
            payload = client.wiim_presets(device_id)
            returned_title, choices = wiim_preset_choices(payload)
            entries = profile_presets.effective_wiim_entries(
                self.layout.state_json,
                device_id,
                choices,
                overrides,
            )
            if current_slot is None:
                current_number = next(
                    (choice.number for choice in choices if choice.current),
                    None,
                )
                active_slot = next(
                    (
                        entry.slot
                        for entry in entries
                        if profile_presets.wiim_native_preset_number(entry)
                        == current_number
                    ),
                    None,
                )
            else:
                active_slot = current_slot
            entry = profile_presets.adjacent_entry(
                entries,
                direction=direction,
                current_slot=active_slot,
            )
            return returned_title, choices, entry

        def done(result) -> None:
            if self.navigator.active is not SessionId.WIIM:
                return
            returned_title, choices, entry = result
            if entry is None:
                self.announcer.say(f"Brak zapisanych presetów: {device_title}")
                return
            number = profile_presets.wiim_native_preset_number(entry)
            choice = next(
                (candidate for candidate in choices if candidate.number == number),
                None,
            )
            if choice is None or not choice.occupied:
                self.announcer.say("Wybrany preset WiiM nie jest już dostępny")
                return
            if choice.activation_error:
                self.announcer.say(choice.activation_error)
                return
            self._last_preset_slot_by_session[SessionId.WIIM] = entry.slot
            self._activate_wiim_preset(
                item_id,
                device_id,
                returned_title or device_title,
                choice,
            )

        self.runner.submit(
            "wiim-preset-navigate",
            work,
            done,
            lambda error: self.announcer.say(
                f"Nie udało się odczytać presetów urządzenia {device_title}: {error}"
            ),
        )

    def _activate_sonos_preset(
        self,
        entry: profile_presets.PresetEntry,
        spoken_slot: str,
    ) -> None:
        """Uruchom materiał presetu na bieżącej albo dokładnie zapisanej grupie."""
        if self.navigator.active is not SessionId.SONOS:
            return
        kind = {
            "sonos-favorite": "favorite",
            "sonos-playlist": "playlist",
            "sonos-own-stream": "ownStream",
        }.get(entry.target_kind.casefold())
        if kind is None:
            self.announcer.say(
                f"Preset {spoken_slot} ma nieobsługiwany rodzaj materiału Sonos"
            )
            return

        fixed = tuple(sorted(set(entry.sonos_fixed_player_ids)))
        if not fixed:
            if not self._sonos_active_household_id or not self._sonos_active_group_id:
                self.announcer.say(
                    "Nie wybrano głośników Sonos. Wybierz grupę skrótem "
                    "Control F5 i spróbuj ponownie. Nic nie uruchomiłem"
                )
                return
            self._start_sonos_preset_material(
                entry,
                kind,
                spoken_slot,
                self._sonos_active_household_id,
                self._sonos_active_group_id,
            )
            return

        if not entry.sonos_household_id:
            self.announcer.say(
                f"Preset {spoken_slot} nie ma bezpiecznie zapisanego domu Sonos. "
                "Przypisz go ponownie. Nic nie uruchomiłem"
            )
            return
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return

        def done(payload: object) -> None:
            if self.navigator.active is not SessionId.SONOS:
                return
            try:
                rows = list(sonos_target_rows(payload))
            except SonosPayloadError:
                self.announcer.say(
                    "Nie udało się odczytać grup Sonos. Nic nie uruchomiłem"
                )
                return
            wanted = set(fixed)
            matches = [
                row for row in rows
                if row.parent_id == entry.sonos_household_id
                and set(row.service_members) == wanted
                and bool(row.service_id)
            ]
            if not matches:
                self.announcer.say(
                    "Nie ma teraz grupy Sonos o dokładnie tym zestawie "
                    "głośników. Zgrupuj je tak jak przy zapisie presetu. "
                    "Niczego nie uruchomiłem i nie przegrupowałem"
                )
                return
            if len(matches) > 1:
                self.announcer.say(
                    "Kilka grup Sonos ma ten sam zestaw głośników, więc wybór "
                    "nie jest jednoznaczny. Nic nie uruchomiłem"
                )
                return
            target = matches[0]
            self.navigator.sessions[SessionId.SONOS].sonos_target_rows = tuple(rows)
            self._start_sonos_preset_material(
                entry,
                kind,
                spoken_slot,
                target.parent_id or "",
                target.service_id or "",
            )

        self.runner.submit(
            "sonos-preset-target",
            client.sonos_targets,
            done,
            lambda _error: self.announcer.say(
                "Nie udało się odczytać grup Sonos. Nic nie uruchomiłem"
            ),
        )

    def _start_sonos_preset_material(
        self,
        entry: profile_presets.PresetEntry,
        kind: str,
        spoken_slot: str,
        household_id: str,
        group_id: str,
    ) -> None:
        if (
            kind in {"favorite", "playlist"}
            and entry.sonos_household_id
            and entry.sonos_household_id != household_id
        ):
            self.announcer.say(
                f"Preset {spoken_slot} zapisano dla innego domu Sonos. "
                "Przypisz go ponownie w tym domu. Nic nie uruchomiłem"
            )
            return
        if not household_id or not group_id:
            self.announcer.say(
                "Nie wybrano głośników Sonos. Nic nie uruchomiłem"
            )
            return
        self._sonos_active_household_id = household_id
        self._sonos_active_group_id = group_id
        self._play_sonos_material(PlaySonosMaterial(
            item_id=f"sonos-preset:{entry.slot}",
            title=entry.title or "Preset Sonos",
            household_id=household_id,
            kind=kind,
            material_id=entry.target_id,
        ))

    def _switch_session(
        self,
        session_id: SessionId,
        *,
        configure_frontier_if_empty: bool = True,
    ) -> None:
        if session_id not in session_order.normalize(self.options.session_order):
            self.announcer.say(
                f"Sesja {session_order.session_name(session_id)} jest wyłączona. "
                "Otwórz Menedżer sesji skrótem Ctrl+Shift+S"
            )
            return
        if self.navigator.active is SessionId.TIDAL and session_id is not SessionId.TIDAL:
            self._tidal_navigation_version += 1
        if (
            self.navigator.active is SessionId.SPOTIFY
            and session_id is not SessionId.SPOTIFY
        ):
            self._spotify_navigation_version += 1
        self._run(self.navigator.switch_session(session_id))
        rate_choice = getattr(self, "rate_choice", None)
        if rate_choice is not None:
            rate_choice.SetSelection(PLAYBACK_RATES.index(
                self._session_default_rate(session_id)
            ))
        if session_id is SessionId.PODCASTS:
            state = self.navigator.sessions[SessionId.PODCASTS]
            if not state.model.rows:
                self._open_podcast_library(preferred_id=state.list_anchor_id)
        elif session_id is SessionId.TIDAL:
            state = self.navigator.sessions[SessionId.TIDAL]
            if not state.model.rows:
                self._open_tidal_view(OpenTidalView(
                    LibraryView.TIDAL_LIBRARY,
                    preferred_id=state.list_anchor_id,
                ))
        elif session_id is SessionId.SPOTIFY:
            state = self.navigator.sessions[SessionId.SPOTIFY]
            if not state.model.rows:
                self._open_spotify_view(OpenSpotifyView(
                    preferred_id=state.list_anchor_id,
                ))
        elif session_id is SessionId.WIIM:
            state = self.navigator.sessions[SessionId.WIIM]
            if not state.model.rows:
                self._load_wiim_devices(preferred_id=state.list_anchor_id)
        elif session_id is SessionId.FRONTIER_SMART:
            state = self.navigator.sessions[SessionId.FRONTIER_SMART]
            if not state.model.rows and configure_frontier_if_empty:
                self._load_frontier_smart_devices(
                    preferred_id=state.list_anchor_id,
                    configure_if_empty=True,
                )
        elif session_id is SessionId.RADIOARCHIWISTA:
            state = self.navigator.sessions[SessionId.RADIOARCHIWISTA]
            if not state.model.rows:
                self._open_radioarchiwista_stations(
                    preferred_id=state.list_anchor_id
                )
        elif session_id is SessionId.SONOS:
            state = self.navigator.sessions[SessionId.SONOS]
            if not state.model.rows:
                self._load_sonos_targets(preferred_id=state.list_anchor_id)

    def _session_readiness(self) -> dict[SessionId, str]:
        """Tylko lokalne, już znane stany; samo otwarcie niczego nie loguje."""

        ready = {
            SessionId.FILES: "Gotowa",
            SessionId.RADIO: "Gotowa",
            SessionId.PODCASTS: "Gotowa",
            SessionId.WIIM: (
                "Gotowa"
                if getattr(self, "_wiim_active_device_id", "")
                or self.navigator.sessions[SessionId.WIIM].model.rows
                else "Wymaga wybrania urządzenia"
            ),
            SessionId.FRONTIER_SMART: (
                "Gotowa"
                if getattr(self, "_frontier_smart_active_device_id", "")
                or self.navigator.sessions[SessionId.FRONTIER_SMART].model.rows
                else "Wymaga wybrania urządzenia"
            ),
            SessionId.SONOS: (
                "Gotowa"
                if getattr(self, "_sonos_active_group_id", "")
                or self.navigator.sessions[SessionId.SONOS].sonos_target_rows
                else "Wymaga zalogowania"
            ),
            SessionId.RADIOARCHIWISTA: (
                "Gotowa"
                if self.navigator.sessions[SessionId.RADIOARCHIWISTA].model.rows
                else "Wymaga wczytania katalogu nagrań"
            ),
            SessionId.SPOTIFY: (
                "Połączona, odtwarzanie ograniczone"
                if getattr(self, "_spotify_account_connected", None) is True
                else "Wymaga zalogowania"
            ),
            SessionId.TIDAL: "Wymaga zalogowania",
        }
        try:
            cached = self.tidal.load_view(TIDAL_VIEW_LIBRARY)
        except (OSError, ValueError, TidalProfileError):
            pass
        else:
            if cached.rows:
                ready[SessionId.TIDAL] = "Połączona, odtwarzanie ograniczone"
        return ready

    # ---------------------------------------------------- Radio Archiwista

    def _radioarchiwista_source(self):
        """Źródło katalogu nagrań; None, gdy profil nie ma tej sesji."""

        source = getattr(self, "_radioarchiwista", None)
        if source is None:
            if _radioarchiwista_module is None:
                return None
            source = _radioarchiwista_module.RadioarchiwistaSource(
                Path(self.layout.lite_settings_dir) / "radioarchiwista"
            )
            self._radioarchiwista = source
        return source

    def _open_radioarchiwista_stations(
        self,
        preferred_id: str | None = None,
        *,
        refresh: bool = False,
    ) -> None:
        """Stacje katalogu nagrań ze skrótem „Najnowsze” na górze."""

        source = self._radioarchiwista_source()
        if source is None:
            self.announcer.say(i18n.tr("rarch.session.unavailable"))
            return
        self.announcer.say(
            i18n.tr("rarch.catalog.refreshing" if refresh else "rarch.catalog.loading")
        )

        def work() -> list[Row]:
            index, _from_cache = source.stations(force=refresh)
            rows = _radioarchiwista_module.station_rows(index)
            rows.insert(0, Row(
                item_id="rarch:latest",
                title=i18n.tr("rarch.latest.menu"),
                kind="folder",
                show_kind=False,
                service_kind="rarchLatest",
            ))
            return rows

        def done(rows: list[Row]) -> None:
            self._radioarchiwista_hours_loaded = 0
            self._run(self.navigator.apply_radioarchiwista_rows(
                LibraryView.RADIOARCHIWISTA_STATIONS,
                rows,
                preferred_id=preferred_id,
            ))

        def failed(error: Exception) -> None:
            self._run(self.navigator.apply_radioarchiwista_message(
                i18n.tr("rarch.error", error=error)
            ))

        self.runner.submit("radioarchiwista", work, done, failed)

    def _open_radioarchiwista_level(self, intent: OpenRadioarchiwistaLevel) -> None:
        """Jeden poziom katalogu: lata, miesiące, dni albo nagrania dnia."""

        source = self._radioarchiwista_source()
        if source is None:
            self.announcer.say(i18n.tr("rarch.session.unavailable"))
            return

        def work() -> tuple[LibraryView, list[Row]]:
            if intent.view is LibraryView.RADIOARCHIWISTA_YEARS:
                years, _cached = source.years(intent.slug, force=intent.refresh)
                rows = _radioarchiwista_module.year_rows(intent.slug, years)
            elif intent.view is LibraryView.RADIOARCHIWISTA_MONTHS:
                months, _cached = source.months(
                    intent.slug, intent.year or 0, force=intent.refresh
                )
                rows = _radioarchiwista_module.month_rows(
                    intent.slug, intent.year or 0, months
                )
            elif intent.view is LibraryView.RADIOARCHIWISTA_DAYS:
                days, _cached = source.days(
                    intent.slug,
                    intent.year or 0,
                    intent.month or 0,
                    force=intent.refresh,
                )
                rows = _radioarchiwista_module.day_rows(
                    intent.slug, intent.year or 0, intent.month or 0, days
                )
            else:
                recordings, _cached = source.recordings(
                    intent.slug,
                    intent.year or 0,
                    intent.month or 0,
                    intent.day or 0,
                    force=intent.refresh,
                )
                if intent.load_more:
                    self._radioarchiwista_hours_loaded += (
                        _radioarchiwista_module.PAGE_SIZE
                    )
                else:
                    self._radioarchiwista_hours_loaded = (
                        _radioarchiwista_module.PAGE_SIZE
                    )
                rows = _radioarchiwista_module.recording_rows(
                    recordings,
                    positions=source.load_positions(),
                    favorite_ids=source.favorite_ids(),
                    loaded_count=self._radioarchiwista_hours_loaded,
                )
            return intent.view, rows

        def done(result: tuple[LibraryView, list[Row]]) -> None:
            view, rows = result
            self._run(self.navigator.apply_radioarchiwista_rows(
                view,
                rows,
                slug=intent.slug,
                year=intent.year,
                month=intent.month,
                day=intent.day,
                preferred_id=intent.preferred_id,
            ))

        def failed(error: Exception) -> None:
            self._run(self.navigator.apply_radioarchiwista_message(
                i18n.tr("rarch.error", error=error)
            ))

        self.runner.submit("radioarchiwista", work, done, failed)

    def _open_radioarchiwista_latest(self, *, refresh: bool = False) -> None:
        """Nagrania ostatniej opublikowanej godziny ze wszystkich stacji."""

        source = self._radioarchiwista_source()
        if source is None:
            self.announcer.say(i18n.tr("rarch.session.unavailable"))
            return
        self.announcer.say(i18n.tr("rarch.latest.loading"))

        def work() -> tuple[list[Row], str]:
            recordings, stamp = source.latest_recordings(force=refresh)
            rows = _radioarchiwista_module.latest_rows(
                recordings,
                positions=source.load_positions(),
                favorite_ids=source.favorite_ids(),
            )
            # Godzina w czasie lokalnym stacji, nie UTC: znacznik katalogu
            # mylil sluchacza polskich stacji (23:00 UTC to polskie 00:00/01:00).
            label = _radioarchiwista_module.latest_local_label(recordings, stamp)
            return rows, label

        def done(result: tuple[list[Row], str]) -> None:
            rows, label = result
            self._radioarchiwista_hours_loaded = len(rows)
            count = sum(1 for row in rows if row.kind != "loadMore")
            self._run(self.navigator.apply_radioarchiwista_rows(
                LibraryView.RADIOARCHIWISTA_HOURS,
                rows,
                announcement=i18n.tr(
                    "rarch.latest.announcement",
                    label=label,
                    phrase=i18n.recordings_phrase(count),
                ),
            ))

        def failed(error: Exception) -> None:
            self._run(self.navigator.apply_radioarchiwista_message(
                i18n.tr("rarch.error", error=error)
            ))

        self.runner.submit("radioarchiwista", work, done, failed)

    def _open_radioarchiwista_favorites(
        self, preferred_id: str | None = None,
    ) -> None:
        """Ulubione nagrania: w pełni offline, bez dotykania katalogu."""

        source = self._radioarchiwista_source()
        if source is None:
            self.announcer.say(i18n.tr("rarch.session.unavailable"))
            return

        def work() -> list[Row]:
            return _radioarchiwista_module.favorite_rows(
                source.load_favorites(),
                positions=source.load_positions(),
            )

        def done(rows: list[Row]) -> None:
            self._run(self.navigator.apply_radioarchiwista_rows(
                LibraryView.RADIOARCHIWISTA_FAVORITES,
                rows,
                preferred_id=preferred_id,
            ))

        def failed(error: Exception) -> None:
            self._run(self.navigator.apply_radioarchiwista_message(
                i18n.tr("rarch.error", error=error)
            ))

        self.runner.submit("radioarchiwista", work, done, failed)

    def _toggle_radioarchiwista_favorite(self) -> None:
        """Przełącz ulubione zaznaczonego nagrania i odśwież jego wiersz."""

        state = self.navigator.sessions[SessionId.RADIOARCHIWISTA]
        row = state.model.selected_row
        if row is None or row.kind != "recording":
            self.announcer.say(i18n.tr("rarch.selectForFavorite"))
            return
        source = self._radioarchiwista_source()
        if source is None:
            self.announcer.say(i18n.tr("rarch.session.unavailable"))
            return

        def work() -> tuple[bool, str]:
            recording = source.recording_by_id(row.item_id)
            if recording is None:
                raise _radioarchiwista_module.RadioarchiwistaError(
                    "Nie znam tego nagrania"
                )
            return source.toggle_favorite(recording), recording.title

        def done(result: tuple[bool, str]) -> None:
            added, title = result
            prefix = "\u2605 " if added else ""
            refreshed = [
                replace(
                    candidate,
                    state_prefix=(
                        prefix if candidate.item_id == row.item_id
                        else candidate.state_prefix
                    ),
                )
                for candidate in state.model.rows
            ]
            state.model.replace(refreshed, preferred_id=row.item_id)
            message = i18n.tr(
                "rarch.favorite.added" if added else "rarch.favorite.removed",
                title=title,
            )
            self._run(self.navigator.apply_radioarchiwista_message(message))

        def failed(error: Exception) -> None:
            self._run(self.navigator.apply_radioarchiwista_message(
                i18n.tr("rarch.error", error=error)
            ))

        self.runner.submit("radioarchiwista", work, done, failed)

    def _download_radioarchiwista_recording(self) -> None:
        """Pobierz zaznaczone nagranie do folderu profilu Pythona."""

        state = self.navigator.sessions[SessionId.RADIOARCHIWISTA]
        row = state.model.selected_row
        if row is None or row.kind != "recording" or not row.url:
            self.announcer.say(i18n.tr("rarch.selectForDownload"))
            return
        if row.item_id in self._radioarchiwista_downloads:
            self.announcer.say(i18n.tr("rarch.download.busy"))
            return
        source = self._radioarchiwista_source()
        if source is None:
            self.announcer.say(i18n.tr("rarch.session.unavailable"))
            return
        target_dir = Path(self.layout.lite_settings_dir) / "radioarchiwista" / "pobrane"

        def work() -> Path:
            recording = source.recording_by_id(row.item_id)
            label = (
                recording.local_label
                if recording is not None and recording.local_label
                else f"{row.service_id or 'nagranie'} {row.title}"
            )
            safe = re.sub(r"[^A-Za-z0-9._-]+", "-", label).strip("-")[:100]
            return _radioarchiwista_module.stream_to_file(
                row.url,
                target_dir / f"{safe}.mp3",
            )

        def done(path: Path) -> None:
            self._radioarchiwista_downloads.discard(row.item_id)
            self.announcer.say(i18n.tr("rarch.download.done", path=path))

        def failed(error: Exception) -> None:
            self._radioarchiwista_downloads.discard(row.item_id)
            self._run(self.navigator.apply_radioarchiwista_message(
                i18n.tr("rarch.download.failed", error=error)
            ))

        self._radioarchiwista_downloads.add(row.item_id)
        self.announcer.say(i18n.tr("rarch.download.started"))
        self.runner.submit("radioarchiwista", work, done, failed)

    def _refresh_radioarchiwista_view(self) -> None:
        """F5: ponowne wczytanie bieżącego poziomu z pominięciem cache."""

        state = self.navigator.sessions[SessionId.RADIOARCHIWISTA]
        view = state.library_view
        if view is None or view is LibraryView.RADIOARCHIWISTA_STATIONS:
            self._open_radioarchiwista_stations(
                state.model.selected_id, refresh=True
            )
        elif view is LibraryView.RADIOARCHIWISTA_FAVORITES:
            self._open_radioarchiwista_favorites()
        else:
            self._open_radioarchiwista_level(OpenRadioarchiwistaLevel(
                view,
                state.radioarchiwista_slug,
                year=state.radioarchiwista_year,
                month=state.radioarchiwista_month,
                day=state.radioarchiwista_day,
                refresh=True,
                preferred_id=state.model.selected_id,
            ))

    def _sessions_blocked_from_disabling(self) -> set[SessionId]:
        """Wewnętrzne odtwarzanie i nagrywanie; urządzeń nie zatrzymujemy."""

        blocked = {
            session
            for session in self.__dict__.get("_playing_sessions", set())
            if session not in (
                SessionId.WIIM,
                SessionId.SONOS,
                SessionId.FRONTIER_SMART,
                SessionId.TIDAL,
            )
        }
        pending = self.__dict__.get("_pending_playback_session")
        if pending is not None and pending not in (
            SessionId.WIIM,
            SessionId.SONOS,
            SessionId.FRONTIER_SMART,
            SessionId.TIDAL,
        ):
            blocked.add(pending)
        recordings = (self.__dict__.get("_last_recording_status", {}) or {}).get(
            "recordings"
        )
        if (
            isinstance(recordings, list) and bool(recordings)
            or int((self.__dict__.get("_last_recording_status", {}) or {}).get("count") or 0)
            > 0
        ):
            blocked.add(SessionId.RADIO)
        return blocked

    def _toggle_session_enabled(
        self,
        session_id: SessionId,
        *,
        disable_only: bool = False,
    ) -> tuple[object, str]:
        previous = list(self.options.session_order)
        active = session_order.normalize(previous)
        if session_id not in active:
            if disable_only:
                return active, f"{session_order.session_name(session_id)} jest już wyłączona"
            changed, message = session_order.enable(session_id, active)
            new_current = self.navigator.active
        else:
            changed, new_current, message = session_order.disable(
                session_id,
                active,
                current=self.navigator.active,
                blocked=self._sessions_blocked_from_disabling(),
            )
        if tuple(changed) == tuple(active):
            return changed, message
        self.options.session_order = [item.value for item in changed]
        previous_current = self.navigator.active
        if new_current is not previous_current:
            # Migawka zapisywana w tej samej transakcji ma już wskazywać
            # aktywną, włączoną sesję. W razie błędu oba pola wracają razem.
            self.navigator.active = new_current
        if not self._save_state():
            self.options.session_order = previous
            self.navigator.active = previous_current
            return active, "Nie udało się zapisać zmiany sesji"
        if new_current is not previous_current:
            self.navigator.active = previous_current
        self._build_menu()
        if new_current is not self.navigator.active:
            self._transient_preview_return = None
            self._switch_session(new_current)
            slot = session_order.slot_for_session(new_current, changed)
            message += (
                f". Aktywna sesja: {session_order.session_name(new_current)}, "
                f"Ctrl+{slot}"
            )
        return changed, message

    def _move_managed_session(
        self,
        session_id: SessionId,
        direction: int,
    ) -> tuple[object, str]:
        previous = list(self.options.session_order)
        changed, message = session_order.move(session_id, direction, previous)
        if tuple(changed) == tuple(session_order.normalize(previous)):
            return changed, message
        self.options.session_order = [item.value for item in changed]
        if not self._save_state():
            self.options.session_order = previous
            return session_order.normalize(previous), "Nie udało się zapisać kolejności sesji"
        self._build_menu()
        return changed, message

    def _configure_session(self, session_id: SessionId) -> None:
        if session_id not in session_order.normalize(self.options.session_order):
            self.announcer.say(
                "Najpierw włącz tę sesję Spacją w Menedżerze sesji"
            )
            return
        self._switch_session(
            session_id,
            configure_frontier_if_empty=(
                session_id is not SessionId.FRONTIER_SMART
            ),
        )
        if session_id is SessionId.FILES:
            wx.CallAfter(self._show_library_folders)
            return
        if session_id in (SessionId.RADIO, SessionId.PODCASTS):
            wx.CallAfter(self._show_session_options)
            return
        if session_id in (SessionId.SPOTIFY, SessionId.TIDAL):
            self._show_service_account(session_id)
            return
        if session_id is SessionId.WIIM:
            state = self.navigator.sessions[SessionId.WIIM]
            self.announcer.say("Odświeżam zapisane urządzenia WiiM")
            self._load_wiim_devices(preferred_id=state.list_anchor_id)
            return
        if session_id is SessionId.FRONTIER_SMART:
            wx.CallAfter(self._show_frontier_smart_devices)
            return
        if session_id is SessionId.SONOS:
            self._show_sonos_account()
            return

    def _show_library_folders(self) -> None:
        client = self._profile_edit_client()
        if client is None:
            return
        try:
            payload = client.local_folder_sources()
        except (HostError, HostUnavailable) as error:
            self.announcer.say(str(error))
            return
        except Exception:
            self.announcer.say("Nie można teraz odczytać Folderów Biblioteki")
            return

        def submit(
            task_name: str,
            work: Callable[[], object],
            dialog: LibraryFoldersDialog,
            preferred_id: str | None = None,
        ) -> None:
            def done(result: object) -> None:
                if not dialog.IsBeingDeleted():
                    dialog.finish(result, preferred_id)
                if self.navigator.active is SessionId.FILES:
                    self._refresh_profile_view()

            def failed(error: Exception) -> None:
                message = (
                    str(error)
                    if isinstance(error, (HostError, HostUnavailable))
                    else "Operacja na Folderach Biblioteki nie powiodła się"
                )
                if not dialog.IsBeingDeleted():
                    dialog.fail(message)

            self.runner.submit(task_name, work, done, failed)

        def add_folder(path: str, dialog: LibraryFoldersDialog) -> None:
            submit(
                "library-folder-add",
                lambda: client.add_local_folder_source(path),
                dialog,
            )

        def refresh_folders(
            source_ids: list[str],
            dialog: LibraryFoldersDialog,
        ) -> None:
            preferred = source_ids[0] if len(source_ids) == 1 else None
            submit(
                "library-folder-refresh",
                lambda: client.refresh_local_folder_sources(source_ids),
                dialog,
                preferred,
            )

        def detach_folder(source_id: str, dialog: LibraryFoldersDialog) -> None:
            submit(
                "library-folder-detach",
                lambda: client.detach_local_folder_source(source_id),
                dialog,
            )

        with LibraryFoldersDialog(
            self,
            payload,
            add_folder=add_folder,
            refresh_folders=refresh_folders,
            detach_folder=detach_folder,
        ) as dialog:
            dialog.ShowModal()
        self._restore_focus_after_dialog()

    def _refresh_local_library(self) -> None:
        client = self._profile_edit_client()
        if client is None:
            return
        self.announcer.say("Odświeżanie Folderów Biblioteki")

        def done(result: object) -> None:
            message = result.get("message") if isinstance(result, dict) else None
            self._refresh_profile_view()
            self.announcer.say(
                message.strip()
                if isinstance(message, str) and message.strip()
                else "Odświeżono Foldery Biblioteki"
            )

        def failed(error: Exception) -> None:
            self.announcer.say(
                str(error)
                if isinstance(error, (HostError, HostUnavailable))
                else "Nie można teraz odświeżyć Folderów Biblioteki"
            )

        self.runner.submit(
            "library-folders-refresh-all",
            lambda: client.refresh_local_folder_sources([]),
            done,
            failed,
        )

    @staticmethod
    def _service_account_status_message(
        session_id: SessionId,
        payload: object,
    ) -> str:
        if not isinstance(payload, dict):
            return "Nie można teraz odczytać stanu konta."
        if session_id is SessionId.TIDAL:
            label = payload.get("label")
            return label.strip() if isinstance(label, str) and label.strip() else (
                "Nie można teraz odczytać stanu konta TIDAL."
            )
        labels: list[str] = []
        for key in ("catalog", "playback"):
            part = payload.get(key)
            if not isinstance(part, dict):
                continue
            label = part.get("label")
            if isinstance(label, str) and label.strip():
                labels.append(label.strip())
        return " ".join(labels) or "Nie można teraz odczytać stanu konta Spotify."

    def _show_service_account(self, session_id: SessionId) -> None:
        client = self.client
        service_name = "Spotify" if session_id is SessionId.SPOTIFY else "TIDAL"
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        try:
            payload = (
                client.spotify_account_status()
                if session_id is SessionId.SPOTIFY
                else client.tidal_account_status()
            )
            status = self._service_account_status_message(session_id, payload)
        except (HostError, HostUnavailable) as error:
            status = str(error)
        except Exception:
            status = f"Nie można teraz odczytać stanu konta {service_name}."

        def start_login(dialog: ServiceAccountDialog) -> None:
            def work() -> object:
                return (
                    client.spotify_login()
                    if session_id is SessionId.SPOTIFY
                    else client.tidal_login()
                )

            def done(result: object) -> None:
                message = "Zalogowano konto."
                if isinstance(result, dict):
                    returned = result.get("message")
                    if isinstance(returned, str) and returned.strip():
                        message = returned.strip()
                if session_id is SessionId.SPOTIFY:
                    cache = getattr(self, "_service_destination_cache", None)
                    if isinstance(cache, ServiceDestinationCache):
                        cache.invalidate("spotify:playlists")
                if not dialog.IsBeingDeleted():
                    dialog.finish(message)
                self.announcer.say(message)

            def failed(error: Exception) -> None:
                message = (
                    str(error)
                    if isinstance(error, (HostError, HostUnavailable))
                    else f"Nie udało się zalogować konta {service_name}."
                )
                if not dialog.IsBeingDeleted():
                    dialog.finish(message)
                self.announcer.say(message)

            self.runner.submit(
                f"{session_id.value}-account-login",
                work,
                done,
                failed,
            )

        with ServiceAccountDialog(
            self,
            service_name,
            status,
            start_login,
        ) as dialog:
            # Statyczny tekst stanu nie zawsze jest automatycznie czytany,
            # ponieważ fokus trafia na przycisk logowania. Zlecenie po wejściu
            # w pętlę modalną daje jeden jawny komunikat bez uruchamiania OAuth.
            wx.CallAfter(self.announcer.say, status)
            dialog.ShowModal()
        self._restore_focus_after_dialog()

    def _show_youtube_account(self) -> None:
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        if not self._youtube_account_available:
            self.announcer.say(
                "Logowanie YouTube nie jest skonfigurowane w tej wersji AMC Test"
            )
            return
        try:
            initial_status = client.youtube_account_status()
        except (HostError, HostUnavailable) as error:
            initial_status = {"message": str(error), "connected": False}
        except Exception:
            initial_status = {
                "message": "Nie można teraz odczytać stanu konta YouTube.",
                "connected": False,
            }

        def run_action(action: str, dialog: YouTubeAccountDialog) -> None:
            if action == "logout":
                question = (
                    "Cofnąć dostęp AMC do YouTube w Google i usunąć z tego "
                    "profilu kanały, playlisty oraz materiały pobrane z konta? "
                    "Nie usuwa to danych zapisanych w YouTube ani publicznych "
                    "źródeł, które nie zostały utworzone lub zaktualizowane "
                    "przez synchronizację konta."
                    if _RELEASE_PROFILE.profile_id == "public"
                    else (
                        "Wylogować konto YouTube z AMC? Zapisane połączenie "
                        "zostanie usunięte tylko z bieżącego profilu AMC. "
                        "Nie zmienia to hasła ani konta Google i YouTube."
                    )
                )
                caption = (
                    "Cofnięcie dostępu YouTube"
                    if _RELEASE_PROFILE.profile_id == "public"
                    else "Wylogowanie YouTube z AMC"
                )
                with wx.MessageDialog(
                    dialog,
                    question,
                    caption,
                    wx.YES_NO | wx.NO_DEFAULT | wx.ICON_WARNING,
                ) as confirm:
                    if confirm.ShowModal() != wx.ID_YES:
                        dialog.set_busy(None)
                        dialog.logout_button.SetFocus()
                        return

            restore_deleted = dialog.restore_deleted_channels

            def work() -> tuple[object, object]:
                if action == "login":
                    result = client.youtube_account_login()
                elif action == "cancelLogin":
                    result = client.youtube_account_cancel_login()
                elif action == "logout":
                    result = client.youtube_account_logout()
                elif action == "preview":
                    result = client.youtube_subscription_sync_preview(
                        restore_suppressed=restore_deleted
                    )
                elif action == "apply":
                    result = client.youtube_subscription_sync_apply(
                        restore_suppressed=restore_deleted
                    )
                elif action == "previewPlaylists":
                    result = client.youtube_playlist_sync_preview(
                        restore_suppressed=restore_deleted
                    )
                elif action == "applyPlaylists":
                    result = client.youtube_playlist_sync_apply(
                        restore_suppressed=restore_deleted
                    )
                else:
                    raise ValueError("Nieobsługiwana operacja konta YouTube")
                return result, client.youtube_account_status()

            def done(payload: tuple[object, object]) -> None:
                result, status = payload
                message = youtube_safe_message(
                    result,
                    "Zakończono operację konta YouTube.",
                )
                if action == "login" and youtube_account_connected(status):
                    message = (
                        "Zalogowano do YouTube. Wybierz Sprawdź subskrypcje albo "
                        "Sprawdź playlisty. Podgląd nie zmieni Biblioteki, dopóki "
                        "osobno nie wybierzesz odpowiedniego przycisku Zapisz."
                    )
                if not dialog.IsBeingDeleted():
                    dialog.finish(action, result, status)
                    if action == "login" and youtube_account_connected(status):
                        dialog._set_status(message)
                _append_frontend_log(
                    self.store,
                    f"Konto YouTube, operacja {action}: {message}",
                )
                if action in {"apply", "applyPlaylists"} and self.navigator.active is SessionId.PODCASTS:
                    self._refresh_profile_view()
                self.announcer.say(message)

            def failed(error: Exception) -> None:
                message = (
                    str(error)
                    if isinstance(error, (HostError, HostUnavailable))
                    else "Operacja konta YouTube nie powiodła się."
                )
                if not dialog.IsBeingDeleted():
                    dialog.fail(message)
                _append_frontend_log(
                    self.store,
                    f"Konto YouTube, operacja {action}: {message}",
                )
                self.announcer.say(message)

            # Jedna nazwa strumienia unieważnia spóźniony wynik logowania,
            # gdy użytkownik naciśnie Anuluj. Sam host kończy wtedy pętlę OAuth.
            self.runner.submit(
                "youtube-account-operation",
                work,
                done,
                failed,
            )

        with YouTubeAccountDialog(
            self,
            initial_status,
            run_action=run_action,
        ) as dialog:
            wx.CallAfter(
                self.announcer.say,
                youtube_safe_message(
                    initial_status,
                    "Nie można teraz odczytać stanu konta YouTube.",
                ),
            )
            dialog.ShowModal()
        self._restore_focus_after_dialog()

    @staticmethod
    def _sonos_account_message(payload: object) -> str:
        if not isinstance(payload, dict):
            return "Nie można teraz odczytać stanu konta Sonos."
        for key in ("message", "label"):
            value = payload.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        return "Nie można teraz odczytać stanu konta Sonos."

    def _show_sonos_account(self, initial_payload: object | None = None) -> None:
        existing = self._sonos_account_dialog
        if existing is not None:
            try:
                if not existing.IsBeingDeleted():
                    existing.Show()
                    existing.Raise()
                    existing.focus_primary_action()
                    return
            except RuntimeError:
                # Obiekt wx może być już zniszczony pomiędzy zdarzeniami.
                pass
            self._sonos_account_dialog = None

        client = self.client
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        if initial_payload is None:
            try:
                initial_payload = client.sonos_account_status()
            except (HostError, HostUnavailable) as error:
                initial_payload = {"message": str(error)}
            except Exception:
                initial_payload = {
                    "message": "Nie można teraz odczytać stanu konta Sonos."
                }

        operations: dict[str, Callable[[], object]] = {
            "loginStart": client.sonos_account_login_start,
            "loginCheck": client.sonos_account_login_check,
            "loginCancel": client.sonos_account_login_cancel,
            "refresh": client.sonos_account_refresh,
            "persistRetry": client.sonos_account_persist_retry,
            "disconnect": client.sonos_account_disconnect,
        }

        def run_action(action: str, dialog: SonosAccountDialog) -> None:
            work = operations.get(action)
            if work is None:
                dialog.fail("Ta operacja konta Sonos nie jest dostępna.")
                return
            if action == "disconnect":
                with wx.MessageDialog(
                    dialog,
                    (
                        "Wylogować konto Sonos z AMC? Zapisane połączenie zostanie "
                        "usunięte z tego profilu. Nie zmienia to hasła ani konta "
                        "na stronie Sonos."
                    ),
                    "Wylogowanie Sonos",
                    wx.YES_NO | wx.NO_DEFAULT | wx.ICON_WARNING,
                ) as confirm:
                    if confirm.ShowModal() != wx.ID_YES:
                        dialog.set_busy(False)
                        dialog.disconnect_button.SetFocus()
                        return

            def done(result: object) -> None:
                if (
                    action == "disconnect"
                    and isinstance(result, dict)
                    and not bool(result.get("connected"))
                ):
                    self._sonos_active_household_id = None
                    self._sonos_active_group_id = None
                    self._sonos_browse_household_id = None
                message = self._sonos_account_message(result)
                if (
                    self._sonos_account_dialog is dialog
                    and not dialog.IsBeingDeleted()
                ):
                    dialog.finish(
                        result,
                        open_browser=action == "loginStart",
                    )
                self.announcer.say(message)

            def failed(error: Exception) -> None:
                message = (
                    str(error)
                    if isinstance(error, (HostError, HostUnavailable))
                    else "Operacja konta Sonos nie powiodła się."
                )
                if (
                    self._sonos_account_dialog is dialog
                    and not dialog.IsBeingDeleted()
                ):
                    dialog.fail(message)
                self.announcer.say(message)

            self.runner.submit(
                f"sonos-account-{action}",
                work,
                done,
                failed,
            )

        dialog = SonosAccountDialog(
            self,
            initial_payload,
            run_action=run_action,
            copy_address=lambda address: self._to_clipboard(address),
        )
        self._sonos_account_dialog = dialog
        closed = False

        def close_account(_event: wx.CloseEvent) -> None:
            nonlocal closed
            if closed:
                return
            closed = True
            if self._sonos_account_dialog is dialog:
                self._sonos_account_dialog = None
            open_targets = dialog.open_targets
            browser_opened = dialog.browser_opened
            dialog.Hide()
            wx.CallAfter(dialog.Destroy)
            if browser_opened and self.navigator.active is SessionId.SONOS:
                self._run(self.navigator.apply_sonos_account_pending_prompt())
            else:
                wx.CallAfter(self._restore_focus_after_dialog)
            if open_targets:
                wx.CallAfter(
                    self._load_sonos_targets,
                    self.navigator.sessions[SessionId.SONOS].list_anchor_id,
                )

        dialog.Bind(wx.EVT_CLOSE, close_account)
        wx.CallAfter(
            self.announcer.say,
            LiteFrame._sonos_account_message(initial_payload),
        )
        dialog.Show()
        dialog.Raise()
        dialog.focus_primary_action()

    def _show_session_list(self, *, focus_inactive: bool = False) -> None:
        """Ctrl+Shift+S i dodatek NVDA: jeden Menedżer sesji."""
        with SessionSelectionDialog(
            self,
            self.navigator.active,
            self.options.session_order,
            self._session_readiness(),
            toggle_session=self._toggle_session_enabled,
            move_session=self._move_managed_session,
            settings_session=lambda session, parent: self._show_session_options(
                session_id=session, parent=parent
            ),
            focus_inactive=focus_inactive,
        ) as dialog:
            result = dialog.ShowModal()
            selected = dialog.selected_session
            configure = dialog.configure_session
            if result not in (wx.ID_OK, wx.ID_APPLY):
                self._restore_focus_after_dialog()
                return
        if result == wx.ID_APPLY and configure is not None:
            self._restore_focus_after_dialog()
            wx.CallAfter(self._configure_session, configure)
        elif selected is not None:
            self._transient_preview_return = None
            self._switch_session(selected)
            # Gdy użytkownik zatwierdzi już aktywną sesję, _sync_views nie
            # zmienia widoku i celowo nie ustawia fokusu ponownie. Po zamknięciu
            # dialogu lista albo odtwarzacz nadal muszą jednak odzyskać fokus.
            wx.CallAfter(self._restore_focus_after_dialog)

    def _show_command_palette(self) -> None:
        # Paleta korzysta z dokładnie tych samych bramek co menu. Dzięki temu
        # zmienia się nie tylko między sesjami, ale również między widokami i
        # po zmianie zaznaczenia; nie proponuje polecenia, które po Enterze
        # zostałoby odrzucone jako niedostępne.
        self._refresh_menu_state()
        available_actions = {
            entry.action
            for item, entry in getattr(self, "_menu_items", ())
            if entry.action is not None and item.IsEnabled()
        }
        entries = command_entries_for_session(
            self.navigator.active,
            self.options.session_order,
            youtube_account_available=self._youtube_account_available,
            shortcut_overrides=getattr(self, "shortcut_overrides", {}),
        )
        entries = available_command_entries(entries, available_actions)
        with CommandPaletteDialog(self, entries) as dialog:
            if dialog.ShowModal() != wx.ID_OK:
                self._restore_focus_after_dialog()
                return
            selected = dialog.selected_entry
        self._restore_focus_after_dialog()
        if selected is not None:
            self._dispatch(selected.action)

    # --------------------------------------------------------------- WiiM

    def _load_wiim_devices(self, preferred_id: str | None = None) -> None:
        """Wczytaj wyłącznie zapisane urządzenia; adresy pozostają w C#."""
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return

        def done(payload: object) -> None:
            try:
                rows = list(wiim_device_rows(payload))
            except WiiMPayloadError as error:
                self.announcer.say(str(error))
                return
            state = self.navigator.sessions[SessionId.WIIM]
            # Pierwszenstwo ma wybor z prywatnego stanu AMC Python albo
            # urzadzenie uzywane w tym procesie. Pole ``selected`` hosta jest
            # tylko zgodnosciowym fallbackiem starego profilu i nie moze za
            # kazdym razem przestawiac fokusu z Pro Plus na WiiM Sound.
            selected_id = preferred_id or state.wiim_device_return_id
            if selected_id is None and self._wiim_active_device_id:
                active_row = next((
                    row for row in rows
                    if row.service_id == self._wiim_active_device_id
                ), None)
                if active_row is not None:
                    selected_id = active_row.item_id
            if selected_id is None and isinstance(payload, dict):
                raw_items = payload.get("items")
                if isinstance(raw_items, list):
                    selected = next((
                        item for item in raw_items
                        if isinstance(item, dict) and item.get("selected") is True
                    ), None)
                    if isinstance(selected, dict):
                        candidate = selected.get("itemId")
                        if isinstance(candidate, str) and any(
                            row.item_id == candidate for row in rows
                        ):
                            selected_id = candidate
            events = self.navigator.apply_wiim_devices(rows, selected_id)
            if self.navigator.active is SessionId.WIIM:
                self._run(events)
            else:
                self._sync_views()

        self.runner.submit(
            "wiim-devices",
            client.wiim_devices,
            done,
            lambda error: self.announcer.say(
                f"Nie udało się odczytać urządzeń WiiM: {error}"
            ),
        )

    def _activate_wiim_device(self, intent: ActivateWiiMDevice) -> None:
        client = self.client
        if client is None:
            self._run(self.navigator.back_to_list())
            self.announcer.say("Silnik nie jest gotowy")
            return
        self._wiim_active_device_id = intent.device_id
        self._wiim_snapshot = {}
        # Tytuł urządzenia jest uczciwym stanem przejściowym, zanim przyjdzie
        # migawka utworu. Nie pokazujemy technicznego identyfikatora.
        self.now_playing.SetLabel(intent.title)
        self._set_transport_label(playing=False, preparing=True)

        def done(payload: object) -> None:
            try:
                state = wiim_snapshot(payload)
            except WiiMPayloadError as error:
                failed(error)
                return
            if state.get("deviceId") != self._wiim_active_device_id:
                return
            self._wiim_snapshot = state
            if (
                self.navigator.active is SessionId.WIIM
                and self.navigator.view is View.PLAYER
            ):
                self._apply_wiim_snapshot(state, announce=True)

        def failed(error: Exception) -> None:
            state = self.navigator.sessions[SessionId.WIIM]
            state.view = View.LIST
            if self.navigator.active is SessionId.WIIM:
                self._sync_views()
                self.announcer.say(str(error))

        self.runner.submit(
            "wiim-snapshot",
            lambda: client.wiim_snapshot(intent.device_id),
            done,
            failed,
        )

    def _apply_wiim_snapshot(
        self, state: dict, *, announce: bool = False
    ) -> None:
        """Pokaż migawkę WiiM bez przepuszczania repr, adresu ani Id."""
        record_history = getattr(
            self, "_record_streamer_history_snapshot", None
        )
        if callable(record_history):
            record_history(SessionId.WIIM, state)
        label = wiim_now_playing_label(state)
        if self.now_playing.GetLabel() != label:
            self.now_playing.SetLabel(label)
        # Nazwa kontrolki jest stałą etykietą pola. Treść utworu pozostaje
        # jego wartością/tekstem, więc po przejściu do innej sesji nie może
        # zostać stara nazwa WiiM czytana nad nowym tytułem.
        self.now_playing.SetName("Teraz odtwarzane")
        time_label = player_time_label(
            state.get("positionSeconds"), state.get("durationSeconds")
        )
        if self.time_label.GetLabel() != time_label:
            self.time_label.SetLabel(time_label)
        volume = int(state.get("volume") or 0)
        if self.volume_slider.GetValue() != volume:
            self.volume_slider.SetValue(volume)
        self.volume_slider.Enable(True)
        playback = str(state.get("playbackState") or "").casefold()
        self._set_transport_label(
            playing=playback in {"odtwarzanie", "playing", "play"}
        )
        apply_activity = getattr(self, "_apply_streamer_activity_status", None)
        if callable(apply_activity):
            apply_activity(SessionId.WIIM)
        if announce:
            message = str(state.get("message") or "").strip()
            self.announcer.say(message or label)

    def _wiim_transport(
        self, command: str, *, volume: int | None = None
    ) -> None:
        client = self.client
        device_id = self._wiim_active_device_id
        if client is None or not device_id:
            self.announcer.say(
                "Brak aktywnego urządzenia WiiM. Naciśnij Enter na urządzeniu"
            )
            return

        def done(payload: object) -> None:
            try:
                state = wiim_snapshot(payload)
            except WiiMPayloadError as error:
                self.announcer.say(str(error))
                return
            if state.get("deviceId") != self._wiim_active_device_id:
                return
            self._wiim_snapshot = state
            if self.navigator.active is SessionId.WIIM:
                self._apply_wiim_snapshot(state, announce=True)

        self.runner.submit(
            "wiim-transport",
            lambda: client.wiim_transport(
                device_id, command, volume=volume
            ),
            done,
            lambda error: self.announcer.say(
                f"Nie udało się sterować urządzeniem WiiM: {error}"
            ),
        )

    def _navigate_wiim_source(self, direction: int) -> None:
        """Alt+Page Up/Down: ten sam zakres źródeł co w pełnym AMC."""
        client = self.client
        device_id = self._wiim_active_device_id
        if (
            client is None
            or not device_id
            or self.navigator.active is not SessionId.WIIM
            or self.navigator.view is not View.PLAYER
        ):
            self.announcer.say(
                "Przechodzenie po źródłach WiiM jest dostępne "
                "w odtwarzaczu urządzenia"
            )
            return

        def done(payload: object) -> None:
            try:
                state = wiim_snapshot(payload)
            except WiiMPayloadError as error:
                self.announcer.say(str(error))
                return
            if (
                self.navigator.active is not SessionId.WIIM
                or self.navigator.view is not View.PLAYER
                or state.get("deviceId") != self._wiim_active_device_id
            ):
                return
            self._wiim_snapshot = state
            self._apply_wiim_snapshot(state, announce=True)
            self.play_button.SetFocus()

        self.runner.submit(
            "wiim-source-navigation",
            lambda: client.wiim_navigate_source(device_id, direction),
            done,
            lambda error: self.announcer.say(str(error)),
        )

    # ------------------------------------------------------ Frontier Smart

    def _apply_frontier_smart_devices_payload(
        self,
        payload: object,
        preferred_id: str | None = None,
    ) -> None:
        rows = list(frontier_smart_device_rows(payload))
        selected_device_id, _message = frontier_smart_device_list_state(payload)
        if selected_device_id:
            self._frontier_smart_active_device_id = selected_device_id
        selected_item_id = preferred_id
        if selected_item_id is None and selected_device_id:
            selected = next((
                row for row in rows if row.service_id == selected_device_id
            ), None)
            if selected is not None:
                selected_item_id = selected.item_id
        events = self.navigator.apply_frontier_smart_devices(
            rows,
            selected_item_id,
        )
        if self.navigator.active is SessionId.FRONTIER_SMART:
            self._run(events)
        else:
            self._sync_views()

    def _load_frontier_smart_devices(
        self,
        preferred_id: str | None = None,
        *,
        configure_if_empty: bool = False,
    ) -> None:
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return

        def done(payload: object) -> None:
            try:
                empty = frontier_smart_should_auto_discover(payload)
                self._apply_frontier_smart_devices_payload(payload, preferred_id)
            except FrontierSmartPayloadError as error:
                self.announcer.say(str(error))
                return
            if (
                configure_if_empty
                and empty
                and self.navigator.active is SessionId.FRONTIER_SMART
            ):
                wx.CallAfter(self._show_frontier_smart_devices, payload)

        self.runner.submit(
            "frontier-smart-devices",
            client.frontier_smart_devices,
            done,
            lambda error: self.announcer.say(
                f"Nie udało się odczytać urządzeń Frontier Smart: {error}"
            ),
        )

    def _show_frontier_smart_devices(
        self,
        initial_payload: object | None = None,
    ) -> None:
        """Otwórz konfigurację dopiero po odczycie hosta poza wątkiem GUI."""
        if getattr(self, "_frontier_smart_configuration_active", False):
            return
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        self._frontier_smart_configuration_active = True
        if initial_payload is None:
            self.announcer.say("Wczytuję urządzenia Frontier Smart")

        def release_with_error(message: str) -> None:
            self._frontier_smart_configuration_active = False
            self.announcer.say(message)

        def ready(initial_payload: object) -> None:
            try:
                self._apply_frontier_smart_devices_payload(initial_payload)
            except FrontierSmartPayloadError as error:
                release_with_error(str(error))
                return

            def alive(dialog: FrontierSmartDevicesDialog) -> bool:
                return not dialog.IsBeingDeleted()

            def failed(
                error: Exception,
                dialog: FrontierSmartDevicesDialog,
                *,
                focus_pin: bool = False,
            ) -> None:
                if alive(dialog):
                    dialog.fail(str(error), focus_pin=focus_pin)

            def finish(
                payload: object,
                dialog: FrontierSmartDevicesDialog,
                preferred_device_id: str | None = None,
                *,
                close_after: bool = False,
            ) -> None:
                try:
                    self._apply_frontier_smart_devices_payload(payload)
                    if alive(dialog):
                        dialog.finish(
                            payload,
                            preferred_device_id,
                            close_after=close_after,
                        )
                except FrontierSmartPayloadError as error:
                    if alive(dialog):
                        dialog.fail(str(error))

            def discover(dialog: FrontierSmartDevicesDialog) -> None:
                def discovered(payload: object) -> None:
                    try:
                        if alive(dialog):
                            dialog.use_discovered(payload)
                    except FrontierSmartPayloadError as error:
                        if alive(dialog):
                            dialog.discovery_failed(str(error))

                self.runner.submit(
                    "frontier-smart-discover",
                    client.frontier_smart_discover,
                    discovered,
                    lambda error: (
                        dialog.discovery_failed(str(error))
                        if alive(dialog)
                        else None
                    ),
                )

            def identify(
                address: str,
                dialog: FrontierSmartDevicesDialog,
            ) -> None:
                def identified(payload: object) -> None:
                    try:
                        if alive(dialog):
                            dialog.use_identified(payload)
                    except FrontierSmartPayloadError as error:
                        if alive(dialog):
                            dialog.discovery_failed(str(error))

                self.runner.submit(
                    "frontier-smart-identify",
                    lambda: client.frontier_smart_identify(address),
                    identified,
                    lambda error: (
                        dialog.discovery_failed(str(error))
                        if alive(dialog)
                        else None
                    ),
                )

            def save(
                address: str,
                pin: str,
                dialog: FrontierSmartDevicesDialog,
            ) -> None:
                self.runner.submit(
                    "frontier-smart-add",
                    lambda: client.frontier_smart_add(address, pin),
                    lambda payload: finish(payload, dialog, close_after=True),
                    lambda error: failed(
                        error,
                        dialog,
                        focus_pin="PIN" in str(error).upper(),
                    ),
                )

            def remove(
                device_id: str,
                dialog: FrontierSmartDevicesDialog,
            ) -> None:
                self.runner.submit(
                    "frontier-smart-remove",
                    lambda: client.frontier_smart_remove(device_id),
                    lambda payload: finish(payload, dialog),
                    lambda error: failed(error, dialog),
                )

            def select(
                device_id: str,
                dialog: FrontierSmartDevicesDialog,
            ) -> None:
                self.runner.submit(
                    "frontier-smart-select",
                    lambda: client.frontier_smart_select(device_id),
                    lambda payload: finish(
                        payload,
                        dialog,
                        device_id,
                        close_after=True,
                    ),
                    lambda error: failed(error, dialog),
                )

            try:
                with FrontierSmartDevicesDialog(
                    self,
                    initial_payload,
                    discover=discover,
                    identify=identify,
                    save=save,
                    remove=remove,
                    select=select,
                    announce=self.announcer.say,
                ) as dialog:
                    dialog.ShowModal()
            finally:
                self._frontier_smart_configuration_active = False
                self._restore_focus_after_dialog()

        if initial_payload is not None:
            ready(initial_payload)
            return
        self.runner.submit(
            "frontier-smart-configure",
            client.frontier_smart_devices,
            ready,
            lambda error: release_with_error(
                f"Nie udało się otworzyć konfiguracji Frontier Smart: {error}"
            ),
        )

    def _activate_frontier_smart_device(
        self,
        intent: ActivateFrontierSmartDevice,
    ) -> None:
        client = self.client
        if client is None:
            self._run(self.navigator.back_to_list())
            self.announcer.say("Silnik nie jest gotowy")
            return
        self._frontier_smart_active_device_id = intent.device_id
        self._frontier_smart_snapshot = {}
        self._frontier_smart_volume_pending = None
        self._frontier_smart_requested_volume = None
        self.now_playing.SetLabel(intent.title)
        self._set_transport_label(playing=False, preparing=True)

        def done(payload: object) -> None:
            try:
                state = frontier_smart_snapshot(payload)
            except FrontierSmartPayloadError as error:
                failed(error)
                return
            if state.get("deviceId") != self._frontier_smart_active_device_id:
                return
            self._frontier_smart_snapshot = state
            if (
                self.navigator.active is SessionId.FRONTIER_SMART
                and self.navigator.view is View.PLAYER
            ):
                self._apply_frontier_smart_snapshot(state, announce=True)

        def failed(error: Exception) -> None:
            state = self.navigator.sessions[SessionId.FRONTIER_SMART]
            state.view = View.LIST
            if self.navigator.active is SessionId.FRONTIER_SMART:
                self._sync_views()
                self.announcer.say(str(error))

        self.runner.submit(
            "frontier-smart-snapshot",
            lambda: client.frontier_smart_snapshot(intent.device_id),
            done,
            failed,
        )

    def _apply_frontier_smart_snapshot(
        self,
        state: dict,
        *,
        announce: bool = False,
    ) -> None:
        label = frontier_smart_now_playing_label(state)
        if self.navigator.active is SessionId.FRONTIER_SMART:
            self.navigator.session.now_playing_title = label
        if self.now_playing.GetLabel() != label:
            self.now_playing.SetLabel(label)
        self.now_playing.SetName("Teraz odtwarzane")
        time_label = player_time_label(
            state.get("positionSeconds"),
            state.get("durationSeconds"),
        )
        if self.time_label.GetLabel() != time_label:
            self.time_label.SetLabel(time_label)
        volume = state.get("volume")
        if (
            isinstance(volume, int)
            and not getattr(self, "_frontier_smart_request_pending", False)
        ):
            self._frontier_smart_requested_volume = volume
        if isinstance(volume, int) and self.volume_slider.GetValue() != volume:
            self.volume_slider.SetValue(volume)
        self.volume_slider.Enable(isinstance(volume, int))
        playback = str(state.get("playbackState") or "").casefold()
        self._set_transport_label(playing=playback == "odtwarzanie")
        self._transport_status_by_session[SessionId.FRONTIER_SMART] = state
        if announce:
            message = str(state.get("message") or "").strip()
            self.announcer.say(message or label)

    def _frontier_smart_transport(
        self,
        command: str,
        *,
        volume: int | None = None,
    ) -> None:
        client = self.client
        device_id = self._frontier_smart_active_device_id
        if client is None or not device_id:
            self.announcer.say(
                "Brak aktywnego urządzenia Frontier Smart. "
                "Naciśnij Enter na urządzeniu"
            )
            return
        if command in {
            "setVolume", "volumeUp5", "volumeDown5", "volumeUp1", "volumeDown1"
        }:
            if command == "setVolume" and volume is not None:
                target = volume
            else:
                delta = {
                    "volumeUp5": 5,
                    "volumeDown5": -5,
                    "volumeUp1": 1,
                    "volumeDown1": -1,
                }.get(command, 0)
                current = self._frontier_smart_requested_volume
                if not isinstance(current, int):
                    current = self._frontier_smart_snapshot.get("volume")
                if not isinstance(current, int):
                    self.announcer.say(
                        "Urządzenie nie podało bieżącej głośności"
                    )
                    return
                target = current + delta
            self._queue_frontier_smart_volume(target)
            return
        if getattr(self, "_frontier_smart_request_pending", False):
            self.announcer.say(
                "Poprzednie polecenie Frontier Smart jeszcze trwa"
            )
            return
        self._frontier_smart_request_pending = True

        def done(payload: object) -> None:
            pending_volume = self._frontier_smart_volume_pending
            self._frontier_smart_request_pending = False
            self._frontier_smart_volume_pending = None
            try:
                state = frontier_smart_snapshot(payload)
            except FrontierSmartPayloadError as error:
                self.announcer.say(str(error))
                return
            if state.get("deviceId") != self._frontier_smart_active_device_id:
                return
            self._frontier_smart_snapshot = state
            if self.navigator.active is SessionId.FRONTIER_SMART:
                self._apply_frontier_smart_snapshot(state, announce=True)
            if isinstance(pending_volume, int):
                self._queue_frontier_smart_volume(pending_volume)

        def failed(error: Exception) -> None:
            self._frontier_smart_request_pending = False
            self._frontier_smart_volume_pending = None
            self.announcer.say(
                f"Nie udało się sterować urządzeniem Frontier Smart: {error}"
            )

        self.runner.submit(
            "frontier-smart-transport",
            lambda: client.frontier_smart_transport(
                device_id,
                command,
                volume=volume,
            ),
            done,
            failed,
        )

    def _queue_frontier_smart_volume(self, value: int) -> None:
        """Scal serię klawiszy do najwyżej jednego oczekującego polecenia."""

        client = self.client
        device_id = self._frontier_smart_active_device_id
        if client is None or not device_id:
            self.announcer.say(
                "Brak aktywnego urządzenia Frontier Smart. "
                "Naciśnij Enter na urządzeniu"
            )
            return
        target = max(0, min(100, int(value)))
        self._frontier_smart_requested_volume = target
        self.volume_slider.SetValue(target)
        if getattr(self, "_frontier_smart_request_pending", False):
            self._frontier_smart_volume_pending = target
            return
        self._frontier_smart_request_pending = True
        self._frontier_smart_volume_pending = None

        def done(payload: object) -> None:
            try:
                state = frontier_smart_snapshot(payload)
            except FrontierSmartPayloadError as error:
                failed(error)
                return
            if state.get("deviceId") != self._frontier_smart_active_device_id:
                self._frontier_smart_request_pending = False
                self._frontier_smart_volume_pending = None
                return
            self._frontier_smart_snapshot = state
            pending = self._frontier_smart_volume_pending
            self._frontier_smart_request_pending = False
            self._frontier_smart_volume_pending = None
            if isinstance(pending, int) and pending != target:
                self._apply_frontier_smart_snapshot(state, announce=False)
                self._queue_frontier_smart_volume(pending)
                return
            confirmed = state.get("volume")
            self._frontier_smart_requested_volume = (
                confirmed if isinstance(confirmed, int) else target
            )
            if self.navigator.active is SessionId.FRONTIER_SMART:
                self._apply_frontier_smart_snapshot(state, announce=True)

        def failed(error: Exception) -> None:
            self._frontier_smart_request_pending = False
            self._frontier_smart_volume_pending = None
            confirmed = self._frontier_smart_snapshot.get("volume")
            self._frontier_smart_requested_volume = (
                confirmed if isinstance(confirmed, int) else None
            )
            if isinstance(confirmed, int):
                self.volume_slider.SetValue(confirmed)
            self.announcer.say(
                "Nie udało się zmienić głośności Frontier Smart. "
                "Odczekaj chwilę i spróbuj ponownie"
            )

        self.runner.submit(
            "frontier-smart-volume",
            lambda: client.frontier_smart_transport(
                device_id,
                "setVolume",
                volume=target,
            ),
            done,
            failed,
        )

    # ---------------------------------------------------------------- Sonos

    def _select_sonos_target(self) -> None:
        """Ctrl+F5: wybór grupy po zalogowaniu, konfiguracja przy braku konta."""
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        preferred_id = self.navigator.sessions[SessionId.SONOS].list_anchor_id

        def done(payload: object) -> None:
            if isinstance(payload, dict) and bool(payload.get("connected")):
                self.announcer.say(
                    f"{LiteFrame._sonos_account_message(payload)} "
                    "Wczytuję głośniki i grupy."
                )
                self._load_sonos_targets(preferred_id=preferred_id)
                return
            self._show_sonos_account(payload)

        def failed(error: Exception) -> None:
            self.announcer.say(
                str(error)
                if isinstance(error, (HostError, HostUnavailable))
                else "Nie można teraz sprawdzić konta Sonos"
            )

        self.runner.submit(
            "sonos-account-status",
            client.sonos_account_status,
            done,
            failed,
        )

    def _load_sonos_targets(self, preferred_id: str | None = None) -> None:
        """Wczytaj grupy przez wspólny Core; token konta zostaje w C#."""
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return

        def done(payload: object) -> None:
            try:
                rows = list(sonos_target_rows(payload))
            except SonosPayloadError as error:
                self.announcer.say(str(error))
                return
            selected_id = preferred_id
            if self._sonos_active_group_id:
                active = next((
                    row.item_id for row in rows
                    if row.service_id == self._sonos_active_group_id
                    and row.parent_id == self._sonos_active_household_id
                ), None)
                selected_id = active or selected_id
            events = self.navigator.apply_sonos_targets(rows, selected_id)
            selected = self.navigator.sessions[SessionId.SONOS].model.selected_row
            if selected is not None and selected.parent_id:
                self._sonos_browse_household_id = selected.parent_id
            if self.navigator.active is SessionId.SONOS:
                self._run(events)
            else:
                self._sync_views()

        def failed(error: Exception) -> None:
            self.announcer.say(f"Nie udało się odczytać grup Sonos: {error}")
            if (
                self.navigator.active is SessionId.SONOS
                and LiteFrame._sonos_error_requires_login(error)
            ):
                self._run(self.navigator.apply_sonos_account_prompt())

        self.runner.submit(
            "sonos-targets",
            client.sonos_targets,
            done,
            failed,
        )

    @staticmethod
    def _sonos_error_requires_login(error: Exception) -> bool:
        """Rozpoznaj wyłącznie użytkowy stan braku połączonego konta."""

        message = str(error).casefold()
        return (
            "nie ma połączonego konta sonos" in message
            or "konto sonos nie jest połączone" in message
        )

    def _activate_sonos_group(
        self, intent: ActivateSonosGroup, *, attempt: int = 0
    ) -> None:
        client = self.client
        if client is None:
            self._run(self.navigator.back_to_list())
            self.announcer.say("Silnik nie jest gotowy")
            return
        self._sonos_active_household_id = intent.household_id
        self._sonos_active_group_id = intent.group_id
        self._sonos_browse_household_id = intent.household_id
        self._sonos_snapshot = {}
        self.now_playing.SetLabel(intent.title)
        self._set_transport_label(playing=False, preparing=True)
        if (
            getattr(self, "_sonos_request_pending", False)
            or getattr(self, "_sonos_retry_pending", False)
        ):
            # Użytkownik może wrócić na listę i wybrać inną grupę, gdy stary
            # odczyt jeszcze kończy się w chmurze. Nie uruchamiamy drugiego
            # równolegle; ostatni świadomy wybór wykona się zaraz po pierwszym.
            self._sonos_pending_activation = intent
            self._sonos_pending_material = None
            return
        self._sonos_request_pending = True

        def done(payload: object) -> None:
            try:
                state = sonos_snapshot(payload)
            except SonosPayloadError as error:
                failed(error)
                return
            if (
                state.get("householdId") != self._sonos_active_household_id
                or state.get("groupId") != self._sonos_active_group_id
            ):
                self._finish_sonos_request()
                return
            self._sonos_snapshot = state
            if (
                self.navigator.active is SessionId.SONOS
                and self.navigator.view is View.PLAYER
            ):
                self._apply_sonos_snapshot(state, announce=True)
            self._finish_sonos_request()
            if (
                self.navigator.active is SessionId.SONOS
                and intent.household_id == self._sonos_active_household_id
                and intent.group_id == self._sonos_active_group_id
            ):
                self._open_sonos_view(OpenSonosView(
                    LibraryView.SONOS_LIBRARY,
                    household_id=intent.household_id,
                    preferred_id=None,
                ))

        def failed(error: Exception) -> None:
            if (
                isinstance(error, HostError)
                and error.code == "operation_busy"
                and attempt < 20
                and intent.household_id == self._sonos_active_household_id
                and intent.group_id == self._sonos_active_group_id
                and self.navigator.active is SessionId.SONOS
            ):
                self._sonos_request_pending = False
                self._sonos_retry_pending = True

                def retry() -> None:
                    self._sonos_retry_pending = False
                    pending_activation = self._sonos_pending_activation
                    self._sonos_pending_activation = None
                    if pending_activation is not None:
                        self._activate_sonos_group(pending_activation)
                    elif (
                        intent.household_id == self._sonos_active_household_id
                        and intent.group_id == self._sonos_active_group_id
                        and self.navigator.active is SessionId.SONOS
                    ):
                        self._activate_sonos_group(intent, attempt=attempt + 1)
                    else:
                        self._start_next_sonos_command()

                call_later = getattr(wx, "CallLater", None)
                if callable(call_later):
                    call_later(250, retry)
                else:
                    retry()
                return
            if (
                intent.household_id == self._sonos_active_household_id
                and intent.group_id == self._sonos_active_group_id
            ):
                state = self.navigator.sessions[SessionId.SONOS]
                state.view = View.LIST
                if self.navigator.active is SessionId.SONOS:
                    self._sync_views()
                    self.announcer.say(str(error))
            self._finish_sonos_request()

        self.runner.submit(
            "sonos-snapshot",
            lambda: client.sonos_snapshot(intent.household_id, intent.group_id),
            done,
            failed,
        )

    def _apply_sonos_snapshot(
        self, state: dict, *, announce: bool = False
    ) -> None:
        """Pokaż tylko jawne etykiety stanu, bez identyfikatorów Sonosa."""
        record_history = getattr(
            self, "_record_streamer_history_snapshot", None
        )
        if callable(record_history):
            record_history(SessionId.SONOS, state)
        label = sonos_now_playing_label(state)
        if self.now_playing.GetLabel() != label:
            self.now_playing.SetLabel(label)
        self.now_playing.SetName("Teraz odtwarzane")
        time_label = player_time_label(
            state.get("positionSeconds"), state.get("durationSeconds")
        )
        if self.time_label.GetLabel() != time_label:
            self.time_label.SetLabel(time_label)
        volume = state.get("volume")
        if isinstance(volume, int) and self.volume_slider.GetValue() != volume:
            self.volume_slider.SetValue(volume)
        self.volume_slider.Enable(
            isinstance(volume, int) and state.get("fixedVolume") is not True
        )
        playback = str(state.get("playbackState") or "").casefold()
        self._set_transport_label(
            playing=playback in {"odtwarzanie", "playing", "play"}
        )
        apply_activity = getattr(self, "_apply_streamer_activity_status", None)
        if callable(apply_activity):
            apply_activity(SessionId.SONOS)
        if announce:
            message = str(state.get("message") or "").strip()
            self.announcer.say(message or label)

    def _sonos_transport(
        self,
        command: str,
        *,
        volume: int | None = None,
        seconds: float | None = None,
    ) -> None:
        client = self.client
        household_id = self._sonos_active_household_id
        group_id = self._sonos_active_group_id
        if client is None or not household_id or not group_id:
            self.announcer.say(
                "Brak aktywnej grupy Sonos. Naciśnij Enter na grupie"
            )
            return

        self._sonos_command_queue.append((
            household_id,
            group_id,
            command,
            volume,
            seconds,
            0,
        ))
        self._start_next_sonos_command()

    def _start_next_sonos_command(self) -> None:
        """Uruchom pierwsze aktualne polecenie, nigdy równolegle z odczytem."""
        if (
            getattr(self, "_sonos_request_pending", False)
            or getattr(self, "_sonos_retry_pending", False)
        ):
            return
        client = self.client
        if client is None:
            self._sonos_command_queue.clear()
            return
        request = None
        while self._sonos_command_queue:
            candidate = self._sonos_command_queue.pop(0)
            household_id, group_id, _command, _volume, _seconds, _attempt = candidate
            if (
                self.navigator.active is SessionId.SONOS
                and household_id == self._sonos_active_household_id
                and group_id == self._sonos_active_group_id
            ):
                request = candidate
                break
        if request is None:
            return
        household_id, group_id, command, volume, seconds, attempt = request
        self._sonos_request_pending = True

        def done(payload: object) -> None:
            try:
                state = sonos_snapshot(payload)
            except SonosPayloadError as error:
                self.announcer.say(str(error))
                self._finish_sonos_request()
                return
            if (
                state.get("householdId") != self._sonos_active_household_id
                or state.get("groupId") != self._sonos_active_group_id
            ):
                self._finish_sonos_request()
                return
            self._sonos_snapshot = state
            if self.navigator.active is SessionId.SONOS:
                self._apply_sonos_snapshot(state, announce=True)
            self._finish_sonos_request()

        def failed(error: Exception) -> None:
            if (
                isinstance(error, HostError)
                and error.code == "operation_busy"
                and attempt < 20
                and household_id == self._sonos_active_household_id
                and group_id == self._sonos_active_group_id
                and self.navigator.active is SessionId.SONOS
            ):
                self._sonos_request_pending = False
                self._sonos_retry_pending = True
                self._sonos_command_queue.insert(0, (
                    household_id,
                    group_id,
                    command,
                    volume,
                    seconds,
                    attempt + 1,
                ))

                def retry() -> None:
                    self._sonos_retry_pending = False
                    # W czasie oczekiwania użytkownik mógł świadomie wybrać
                    # inną grupę. Ostatni wybór ma pierwszeństwo przed
                    # ponowieniem starego polecenia.
                    self._finish_sonos_request()

                call_later = getattr(wx, "CallLater", None)
                if callable(call_later):
                    call_later(250, retry)
                else:
                    retry()
                return
            self.announcer.say(
                f"Nie udało się sterować grupą Sonos: {error}"
            )
            self._finish_sonos_request()

        self.runner.submit(
            "sonos-transport",
            lambda: client.sonos_transport(
                household_id,
                group_id,
                command,
                volume=volume,
                seconds=seconds,
            ),
            done,
            failed,
        )

    def _finish_sonos_request(self) -> None:
        """Zwolnij tor Sonosa i wykonaj ostatni wybór albo czekające polecenie."""
        self._sonos_request_pending = False
        pending_activation = self._sonos_pending_activation
        self._sonos_pending_activation = None
        if pending_activation is not None:
            self._activate_sonos_group(pending_activation)
            return
        pending_material = getattr(self, "_sonos_pending_material", None)
        self._sonos_pending_material = None
        if pending_material is not None:
            self._play_sonos_material(pending_material)
            return
        self._start_next_sonos_command()

    def _sonos_content_household_id(self) -> str:
        """Dom do odczytu treści, nigdy tekst pokazywany użytkownikowi."""
        if self._sonos_active_household_id:
            return self._sonos_active_household_id
        state = self.navigator.sessions[SessionId.SONOS]
        row = state.model.selected_row
        if row is not None and row.parent_id:
            return row.parent_id
        if state.library_item_id:
            return state.library_item_id
        return self._sonos_browse_household_id

    def _open_sonos_view(
        self,
        intent: OpenSonosView,
        *,
        announcement: str | None = None,
    ) -> None:
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        household_id = intent.household_id or self._sonos_content_household_id()
        if not household_id:
            self.announcer.say(
                "Najpierw wybierz grupę Sonos skrótem Control F5"
            )
            self._load_sonos_targets()
            return
        self._sonos_browse_household_id = household_id
        if intent.view is not LibraryView.SONOS_OWN_STREAMS:
            self._sonos_pending_move_ids = []
        self._sonos_content_version += 1
        version = self._sonos_content_version
        state = self.navigator.sessions[SessionId.SONOS]
        return_id = (
            state.model.selected_id
            if state.library_view is LibraryView.SONOS_LIBRARY
            else state.library_return_id
        )

        if intent.view is LibraryView.SONOS_LIBRARY:
            work = client.sonos_library
        elif intent.view is LibraryView.SONOS_FAVORITES:
            work = lambda: client.sonos_materials(household_id, "favorite")
        elif intent.view is LibraryView.SONOS_PLAYLISTS:
            work = lambda: client.sonos_materials(household_id, "playlist")
        elif intent.view is LibraryView.SONOS_OWN_STREAMS:
            work = lambda: client.sonos_materials(household_id, "ownStream")
        else:
            self.announcer.say("Ten widok Sonosa nie jest jeszcze dostępny")
            return

        def done(payload: object) -> None:
            if version != self._sonos_content_version:
                return
            if (
                intent.view is LibraryView.SONOS_OWN_STREAMS
                and isinstance(payload, dict)
            ):
                sort_mode = str(payload.get("sortMode") or "")
                if sort_mode in {
                    SORT_ADDED_NEWEST,
                    SORT_ALPHABETICAL,
                    SORT_CUSTOM,
                }:
                    self._sonos_own_stream_sort_mode = sort_mode
            try:
                if intent.view is LibraryView.SONOS_LIBRARY:
                    rows = list(sonos_library_rows(payload, household_id))
                    events = self.navigator.apply_sonos_library(
                        rows,
                        household_id=household_id,
                        preferred_id=intent.preferred_id or return_id,
                    )
                else:
                    rows = list(sonos_material_rows(payload, household_id))
                    events = self.navigator.apply_sonos_materials(
                        intent.view,
                        rows,
                        household_id=household_id,
                        preferred_id=intent.preferred_id,
                        return_id=return_id,
                    )
            except SonosPayloadError as error:
                self.announcer.say(str(error))
                return
            if self.navigator.active is SessionId.SONOS:
                self._run(events)
                if intent.view is not LibraryView.SONOS_LIBRARY:
                    message = announcement or sonos_response_message(payload)
                    self.announcer.say(message or (
                        "Zero elementów" if not rows else "Lista Sonos"
                    ))
            else:
                self._sync_views()

        def failed(error: Exception) -> None:
            if version == self._sonos_content_version:
                self.announcer.say(
                    f"Nie udało się odczytać Biblioteki Sonos: {error}"
                )

        self.runner.submit(
            "sonos-library",
            work,
            done,
            failed,
        )

    def _selected_sonos_own_stream_rows(self) -> list[Row]:
        """Zwróć lokalne stacje AMC, nigdy ulubione ani playlisty Sonosa."""
        if (
            self.navigator.active is not SessionId.SONOS
            or self.navigator.session.library_view
            is not LibraryView.SONOS_OWN_STREAMS
        ):
            return []
        return [
            row for row in self._selected_action_rows()
            if row.kind == "sonosOwnStream"
            and row.service_kind == "ownStream"
            and bool(row.service_id)
        ]

    def _reload_sonos_own_streams(
        self,
        *,
        preferred_stream_id: str | None = None,
        announcement: str | None = None,
    ) -> None:
        household_id = self._sonos_content_household_id()
        if not household_id:
            self.announcer.say(
                "Najpierw wybierz grupę Sonos skrótem Control F5"
            )
            return
        self._open_sonos_view(
            OpenSonosView(
                LibraryView.SONOS_OWN_STREAMS,
                household_id=household_id,
                preferred_id=(
                    f"sonos-stream:{preferred_stream_id}"
                    if preferred_stream_id else None
                ),
            ),
            announcement=announcement,
        )

    def _add_sonos_own_stream(self) -> None:
        client = self._profile_edit_client()
        if client is None:
            return
        if self.navigator.session.library_view is not LibraryView.SONOS_OWN_STREAMS:
            self.announcer.say("Otwórz kategorię Moje stacje Sonosa")
            return
        with StationDialog(
            self,
            "Dodaj stację Sonos",
            network_stream=True,
        ) as dialog:
            if dialog.ShowModal() != wx.ID_OK:
                self._restore_focus_after_dialog()
                return
            name, url = dialog.values

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            preferred = str(result.get("preferredStreamId") or "") or None
            message = str(result.get("message") or f"Dodano stację Sonos: {name}")
            self._reload_sonos_own_streams(
                preferred_stream_id=preferred,
                announcement=message,
            )

        self.runner.submit(
            "sonos-own-stream-edit",
            lambda: client.sonos_add_own_stream(name, url),
            done,
            lambda error: self.announcer.say(
                f"Nie dodano stacji Sonos: {error}"
            ),
        )

    def _edit_sonos_own_stream(self) -> None:
        rows = self._selected_sonos_own_stream_rows()
        if len(rows) != 1:
            self.announcer.say("Do edycji wybierz jedną stację Sonos")
            return
        client = self._profile_edit_client()
        if client is None:
            return
        stream_id = rows[0].service_id or ""

        def loaded(payload: object) -> None:
            try:
                loaded_id, current_name, current_url = (
                    sonos_own_stream_edit_info(payload)
                )
            except SonosPayloadError as error:
                self.announcer.say(str(error))
                return
            with StationDialog(
                self,
                "Edytuj stację Sonos",
                current_name,
                current_url,
                network_stream=True,
            ) as dialog:
                if dialog.ShowModal() != wx.ID_OK:
                    self._restore_focus_after_dialog()
                    return
                name, url = dialog.values

            def saved(result_payload: object) -> None:
                result = result_payload if isinstance(result_payload, dict) else {}
                preferred = str(result.get("preferredStreamId") or loaded_id)
                message = str(
                    result.get("message") or f"Zapisano stację Sonos: {name}"
                )
                self._reload_sonos_own_streams(
                    preferred_stream_id=preferred,
                    announcement=message,
                )

            self.runner.submit(
                "sonos-own-stream-edit",
                lambda: client.sonos_edit_own_stream(
                    loaded_id, name, url
                ),
                saved,
                lambda error: self.announcer.say(
                    f"Nie zapisano stacji Sonos: {error}"
                ),
            )

        self.runner.submit(
            "sonos-own-stream-edit-info",
            lambda: client.sonos_own_stream_edit_info(stream_id),
            loaded,
            lambda error: self.announcer.say(
                f"Nie odczytano stacji Sonos: {error}"
            ),
        )

    def _remove_sonos_own_streams(self) -> None:
        rows = self._selected_sonos_own_stream_rows()
        if not rows:
            self.announcer.say("Wybierz stację Sonos do usunięcia")
            return
        client = self._profile_edit_client()
        if client is None:
            return
        prompt = (
            f"Usunąć stację {rows[0].title} z AMC? "
            "Ulubione i playlisty na koncie Sonos pozostaną bez zmian."
            if len(rows) == 1 else
            f"Usunąć wybrane stacje z AMC: {len(rows)}? "
            "Ulubione i playlisty na koncie Sonos pozostaną bez zmian."
        )
        if wx.MessageBox(
            prompt,
            "Potwierdzenie",
            wx.YES_NO | wx.NO_DEFAULT | wx.ICON_QUESTION,
            self,
        ) != wx.YES:
            self._restore_focus_after_dialog()
            return
        stream_ids = [row.service_id for row in rows if row.service_id]

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            removed = set(stream_ids)
            self._sonos_pending_move_ids = [
                stream_id for stream_id in self._sonos_pending_move_ids
                if stream_id not in removed
            ]
            message = str(
                result.get("message")
                or f"Usunięto stacje Sonos: {len(stream_ids)}"
            )
            self._reload_sonos_own_streams(announcement=message)

        self.runner.submit(
            "sonos-own-stream-edit",
            lambda: client.sonos_remove_own_streams(stream_ids),
            done,
            lambda error: self.announcer.say(
                f"Nie usunięto stacji Sonos: {error}"
            ),
        )

    def _import_sonos_own_streams(self) -> None:
        client = self._profile_edit_client()
        if client is None:
            return
        if self.navigator.session.library_view is not LibraryView.SONOS_OWN_STREAMS:
            self.announcer.say("Otwórz kategorię Moje stacje Sonosa")
            return
        with wx.FileDialog(
            self,
            "Importuj playlistę do Moich stacji Sonosa",
            wildcard=(
                "Playlisty (*.m3u;*.m3u8;*.pls)|*.m3u;*.m3u8;*.pls|"
                "Wszystkie pliki (*.*)|*.*"
            ),
            style=wx.FD_OPEN | wx.FD_FILE_MUST_EXIST,
        ) as dialog:
            if dialog.ShowModal() != wx.ID_OK:
                self._restore_focus_after_dialog()
                return
            path = dialog.GetPath()

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            preferred = str(result.get("preferredStreamId") or "") or None
            message = str(
                result.get("message") or "Zakończono import stacji Sonos"
            )
            self._reload_sonos_own_streams(
                preferred_stream_id=preferred,
                announcement=message,
            )

        self.runner.submit(
            "sonos-own-stream-import",
            lambda: client.sonos_import_own_streams(path),
            done,
            lambda error: self.announcer.say(
                f"Nie można zaimportować playlisty: {error}"
            ),
        )

    def _set_sonos_own_stream_sort(self, action: Action) -> None:
        modes = {
            Action.SORT_SONOS_OWN_STREAMS_ADDED: SORT_ADDED_NEWEST,
            Action.SORT_SONOS_OWN_STREAMS_ALPHABETICAL: SORT_ALPHABETICAL,
            Action.SORT_SONOS_OWN_STREAMS_CUSTOM: SORT_CUSTOM,
        }
        mode = modes[action]
        client = self._profile_edit_client()
        if client is None:
            return
        selected = next(iter(self._selected_sonos_own_stream_rows()), None)
        preferred = selected.service_id if selected is not None else None

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            self._sonos_own_stream_sort_mode = mode
            if mode != SORT_CUSTOM:
                self._sonos_pending_move_ids = []
            message = str(
                result.get("message") or "Zmieniono kolejność stacji Sonos"
            )
            self._reload_sonos_own_streams(
                preferred_stream_id=preferred,
                announcement=message,
            )

        self.runner.submit(
            "sonos-own-stream-sort",
            lambda: client.sonos_sort_own_streams(mode),
            done,
            lambda error: self.announcer.say(
                f"Nie zapisano kolejności stacji Sonos: {error}"
            ),
        )

    def _move_sonos_own_streams(self, direction: int) -> None:
        if self._sonos_own_stream_sort_mode != SORT_CUSTOM:
            self.announcer.say(
                "Przenoszenie działa w kolejności własnej. Naciśnij Alt 3"
            )
            return
        filter_box = getattr(self, "filter_box", None)
        if filter_box is not None and filter_box.GetValue().strip():
            self.announcer.say(
                "Wyczyść filtr klawiszem Escape przed zmianą kolejności"
            )
            return
        rows = self._selected_sonos_own_stream_rows()
        if not rows:
            self.announcer.say("Najpierw wybierz stację")
            return
        client = self._profile_edit_client()
        if client is None:
            return
        stream_ids = [row.service_id for row in rows if row.service_id]
        selected = set(stream_ids)
        visible = [
            row for row in self.navigator.session.model.rows
            if row.kind == "sonosOwnStream" and row.service_id
        ]
        positions = [
            index for index, row in enumerate(visible)
            if row.service_id in selected
        ]
        adjacent_title = "sąsiedni element"
        if positions and positions[-1] - positions[0] + 1 == len(positions):
            adjacent_index = positions[0] - 1 if direction < 0 else positions[-1] + 1
            if 0 <= adjacent_index < len(visible):
                adjacent_title = visible[adjacent_index].title

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            preferred = str(result.get("preferredStreamId") or "") or None
            moved = (
                "Przeniesiono stację"
                if len(stream_ids) == 1
                else f"Przeniesiono stacje: {len(stream_ids)}"
            )
            message = (
                f"{moved} w górę, nad {adjacent_title}"
                if direction < 0
                else f"{moved} w dół, pod {adjacent_title}"
            )
            self._reload_sonos_own_streams(
                preferred_stream_id=preferred,
                announcement=message,
            )

        self.runner.submit(
            "sonos-own-stream-order",
            lambda: client.sonos_move_own_streams(stream_ids, direction),
            done,
            lambda error: self.announcer.say(str(error)),
        )

    def _cut_sonos_own_streams(self) -> None:
        if self._sonos_own_stream_sort_mode != SORT_CUSTOM:
            self.announcer.say(
                "Przenoszenie działa w kolejności własnej. Naciśnij Alt 3"
            )
            return
        filter_box = getattr(self, "filter_box", None)
        if filter_box is not None and filter_box.GetValue().strip():
            self.announcer.say(
                "Wyczyść filtr klawiszem Escape przed przenoszeniem elementów"
            )
            return
        rows = self._selected_sonos_own_stream_rows()
        if not rows:
            self.announcer.say("Najpierw wybierz stację")
            return
        self._sonos_pending_move_ids = [
            row.service_id for row in rows if row.service_id
        ]
        self.announcer.say(
            "Zaznaczono stację do przeniesienia. "
            "Wybierz miejsce i naciśnij Control V"
            if len(self._sonos_pending_move_ids) == 1 else
            f"Zaznaczono {len(self._sonos_pending_move_ids)} stacji do "
            "przeniesienia. Wybierz miejsce i naciśnij Control V"
        )

    def _paste_sonos_own_streams(self) -> None:
        if self._sonos_own_stream_sort_mode != SORT_CUSTOM:
            self.announcer.say(
                "Przenoszenie działa w kolejności własnej. Naciśnij Alt 3"
            )
            return
        filter_box = getattr(self, "filter_box", None)
        if filter_box is not None and filter_box.GetValue().strip():
            self.announcer.say(
                "Wyczyść filtr klawiszem Escape przed przenoszeniem elementów"
            )
            return
        if not self._sonos_pending_move_ids:
            self.announcer.say(
                "Najpierw naciśnij Control X na stacji do przeniesienia"
            )
            return
        target = next(iter(self._selected_sonos_own_stream_rows()), None)
        if target is None or not target.service_id:
            self.announcer.say("Nie wybrano miejsca docelowego")
            return
        client = self._profile_edit_client()
        if client is None:
            return
        pending = list(self._sonos_pending_move_ids)
        target_title = target.title

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            preferred = str(result.get("preferredStreamId") or "") or None
            message = (
                f"Przeniesiono stację przed {target_title}"
                if len(pending) == 1 else
                f"Przeniesiono stacje: {len(pending)}, przed {target_title}"
            )
            self._sonos_pending_move_ids = []
            self._reload_sonos_own_streams(
                preferred_stream_id=preferred,
                announcement=message,
            )

        self.runner.submit(
            "sonos-own-stream-order",
            lambda: client.sonos_place_own_streams(
                pending, target.service_id or ""
            ),
            done,
            lambda error: self.announcer.say(str(error)),
        )

    def _export_sonos_own_streams(self) -> None:
        client = self._profile_edit_client()
        if client is None:
            return
        if self.navigator.session.library_view is not LibraryView.SONOS_OWN_STREAMS:
            self.announcer.say("Otwórz kategorię Moje stacje Sonosa")
            return
        with wx.FileDialog(
            self,
            "Eksportuj Moje stacje Sonosa",
            defaultFile="Moje stacje Sonosa AMC.m3u",
            wildcard="Playlisty M3U (*.m3u)|*.m3u|Wszystkie pliki (*.*)|*.*",
            style=wx.FD_SAVE | wx.FD_OVERWRITE_PROMPT,
        ) as dialog:
            if dialog.ShowModal() != wx.ID_OK:
                self._restore_focus_after_dialog()
                return
            path = str(Path(dialog.GetPath()).with_suffix(".m3u"))

        def done(payload: object) -> None:
            result = payload if isinstance(payload, dict) else {}
            count = int(result.get("exportedCount") or 0)
            self.announcer.say(f"Wyeksportowano stacje Sonos: {count}")
            self._restore_focus_after_dialog()

        self.runner.submit(
            "sonos-own-stream-export",
            lambda: client.sonos_export_own_streams(path),
            done,
            lambda error: self.announcer.say(
                f"Nie można zapisać playlisty: {error}"
            ),
        )

    def _play_sonos_material(
        self, intent: PlaySonosMaterial, *, attempt: int = 0
    ) -> None:
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie jest gotowy")
            return
        if self.navigator.active is not SessionId.SONOS:
            return
        if (
            not self._sonos_active_group_id
            or self._sonos_active_household_id != intent.household_id
        ):
            self.announcer.say(
                "Wybierz grupę Sonos skrótem Control F5, a potem uruchom materiał ponownie"
            )
            return
        if self._sonos_request_pending or self._sonos_retry_pending:
            self._sonos_pending_material = intent
            return

        household_id = self._sonos_active_household_id
        group_id = self._sonos_active_group_id
        self._sonos_request_pending = True

        def done(payload: object) -> None:
            try:
                state = sonos_snapshot(payload)
            except SonosPayloadError as error:
                failed(error)
                return
            if (
                household_id != self._sonos_active_household_id
                or group_id != self._sonos_active_group_id
            ):
                self._finish_sonos_request()
                return
            session = self.navigator.sessions[SessionId.SONOS]
            session.now_playing_id = intent.item_id
            session.now_playing_title = intent.title
            session.current_material_id = intent.item_id
            self._sonos_snapshot = state
            kind = {
                "favorite": "sonosFavorite",
                "playlist": "sonosPlaylist",
                "ownStream": "sonosOwnStream",
            }.get(intent.kind, "station")
            record_history = getattr(self, "_record_streamer_history_row", None)
            if callable(record_history):
                record_history(SessionId.SONOS, Row(
                    item_id=intent.item_id,
                    title=intent.title,
                    kind=kind,
                    parent_id=intent.household_id,
                    service_id=intent.material_id,
                    service_kind=intent.kind,
                ), replay_supported=kind != "station")
            if self.navigator.active is SessionId.SONOS:
                state["message"] = intent.title
                self._apply_sonos_snapshot(state, announce=True)
            self._finish_sonos_request()

        def failed(error: Exception) -> None:
            if (
                isinstance(error, HostError)
                and error.code == "operation_busy"
                and attempt < 20
                and household_id == self._sonos_active_household_id
                and group_id == self._sonos_active_group_id
            ):
                self._sonos_request_pending = False
                self._sonos_retry_pending = True

                def retry() -> None:
                    self._sonos_retry_pending = False
                    self._play_sonos_material(intent, attempt=attempt + 1)

                call_later = getattr(wx, "CallLater", None)
                if callable(call_later):
                    call_later(250, retry)
                else:
                    retry()
                return
            self.announcer.say(f"Nie udało się uruchomić materiału Sonos: {error}")
            session = self.navigator.sessions[SessionId.SONOS]
            if (
                self.navigator.active is SessionId.SONOS
                and session.view is View.PLAYER
                and session.now_playing_id == intent.item_id
            ):
                session.view = View.LIST
                self._sync_views()
            self._finish_sonos_request()

        self.runner.submit(
            "sonos-material",
            lambda: client.sonos_load_material(
                household_id,
                group_id,
                intent.kind,
                intent.material_id,
            ),
            done,
            failed,
        )

    # ------------------------------------------------ Podcasty i YouTube

    def _apply_podcast_result(self, events: list[object]) -> None:
        """Apply data silently when its session is no longer on screen."""
        if self.navigator.active is SessionId.PODCASTS:
            self._run(events)
        else:
            self._sync_views()

    def _open_podcast_library(
        self,
        preferred_id: str | None = None,
        *,
        completion_message: str = "",
        sort_label: str = "",
        after_refresh: Callable[[], None] | None = None,
        announce_result: bool = True,
    ) -> None:
        """Load the shared AMC podcast/channel library outside the GUI thread."""
        if not self.podcasts.is_available:
            if self.navigator.active is SessionId.PODCASTS:
                self.announcer.say("Nie znaleziono biblioteki podcastów AMC")
            return

        def work():
            ordered = getattr(self.podcasts, "ordered_subscriptions", None)
            if callable(ordered):
                return ordered(
                    getattr(self, "_podcast_library_sort_mode", SORT_CUSTOM),
                    collation=getattr(self, "_collation", None),
                )
            # Minimalne atrapy starszych testów udostępniają tylko odczyt
            # źródeł. Produkcja zawsze przechodzi przez metodę powyżej.
            return self.podcasts.subscriptions(), True

        def done(result) -> None:
            subscriptions, order_matches_amc = result
            if completion_message:
                state = self.navigator.sessions[SessionId.PODCASTS]
                if (
                    self.navigator.active is not SessionId.PODCASTS
                    or state.view is not View.LIST
                    or state.library_view is not LibraryView.PODCAST_LIBRARY
                ):
                    return
            events = self.navigator.apply_podcast_library(
                subscription_rows(subscriptions),
                preferred_id=preferred_id,
                sort_label=sort_label,
                order_matches_amc=order_matches_amc,
            )
            if completion_message:
                self._sync_views()
                self.announcer.say(completion_message)
            elif announce_result:
                self._apply_podcast_result(events)
            else:
                # Odświeżenie listy pod modalnym oknem wyszukiwania nie może
                # odebrać mu fokusu ani zagłuszyć potwierdzenia dodania.
                self._sync_views()
            if after_refresh is not None:
                after_refresh()

        def failed(error: Exception) -> None:
            if self.navigator.active is SessionId.PODCASTS:
                self.announcer.say(str(error) if isinstance(error, PodcastProfileError)
                                   else "Nie udało się odczytać biblioteki podcastów")

        self.runner.submit("podcast-view", work, done, failed)

    def _refresh_visible_podcast_library_after_search_add(
        self,
        preferred_id: str,
    ) -> None:
        """Pokaż nowy wpis po zamknięciu wyszukiwarki, bez dodatkowej mowy."""

        state = self.navigator.sessions[SessionId.PODCASTS]
        if (
            self.navigator.active is SessionId.PODCASTS
            and state.view is View.LIST
            and state.library_view is LibraryView.PODCAST_LIBRARY
        ):
            self._open_podcast_library(
                preferred_id=preferred_id,
                announce_result=False,
            )

    def _open_podcast_view(
        self,
        intent: OpenPodcastView,
        *,
        completion_message: str = "",
        after_refresh: Callable[[], None] | None = None,
    ) -> None:
        if not intent.subscription_id:
            self._open_podcast_library(
                preferred_id=intent.preferred_id,
                completion_message=completion_message,
                after_refresh=after_refresh,
            )
            return

        subscription_id = intent.subscription_id
        previous_count = self._podcast_loaded_counts.get(subscription_id, 0)
        requested = requested_count(
            previous_count,
            load_more=intent.load_more,
            page_size=PODCAST_PAGE_SIZE,
        )

        def work():
            subscription = self.podcasts.subscription(subscription_id)
            if subscription is None:
                raise PodcastProfileError("Tego podcastu nie ma już w Bibliotece.")
            page = self.podcasts.episodes(subscription_id, loaded_count=requested)
            return subscription, page

        def done(result) -> None:
            if completion_message:
                state = self.navigator.sessions[SessionId.PODCASTS]
                if (
                    self.navigator.active is not SessionId.PODCASTS
                    or state.view is not View.LIST
                    or state.library_view is not LibraryView.PODCAST_EPISODES
                    or state.library_playlist_id != subscription_id
                ):
                    return
            subscription, page = result
            self._podcast_loaded_counts[subscription_id] = page.loaded_count
            preferred = intent.preferred_id
            if intent.load_more and previous_count < len(page.rows):
                candidate = page.rows[previous_count]
                if candidate.kind == "episode":
                    preferred = candidate.item_id
            events = self.navigator.apply_podcast_episodes(
                subscription_id,
                subscription.title,
                page.rows,
                preferred_id=preferred,
                total_count=page.total_count,
            )
            if completion_message:
                self._sync_views()
                self.announcer.say(completion_message)
            else:
                self._apply_podcast_result(events)
            if after_refresh is not None:
                after_refresh()

        def failed(error: Exception) -> None:
            if self.navigator.active is SessionId.PODCASTS:
                self.announcer.say(str(error) if isinstance(error, PodcastProfileError)
                                   else "Nie udało się odczytać odcinków")

        self.runner.submit("podcast-view", work, done, failed)

    def _open_youtube_broadcasts(self, intent: OpenYouTubeBroadcasts) -> None:
        """Load live/upcoming items through the token-owning C# host."""

        client = self.client
        if client is None:
            self.announcer.say("Silnik nie działa. Nie można pobrać transmisji YouTube")
            return
        subscription_id = intent.subscription_id

        def work() -> object:
            return client.youtube_channel_broadcasts(
                subscription_id,
                refresh=intent.force_refresh,
            )

        def done(payload: object) -> None:
            state = self.navigator.sessions[SessionId.PODCASTS]
            if self.navigator.active is not SessionId.PODCASTS:
                return
            if state.library_view not in (
                LibraryView.PODCAST_LIBRARY,
                LibraryView.YOUTUBE_BROADCASTS,
            ):
                return
            if (
                state.library_view is LibraryView.YOUTUBE_BROADCASTS
                and state.library_playlist_id != subscription_id
            ):
                return
            try:
                rows = youtube_broadcast_rows(
                    payload,
                    subscription_id=subscription_id,
                )
            except YouTubeLivePayloadError as error:
                self.announcer.say(str(error))
                return
            events = self.navigator.apply_youtube_broadcasts(
                subscription_id,
                intent.subscription_title,
                rows,
                preferred_id=intent.preferred_id,
            )
            self._apply_podcast_result(events)

        def failed(error: Exception) -> None:
            if self.navigator.active is SessionId.PODCASTS:
                message = str(error).strip() if isinstance(error, HostError) else ""
                self.announcer.say(
                    message or "Nie udało się pobrać transmisji YouTube"
                )

        self.runner.submit("youtube-broadcasts", work, done, failed)

    def _add_selected_youtube_live_station(self) -> None:
        row = self.navigator.session.model.selected_row
        if (
            self.navigator.active is not SessionId.PODCASTS
            or row is None
            or row.kind != "podcast"
            or row.service_kind != "youtubeChannel"
        ):
            self.announcer.say("Wybierz kanał YouTube z Biblioteki")
            return
        try:
            address = youtube_dynamic_live_url(row.url or "")
        except YouTubeLivePayloadError as error:
            self.announcer.say(str(error))
            return
        self._station_add(
            default_name=f"{row.title} — YouTube na żywo",
            default_url=address,
            dialog_title="Dodaj dynamiczną stację YouTube",
        )

    def _youtube_channel_subscriptions(self):
        return [
            subscription
            for subscription in self.podcasts.subscriptions()
            if subscription.source_kind == 2
        ]

    def _save_youtube_live_channel_ids(self, channel_ids: object) -> bool:
        normalized = normalize_youtube_live_channel_ids(channel_ids)
        previous = list(self.state.youtube_live_channel_ids)
        self.state.youtube_live_channel_ids = normalized
        if self._save_state():
            return True
        self.state.youtube_live_channel_ids = previous
        return False

    def _configure_youtube_live_channels(
        self,
        *,
        open_after_save: bool = False,
    ) -> None:
        """Natywny selektor: tytuły kanałów, jawny zapis i powrót fokusu."""

        def done(channels) -> None:
            self._youtube_live_channels_by_id = {
                channel.subscription_id: channel for channel in channels
            }
            with YouTubeLiveChannelPickerDialog(
                self,
                channels,
                list(self.state.youtube_live_channel_ids),
            ) as dialog:
                accepted = dialog.ShowModal() == wx.ID_OK
                result_ids = dialog.result_ids
            if not accepted or result_ids is None:
                self._restore_focus_after_dialog()
                return
            if not self._save_youtube_live_channel_ids(result_ids):
                self._restore_focus_after_dialog()
                return
            count = len(self.state.youtube_live_channel_ids)
            self._refresh_menu_state()
            if count:
                self.announcer.say(f"Zapisano kanały transmisji: {count}")
            else:
                self.announcer.say("Wyczyszczono wybór kanałów transmisji")
            if open_after_save and count:
                self._show_youtube_live_aggregate()
            else:
                self._restore_focus_after_dialog()

        self.runner.submit(
            "youtube-live-channel-picker",
            self._youtube_channel_subscriptions,
            done,
            lambda error: self.announcer.say(
                str(error)
                if isinstance(error, PodcastProfileError)
                else "Nie udało się odczytać kanałów YouTube"
            ),
        )

    def _toggle_youtube_live_aggregate_channel(self) -> None:
        row = self.navigator.session.model.selected_row
        if (
            self.navigator.active is not SessionId.PODCASTS
            or self.navigator.session.library_view is not LibraryView.PODCAST_LIBRARY
            or row is None
            or row.kind != "podcast"
            or row.service_kind != "youtubeChannel"
        ):
            self.announcer.say("Wybierz kanał YouTube z Biblioteki")
            return
        channel_ids = list(self.state.youtube_live_channel_ids)
        if row.item_id in channel_ids:
            channel_ids.remove(row.item_id)
            message = (
                f"Kanał {row.title} nie będzie sprawdzany na zbiorczej liście"
            )
        else:
            if len(channel_ids) >= YOUTUBE_LIVE_CHANNEL_LIMIT:
                self.announcer.say(
                    f"Możesz wybrać najwyżej {YOUTUBE_LIVE_CHANNEL_LIMIT} kanałów"
                )
                return
            channel_ids.append(row.item_id)
            message = f"Kanał {row.title} będzie sprawdzany na zbiorczej liście"
        if self._save_youtube_live_channel_ids(channel_ids):
            self._refresh_menu_state()
            self.announcer.say(message)

    def _show_youtube_live_aggregate(self, *, force_refresh: bool = False) -> None:
        """Ctrl+Shift+I: ręczny skan wybranych kanałów z bezpiecznym powrotem."""

        if self._youtube_live_scan_pending:
            self.announcer.say(
                "Sprawdzanie transmisji wybranych kanałów YouTube już trwa"
            )
            return
        client = self.client
        if not getattr(self, "_youtube_account_available", False):
            self.announcer.say(
                "Najpierw skonfiguruj konto YouTube w menu Plik"
            )
            return
        if client is None:
            self.announcer.say("Silnik nie działa. Nie można pobrać transmisji YouTube")
            return
        selected_ids = normalize_youtube_live_channel_ids(
            self.state.youtube_live_channel_ids
        )
        if not selected_ids:
            self.announcer.say(
                "Najpierw wybierz kanały zbiorczej listy transmisji"
            )
            self._configure_youtube_live_channels(open_after_save=True)
            return

        already_open = (
            self.navigator.active is SessionId.PODCASTS
            and self.navigator.session.library_view
            is LibraryView.YOUTUBE_BROADCASTS_AGGREGATE
        )
        preferred_id = (
            self.navigator.session.model.selected_id if already_open else None
        )
        if not already_open:
            self._begin_transient_preview()
            self.navigator.active = SessionId.PODCASTS
        podcast_state = self.navigator.sessions[SessionId.PODCASTS]
        podcast_state.library_view = LibraryView.YOUTUBE_BROADCASTS_AGGREGATE
        podcast_state.library_playlist_id = None
        podcast_state.library_return_view = (
            "Transmisje wybranych kanałów YouTube"
        )
        podcast_state.view = View.LIST
        self._sync_views()
        self.announcer.say(
            "Odświeżam transmisje wybranych kanałów YouTube"
            if force_refresh
            else "Sprawdzam transmisje wybranych kanałów YouTube"
        )
        self._youtube_live_scan_version += 1
        version = self._youtube_live_scan_version
        self._youtube_live_scan_pending = True

        def finish_current_scan() -> bool:
            if version != self._youtube_live_scan_version:
                return False
            self._youtube_live_scan_pending = False
            return True

        def work():
            channels = self._youtube_channel_subscriptions()
            by_id = {channel.subscription_id: channel for channel in channels}
            chosen = [by_id[channel_id] for channel_id in selected_ids if channel_id in by_id]
            payloads: list[tuple[str, str, object]] = []
            failures = 0
            for channel in chosen:
                try:
                    payload = client.youtube_channel_broadcasts(
                        channel.subscription_id,
                        refresh=force_refresh,
                    )
                except (HostError, HostUnavailable, OSError):
                    failures += 1
                    continue
                payloads.append((channel.subscription_id, channel.title, payload))
            return channels, chosen, payloads, failures

        def done(result) -> None:
            if not finish_current_scan():
                return
            state = self.navigator.sessions[SessionId.PODCASTS]
            if (
                self.navigator.active is not SessionId.PODCASTS
                or state.library_view
                is not LibraryView.YOUTUBE_BROADCASTS_AGGREGATE
            ):
                return
            channels, chosen, payloads, failures = result
            self._youtube_live_channels_by_id = {
                channel.subscription_id: channel for channel in channels
            }
            remaining_ids = [
                channel_id
                for channel_id in selected_ids
                if channel_id in self._youtube_live_channels_by_id
            ]
            if remaining_ids != selected_ids:
                self._save_youtube_live_channel_ids(remaining_ids)
            if not chosen:
                self._restore_transient_preview(announce=False, force=True)
                self.announcer.say(
                    "Wybrane wcześniej kanały nie są już w Bibliotece"
                )
                self._configure_youtube_live_channels(open_after_save=True)
                return
            try:
                rows = youtube_aggregate_broadcast_rows(payloads)
            except YouTubeLivePayloadError as error:
                self.announcer.say(str(error))
                return
            events = self.navigator.apply_youtube_broadcasts_aggregate(
                rows,
                checked_channels=len(payloads),
                failed_channels=failures,
                preferred_id=preferred_id,
            )
            self._apply_podcast_result(events)

        def failed(error: Exception) -> None:
            if not finish_current_scan():
                return
            self.announcer.say(
                str(error)
                if isinstance(error, PodcastProfileError)
                else "Nie udało się sprawdzić transmisji YouTube"
            )

        try:
            self.runner.submit("youtube-live-aggregate", work, done, failed)
        except Exception:
            self._youtube_live_scan_pending = False
            raise

    def _selected_youtube_live_station(self, *, stable: bool) -> Station | None:
        state = self.navigator.sessions[SessionId.PODCASTS]
        row = state.model.selected_row
        if (
            self.navigator.active is not SessionId.PODCASTS
            or state.library_view is not LibraryView.YOUTUBE_BROADCASTS_AGGREGATE
            or row is None
            or row.service_kind not in {"youtubeLive", "youtubeUpcoming"}
            or not row.parent_id
        ):
            self.announcer.say("Wybierz transmisję ze zbiorczej listy")
            return None
        channel = self._youtube_live_channels_by_id.get(row.parent_id)
        if channel is None:
            self.announcer.say("Nie można odnaleźć kanału tej transmisji")
            return None
        try:
            url = (
                youtube_dynamic_live_url(channel.feed_url)
                if stable
                else str(row.url or "").strip()
            )
        except YouTubeLivePayloadError as error:
            self.announcer.say(str(error))
            return None
        if not url:
            self.announcer.say("Ta transmisja nie ma adresu do nagrywania")
            return None
        return Station(
            id=(
                f"youtube-live:{row.parent_id}"
                if stable
                else f"youtube-broadcast:{row.item_id}"
            ),
            name=(
                f"{channel.title} — YouTube na żywo"
                if stable
                else row.title
            ),
            url=url,
        )

    def _toggle_youtube_live_recording(self) -> None:
        row = self.navigator.session.model.selected_row
        if row is None or row.service_kind != "youtubeLive":
            self.announcer.say("Ta transmisja jeszcze nie jest na żywo")
            return
        station = self._selected_youtube_live_station(stable=False)
        if station is not None:
            self._toggle_recording_for_station(station)

    def _schedule_youtube_live_recording(self) -> None:
        row = self.navigator.session.model.selected_row
        station = self._selected_youtube_live_station(stable=True)
        if row is None or station is None:
            return
        initial_start = None
        if row.service_kind == "youtubeUpcoming" and row.service_start_utc:
            try:
                initial_start = datetime.fromisoformat(
                    row.service_start_utc.replace("Z", "+00:00")
                ).astimezone()
            except ValueError:
                initial_start = None
        self._show_radio_schedules(
            create_for_selected=True,
            selected_station_override=station,
            initial_start=initial_start,
        )

    def _show_podcast_inbox(self) -> None:
        """Ctrl+I: otwórz podgląd albo doładuj kolejne 150 pozycji."""
        podcast_state = self.navigator.sessions[SessionId.PODCASTS]
        load_more = (
            self.navigator.active is SessionId.PODCASTS
            and podcast_state.view is View.LIST
            and podcast_state.library_view is LibraryView.PODCAST_INBOX
        )
        self._begin_transient_preview()
        self.navigator.active = SessionId.PODCASTS
        # Oznaczamy widok od razu, zanim watek SQLite odda dane. Escape ma
        # dzialac takze podczas wczytywania, a spozniony wynik po Escape nie
        # moze ponownie otworzyc podgladu.
        podcast_state.library_view = LibraryView.PODCAST_INBOX
        podcast_state.view = View.LIST
        self._open_podcast_aggregate(
            OpenPodcastAggregateView(
                LibraryView.PODCAST_INBOX,
                load_more=load_more,
            ),
            announce_single_item=True,
        )

    def _show_podcast_downloads(self) -> None:
        if self.navigator.active is not SessionId.PODCASTS:
            self.announcer.say(
                "Pobrane odcinki są dostępne w sesji Podcasty i YouTube"
            )
            return
        self._transient_preview_return = None
        self._open_podcast_aggregate(
            OpenPodcastAggregateView(LibraryView.PODCAST_DOWNLOADS)
        )

    def _set_radio_collection_sort(self, action: Action) -> None:
        """Alt+1/2/3 w Bibliotece i Ulubionych Radia."""
        state = self.navigator.sessions[SessionId.RADIO]
        if (
            self.navigator.active is not SessionId.RADIO
            or state.view is not View.LIST
            or state.library_view not in (None, LibraryView.FAVORITES)
        ):
            self.announcer.say(
                "Sortowanie jest dostępne w Bibliotece i Ulubionych Radia"
            )
            return
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie działa, nie mogę zmienić sortowania")
            return
        choice = {
            Action.SORT_RADIO_COLLECTION_ADDED: (
                SORT_ADDED_NEWEST,
                "Radio: według dodania, najnowsze na początku",
            ),
            Action.SORT_RADIO_COLLECTION_ALPHABETICAL: (
                SORT_ALPHABETICAL,
                "Radio: alfabetycznie",
            ),
            Action.SORT_RADIO_COLLECTION_CUSTOM: (
                SORT_CUSTOM,
                "Radio: kolejność własna",
            ),
        }.get(action)
        if choice is None:
            return
        mode, label = choice
        scope = (
            "favorites"
            if state.library_view is LibraryView.FAVORITES
            else "library"
        )
        preferred_id = state.model.selected_id

        def done(payload: dict) -> None:
            result = payload or {}
            effective = str(result.get("sortMode") or mode)
            self._radio_effective_sort_modes[scope] = effective
            if effective != SORT_CUSTOM:
                self._pending_radio_collection_move = None
            self._refresh_menu_state()
            self._open_radio_view(
                OpenLibraryView(
                    view=state.library_view,
                    preferred_id=preferred_id,
                    target_session_id=SessionId.RADIO,
                ),
                after_refresh=lambda: self.announcer.say(label),
            )

        self.runner.submit(
            "radio-sort",
            lambda: client.set_radio_collection_sort(scope, mode),
            done,
            lambda error: self.announcer.say(
                f"Nie mogę zmienić sortowania Radia: {error}"
            ),
        )

    def _radio_manual_order_context(
        self,
    ) -> tuple[str, LibraryView | None] | None:
        """Zakres ręcznej kolejności aktywnej kolekcji Radia."""
        if self.navigator.active is not SessionId.RADIO:
            return None
        state = self.navigator.session
        if state.view is not View.LIST:
            return None
        if state.library_view is None:
            return "library", None
        if state.library_view is LibraryView.FAVORITES:
            return "favorites", LibraryView.FAVORITES
        return None

    def _radio_collection_order_rows(
        self,
    ) -> tuple[list[Row], list[Row]] | None:
        """Zaznaczenie i pełna widoczna kolejność stacji bez filtra."""
        if self.filter_box.GetValue().strip():
            self.announcer.say(
                "Wyczyść filtr klawiszem Escape przed zmianą kolejności"
            )
            return None
        rows = [
            row for row in self._selected_action_rows()
            if row.kind == "station" and row.item_id
        ]
        if not rows:
            self.announcer.say("Wybierz stację do przeniesienia")
            return None
        visible = [
            row for row in self.navigator.session.model.rows
            if row.kind == "station" and row.item_id
        ]
        return rows, visible

    def _move_radio_collection_selection(self, direction: int) -> None:
        context = self._radio_manual_order_context()
        if context is None:
            self.announcer.say(
                "Ręczne przenoszenie działa w Bibliotece i Ulubionych Radia"
            )
            return
        scope, _view = context
        if self._radio_effective_sort_modes.get(scope) != SORT_CUSTOM:
            self.announcer.say(
                "Przenoszenie działa w kolejności własnej. Naciśnij Alt 3"
            )
            return
        if self._playlist_order_pending:
            self.announcer.say("Zmiana kolejności już trwa")
            return
        prepared = self._radio_collection_order_rows()
        if prepared is None:
            return
        rows, visible = prepared
        selected_ids = list(dict.fromkeys(row.item_id for row in rows))
        visible_ids = [row.item_id for row in visible]
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie działa. Kolejność nie została zmieniona")
            return

        selected_set = set(selected_ids)
        positions = [
            index for index, row in enumerate(visible)
            if row.item_id in selected_set
        ]
        adjacent_title = "sąsiedni element"
        if positions and positions[-1] - positions[0] + 1 == len(positions):
            adjacent_index = positions[0] - 1 if direction < 0 else positions[-1] + 1
            if 0 <= adjacent_index < len(visible):
                adjacent_title = visible[adjacent_index].title
        self._playlist_order_pending = True

        def work() -> dict:
            result = client.move_radio_collection_items(
                scope,
                selected_ids,
                visible_ids,
                direction,
            )
            return result if isinstance(result, dict) else {}

        def done(result: dict) -> None:
            self._playlist_order_pending = False
            status = str(result.get("status") or "invalid")
            if status != "moved":
                self.announcer.say({
                    "boundary": (
                        "To początek tej listy" if direction < 0
                        else "To koniec tej listy"
                    ),
                    "nonContiguous": (
                        "Do wspólnego przeniesienia zaznacz ciągły blok elementów"
                    ),
                }.get(status, "Nie można zmienić kolejności zaznaczenia"))
                return
            self._pending_radio_collection_move = None
            moved = (
                "Przeniesiono stację" if len(selected_ids) == 1
                else f"Przeniesiono stacje: {len(selected_ids)}"
            )
            message = (
                f"{moved} w górę, nad {adjacent_title}"
                if direction < 0
                else f"{moved} w dół, pod {adjacent_title}"
            )
            if self._radio_manual_order_context() == context:
                self._refresh_profile_view(
                    preferred_id=selected_ids[0],
                    selected_ids=selected_ids,
                    after_refresh=lambda: self.announcer.say(message),
                )
            else:
                self.announcer.say(message)

        def failed(error: Exception) -> None:
            self._playlist_order_pending = False
            self.announcer.say(f"Nie zmieniono kolejności stacji: {error}")

        self.runner.submit("radio-order-move", work, done, failed)

    def _cut_radio_collection_move(self) -> None:
        context = self._radio_manual_order_context()
        if context is None:
            return
        scope, _view = context
        if self._radio_effective_sort_modes.get(scope) != SORT_CUSTOM:
            self.announcer.say(
                "Przenoszenie działa w kolejności własnej. Naciśnij Alt 3"
            )
            return
        prepared = self._radio_collection_order_rows()
        if prepared is None:
            return
        rows, _visible = prepared
        item_ids = tuple(dict.fromkeys(row.item_id for row in rows))
        self._pending_radio_collection_move = (scope, item_ids)
        self._pending_internal_playlist_move = None
        self._clear_pending_external_moves()
        self.announcer.say(
            "Zaznaczono stację do przeniesienia. "
            "Wybierz miejsce i naciśnij Ctrl+V"
            if len(item_ids) == 1
            else f"Zaznaczono stacje do przeniesienia: {len(item_ids)}. "
                 "Wybierz miejsce i naciśnij Ctrl+V"
        )

    def _paste_radio_collection_move(self) -> None:
        context = self._radio_manual_order_context()
        if context is None:
            return
        scope, _view = context
        if self._radio_effective_sort_modes.get(scope) != SORT_CUSTOM:
            self.announcer.say(
                "Przenoszenie działa w kolejności własnej. Naciśnij Alt 3"
            )
            return
        pending = self._pending_radio_collection_move
        if pending is None or pending[0] != scope:
            self.announcer.say(
                "Najpierw zaznacz stację lub grupę skrótem Ctrl+X"
            )
            return
        if self._playlist_order_pending:
            self.announcer.say("Zmiana kolejności już trwa")
            return
        if self.filter_box.GetValue().strip():
            self.announcer.say(
                "Wyczyść filtr klawiszem Escape przed przenoszeniem stacji"
            )
            return
        target = self.navigator.session.model.selected_row
        if target is None or target.kind != "station" or not target.item_id:
            self.announcer.say(
                "Wybierz stację, przed którą chcesz przenieść zaznaczenie"
            )
            return
        visible = [
            row for row in self.navigator.session.model.rows
            if row.kind == "station" and row.item_id
        ]
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie działa. Kolejność nie została zmieniona")
            return
        selected_ids = list(pending[1])
        visible_ids = [row.item_id for row in visible]
        target_id = target.item_id
        target_title = target.title
        self._playlist_order_pending = True

        def work() -> dict:
            result = client.place_radio_collection_items_before(
                scope,
                selected_ids,
                visible_ids,
                target_id,
            )
            return result if isinstance(result, dict) else {}

        def done(result: dict) -> None:
            self._playlist_order_pending = False
            status = str(result.get("status") or "invalid")
            if status != "moved":
                self.announcer.say({
                    "targetInSelection": "Wybierz inną stację jako miejsce docelowe",
                    "targetMissing": "Nie znaleziono wskazanego miejsca docelowego",
                    "unchanged": "Stacje są już w tym miejscu",
                }.get(status, "Nie można przenieść zaznaczonych stacji"))
                return
            self._pending_radio_collection_move = None
            message = (
                f"Przeniesiono stację przed {target_title}"
                if len(selected_ids) == 1
                else f"Przeniesiono stacje: {len(selected_ids)}, przed {target_title}"
            )
            if self._radio_manual_order_context() == context:
                self._refresh_profile_view(
                    preferred_id=selected_ids[0],
                    selected_ids=selected_ids,
                    after_refresh=lambda: self.announcer.say(message),
                )
            else:
                self.announcer.say(message)

        def failed(error: Exception) -> None:
            self._playlist_order_pending = False
            self.announcer.say(f"Nie przeniesiono stacji: {error}")

        self.runner.submit("radio-order-place", work, done, failed)

    def _set_podcast_library_sort(self, action: Action) -> None:
        """Alt+1/2/3 on the source library, persisted only by AMC Test."""

        state = self.navigator.sessions[SessionId.PODCASTS]
        if (
            self.navigator.active is not SessionId.PODCASTS
            or state.view is not View.LIST
            or state.library_view is not LibraryView.PODCAST_LIBRARY
        ):
            self.announcer.say(
                "Sortowanie Alt+1, Alt+2 i Alt+3 działa w Bibliotece podcastów i kanałów"
            )
            return

        choices = {
            Action.SORT_PODCAST_LIBRARY_ADDED: (
                SORT_ADDED_NEWEST,
                "Ostatnio dodane na początku",
            ),
            Action.SORT_PODCAST_LIBRARY_ALPHABETICAL: (
                SORT_ALPHABETICAL,
                "Alfabetycznie",
            ),
            Action.SORT_PODCAST_LIBRARY_CUSTOM: (
                SORT_CUSTOM,
                "Kolejność własna",
            ),
        }
        choice = choices.get(action)
        if choice is None:
            return
        mode, label = choice
        previous_override = self.state.podcast_library_sort_mode
        previous_effective = self._podcast_library_sort_mode
        preferred_id = state.model.selected_id
        self.state.podcast_library_sort_mode = mode
        self._podcast_library_sort_mode = mode
        if not self._save_state():
            self.state.podcast_library_sort_mode = previous_override
            self._podcast_library_sort_mode = previous_effective
            self._refresh_menu_state()
            return
        self._refresh_menu_state()
        self._open_podcast_library(
            preferred_id=preferred_id,
            sort_label=label,
        )

