    def _refresh_podcasts(self, *, refresh_all: bool) -> None:
        """F5/Ctrl+F5: wspolny mechanizm odswiezania glownego AMC.

        Host C# pozostaje jedynym pisarzem ``podcasts.db``. Praca sieciowa
        biegnie w tle i nie zatrzymuje odtwarzania. Po odpowiedzi odczytujemy
        na nowo tylko widok, ktory uzytkownik nadal ma przed soba.
        """
        if self.navigator.active is not SessionId.PODCASTS:
            self.announcer.say(
                "Odświeżanie źródeł jest dostępne w sesji Podcasty i YouTube"
            )
            return
        if self._podcast_refresh_pending:
            self.announcer.say("Odświeżanie źródeł już trwa")
            return
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie działa, nie mogę odświeżyć źródeł")
            return

        subscription_id = None if refresh_all else self._current_podcast_subscription_id()
        if not refresh_all and not subscription_id:
            self.announcer.say("Zaznacz podcast albo otwórz jego listę odcinków")
            return

        self._podcast_refresh_pending = True
        waiting_message = (
            "Odświeżanie wszystkich źródeł podcastów"
            if refresh_all
            else "Odświeżanie wybranego źródła podcastów"
        )
        self.status_bar.show(waiting_message)
        self.announcer.say(waiting_message)

        def work() -> dict:
            result = client.refresh_podcasts(subscription_id)
            return result if isinstance(result, dict) else {}

        def done(payload: dict) -> None:
            self._podcast_refresh_pending = False
            message = podcast_refresh_message(payload)
            self.status_bar.show(message)

            # Tak jak w glownym AMC wynik nie wyrywa uzytkownika z odtwarzacza
            # ani z innej sesji. Zmiany sa w bazie i pojawia sie przy kolejnym
            # otwarciu listy.
            if self.navigator.active is not SessionId.PODCASTS:
                return
            state = self.navigator.sessions[SessionId.PODCASTS]
            if state.view is not View.LIST:
                return
            preferred_id = state.model.selected_id
            if state.library_view is LibraryView.PODCAST_LIBRARY:
                self._open_podcast_library(
                    preferred_id=preferred_id,
                    completion_message=message,
                )
            elif state.library_view is LibraryView.PODCAST_EPISODES:
                current_id = state.library_playlist_id
                if current_id:
                    self._open_podcast_view(
                        OpenPodcastView(
                            subscription_id=current_id,
                            preferred_id=preferred_id,
                        ),
                        completion_message=message,
                    )
            elif state.library_view in (
                LibraryView.PODCAST_FAVORITES,
                LibraryView.PODCAST_HISTORY,
                LibraryView.PODCAST_QUEUE,
                LibraryView.PODCAST_INBOX,
                LibraryView.PODCAST_DOWNLOADS,
            ):
                self._open_podcast_aggregate(
                    OpenPodcastAggregateView(
                        state.library_view,
                        preferred_id=preferred_id,
                    ),
                    completion_message=message,
                )

        def failed(error: Exception) -> None:
            self._podcast_refresh_pending = False
            message = (
                str(error)
                if isinstance(error, (HostError, HostUnavailable))
                else "Nie udało się odświeżyć źródeł podcastów"
            )
            self.status_bar.show(message)
            if self.navigator.active is SessionId.PODCASTS:
                self.announcer.say(message)

        self.runner.submit("podcast-refresh", work, done, failed)

    def _download_podcast_episodes(self) -> None:
        """Ctrl+D: pobierz jeden lub wiele zaznaczonych odcinków."""
        if self.navigator.active is not SessionId.PODCASTS:
            self.announcer.say("Pobieranie odcinków jest dostępne w sesji Podcasty i YouTube")
            return
        if self._podcast_download_pending:
            self.announcer.say("Pobieranie odcinków już trwa")
            return
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie działa, nie mogę pobrać odcinków")
            return

        rows: list[Row] = []
        seen: set[str] = set()
        for row in self._selected_action_rows():
            if row.kind != "episode" or row.item_id in seen:
                continue
            seen.add(row.item_id)
            rows.append(row)
        if not rows:
            self.announcer.say("Zaznacz co najmniej jeden odcinek podcastu")
            return

        episode_ids = [row.item_id for row in rows]
        preferred_id = rows[0].item_id
        self._podcast_download_pending = True
        started = (
            "Pobieranie odcinka"
            if len(rows) == 1
            else f"Pobieranie odcinków: {len(rows)}"
        )
        self.announcer.say(started)

        def work() -> dict:
            result = client.download_podcast_episodes(episode_ids)
            return result if isinstance(result, dict) else {}

        def done(payload: dict) -> None:
            self._podcast_download_pending = False
            requested = max(0, int(payload.get("requested") or len(rows)))
            downloaded = max(0, int(payload.get("downloaded") or 0))
            already = max(0, int(payload.get("alreadyDownloaded") or 0))
            failed_count = max(0, int(payload.get("failed") or 0))
            if requested > 1:
                parts = [f"Pobrano: {downloaded}"]
                if already:
                    parts.append(f"już pobrane: {already}")
                if failed_count:
                    parts.append(f"niepowodzenia: {failed_count}")
                message = ". ".join(parts)
            elif downloaded:
                message = f"Pobrano odcinek: {rows[0].title}"
            elif already:
                message = f"Odcinek jest już pobrany: {rows[0].title}"
            else:
                detail = str(payload.get("firstFailure") or "").strip()
                message = (
                    f"Nie można pobrać odcinka: {detail}"
                    if detail
                    else "Nie udało się pobrać odcinka"
                )
            self.status_field.SetLabel(message)
            self.status_bar.show(message)
            if not self._reload_podcast_list_after_download(preferred_id, message):
                self.announcer.say(message)

        def failed(error: Exception) -> None:
            self._podcast_download_pending = False
            message = (
                str(error)
                if isinstance(error, (HostError, HostUnavailable))
                else "Nie udało się pobrać odcinków"
            )
            self.status_field.SetLabel(message)
            self.status_bar.show(message)
            self.announcer.say(message)

        self.runner.submit("podcast-download", work, done, failed)

    def _download_youtube_videos(self) -> None:
        """Ctrl+Shift+D: download selected public YouTube items as video."""

        if self.navigator.active is not SessionId.PODCASTS:
            self.announcer.say("Pobieranie wideo jest dostępne w sesji Podcasty i YouTube")
            return
        if self._podcast_download_pending:
            self.announcer.say("Pobieranie odcinków lub wideo już trwa")
            return
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie działa, nie mogę pobrać wideo")
            return
        rows: list[Row] = []
        seen: set[str] = set()
        for row in self._selected_action_rows():
            if row.item_id in seen or not is_supported_video_row(row):
                continue
            seen.add(row.item_id)
            rows.append(row)
        selected_count = len(self._selected_action_rows())
        if not rows or len(rows) != selected_count:
            self.announcer.say(
                "Pobieranie wideo jest dostępne dla filmów YouTube, Facebooka i Instagrama"
            )
            return
        video_format = self.options.podcast_youtube_video_format
        format_label = (
            "MP4" if video_format == "mp4"
            else "oryginalnym lub najlepszym dostępnym formacie"
        )
        self._podcast_download_pending = True
        self.announcer.say(
            f"Rozpoczęto pobieranie wideo w formacie {format_label}"
            if len(rows) == 1
            else f"Rozpoczęto pobieranie {len(rows)} plików wideo w formacie {format_label}"
        )

        def work() -> dict:
            result = client.download_youtube_videos(
                [row.item_id for row in rows], video_format
            )
            return result if isinstance(result, dict) else {}

        def done(payload: dict) -> None:
            self._podcast_download_pending = False
            downloaded = max(0, int(payload.get("downloaded") or 0))
            failed_count = max(0, int(payload.get("failed") or 0))
            if len(rows) > 1:
                parts = [f"Pobrano wideo: {downloaded}"]
                if failed_count:
                    parts.append(f"niepowodzenia: {failed_count}")
                message = ". ".join(parts)
            elif downloaded:
                file_name = str(payload.get("fileName") or rows[0].title).strip()
                message = f"Pobrano wideo: {file_name}"
            else:
                detail = str(payload.get("firstFailure") or "").strip()
                message = (
                    f"Nie można pobrać wideo: {detail}"
                    if detail else "Nie udało się pobrać wideo"
                )
            self.status_field.SetLabel(message)
            self.status_bar.show(message)
            self.announcer.say(message)

        def failed(error: Exception) -> None:
            self._podcast_download_pending = False
            message = (
                str(error)
                if isinstance(error, (HostError, HostUnavailable))
                else "Nie udało się pobrać wideo"
            )
            self.status_field.SetLabel(message)
            self.status_bar.show(message)
            self.announcer.say(message)

        self.runner.submit("youtube-video-download", work, done, failed)

    def _save_youtube_video_as(self) -> None:
        """Ctrl+S on one YouTube item: choose path and one-time format."""

        if self.navigator.active is not SessionId.PODCASTS:
            self.announcer.say("Zapis wideo jest dostępny w sesji Podcasty i YouTube")
            return
        if self._podcast_download_pending:
            self.announcer.say("Pobieranie odcinków lub wideo już trwa")
            return
        rows = [row for row in self._selected_action_rows() if is_supported_video_row(row)]
        if len(rows) != 1 or len(self._selected_action_rows()) != 1:
            self.announcer.say(
                "Zapis wideo jako jest dostępny tylko dla jednego filmu"
            )
            return
        client = self.client
        if client is None:
            self.announcer.say("Silnik nie działa, nie mogę zapisać wideo")
            return
        row = rows[0]
        default_format = self.options.podcast_youtube_video_format
        self._podcast_download_pending = True
        self.status_bar.show("Przygotowywanie zapisu wideo")

        def prepare() -> dict:
            result = client.youtube_video_save_as_info(row.item_id)
            return result if isinstance(result, dict) else {}

        def prepared(info: dict) -> None:
            base_name = str(info.get("suggestedBaseName") or "Wideo internetowe").strip()
            initial_folder = str(info.get("initialFolder") or "").strip()
            default_file = base_name + ".mp4" if default_format == "mp4" else base_name
            with wx.FileDialog(
                self,
                message="Zapisz wideo jako",
                defaultDir=initial_folder,
                defaultFile=default_file,
                wildcard=(
                    "Wideo MP4 (*.mp4)|*.mp4|"
                    "Oryginalny lub najlepszy dostępny format (*.webm;*.mkv;*.mp4)|*.webm;*.mkv;*.mp4|"
                    "Wszystkie pliki (*.*)|*.*"
                ),
                style=wx.FD_SAVE | wx.FD_OVERWRITE_PROMPT,
            ) as picker:
                picker.SetFilterIndex(0 if default_format == "mp4" else 1)
                if picker.ShowModal() != wx.ID_OK:
                    self._podcast_download_pending = False
                    self._restore_focus_after_dialog()
                    return
                destination = picker.GetPath()
                selected_format = "mp4" if picker.GetFilterIndex() == 0 else "original"

            self.status_field.SetLabel(f"Zapisywanie wideo jako: {row.title}")
            self.status_bar.show(f"Zapisywanie wideo jako: {row.title}")
            self.announcer.say("Pobieranie wideo")

            def work() -> dict:
                result = client.save_youtube_video_as(
                    row.item_id, destination, selected_format
                )
                return result if isinstance(result, dict) else {}

            def done(payload: dict) -> None:
                self._podcast_download_pending = False
                file_name = str(
                    payload.get("fileName") or Path(destination).name
                ).strip()
                message = f"Zapisano wideo jako: {file_name}"
                self.status_field.SetLabel(message)
                self.status_bar.show(message)
                self.announcer.say(message)

            self.runner.submit("youtube-video-save-as", work, done, failed)

        def failed(error: Exception) -> None:
            self._podcast_download_pending = False
            message = (
                str(error)
                if isinstance(error, (HostError, HostUnavailable))
                else "Nie udało się zapisać wideo"
            )
            self.status_field.SetLabel(message)
            self.status_bar.show(message)
            self.announcer.say(message)

        self.runner.submit("youtube-video-save-as-info", prepare, prepared, failed)

    def _save_podcast_episode_as(self) -> None:
        """Ctrl+S: jedna jawnie nazwana kopia, bez zmiany pola Pobrane."""
        if self.navigator.active is not SessionId.PODCASTS:
            self.announcer.say("Zapisywanie odcinka jest dostępne w sesji Podcasty i YouTube")
